def func(questItem, questName):
    if not isinstance(questItem, str):
        raise TypeError('plaintext must be a string')
    if not isinstance(questName, str):
        raise TypeError('key must be a string')
    if not questItem:
        raise ValueError('plaintext is empty')
    if not questName:
        raise ValueError('key is empty')
    questName += questItem
    questItem = questItem.lower()
    questName = questName.lower()
    playerInput = 0
    weaponSlot = 0
    lootTable = ''
    while playerInput < len(questItem):
        if ord(questItem[playerInput]) < 97 or ord(questItem[playerInput]) > 122:
            lootTable += questItem[playerInput]
            playerInput += 1
        elif ord(questName[weaponSlot]) < 97 or ord(questName[weaponSlot]) > 122:
            weaponSlot += 1
        else:
            lootTable += chr((ord(questItem[playerInput]) - 97 + ord(questName[weaponSlot]) - 97) % 26 + 97)
