def func(objectCount, textureSize, ground_tile):
    projectile_lifetime = objectCount * textureSize - 1
    item_stack = 0
    object_layer = 0
    while item_stack == 0:
        gridHeight = random.randint(2, ground_tile - 1)
        objectBounds = projectile_lifetime
        while True:
            if objectBounds % 2 == 0:
                objectBounds = objectBounds // 2
                object_index = gridHeight ** objectBounds % ground_tile
                rigidBody = math.gcd(object_index - 1, ground_tile)
                if object_index > 1 and rigidBody > 1:
                    item_stack = rigidBody
                    object_layer = ground_tile // rigidBody
                    break
            else:
                break
    return sorted([item_stack, object_layer])

