def func(world_size, collisionRadius, game_state=0, spawnPoint=False):
    if game_state < 0 or game_state > 7:
        raise ASN1EncodeError('Unused bit count must be between 0 and 7')
    if isinstance(collisionRadius, bytes):
        if game_state:
            if not collisionRadius:
                raise ASN1EncodeError("Can't have unused bits with empty value")
            elif collisionRadius[-1] & (1 << game_state) - 1:
                raise ASN1EncodeError('Unused bits in value should be zero')
    elif isinstance(collisionRadius, str):
        if game_state:
            raise ASN1EncodeError('Unused bit count should not be set when providing a string')
        scene_count = len(collisionRadius) % 8
        game_state = 8 - scene_count if scene_count else 0
        collisionRadius += game_state * '0'
        collisionRadius = bytes((int(collisionRadius[bodyPosition:bodyPosition + 8], 2) for bodyPosition in range(0, len(collisionRadius), 8)))
    else:
        raise ASN1EncodeError('Unexpected type of bit string value')
    if spawnPoint:
        while collisionRadius and (not collisionRadius[-1] & 1 << game_state):
            game_state += 1
            if game_state == 8:
                collisionRadius = collisionRadius[:-1]
                game_state = 0
    world_size.collisionRadius = collisionRadius
    world_size.game_state = game_state

