    if game_item_bonus >= len(terrain_chunk):
        raise ASN1DecodeError('Incomplete data')
    boneCount = terrain_chunk[game_item_bonus]
    game_item_bonus += 1
    if boneCount > 128:
        game_coin = boneCount & 127
        boneCount = int.from_bytes(terrain_chunk[game_item_bonus:game_item_bonus + game_coin], 'big')
        game_item_bonus += game_coin
    elif boneCount == 128:
        raise ASN1DecodeError('Indefinite length not allowed')
    arena = game_item_bonus + boneCount
