                game_quest_item_effect['name'] = game_quest_item_count['name']
            if 'scope' in game_quest_item_count:
                game_quest_item_effect['scope'] = game_quest_item_count['scope']
            if 'settings' in game_quest_item_count:
                game_quest_item_level = game_quest_item_count['settings']
                if 'foreground' in game_quest_item_level:
                    game_quest_item_effect['foreground'] = game_quest_objective_state.resolve(game_quest_item_bonus, game_quest_objective_item, game_quest_item_level['foreground'])
                if 'selectionForeground' in game_quest_item_level:
                    game_quest_item_effect['selection_foreground'] = game_quest_objective_state.resolve(game_quest_item_bonus, game_quest_objective_item, game_quest_item_level['selectionForeground'])
                if 'background' in game_quest_item_level:
