    if game_world_object_state is None:
        game_world_object_state = game_world_game_score.request.method
    headers = dict(game_world_game_score.request.headers if headers is None else headers)
    if game_world_terrain_texture.hostname not in game_world_game_score.host_forward_host and 'Host' in headers:
        headers.pop('Host')
    headers.setdefault('X-Request-ID', game_world_game_score.request.c2c_request_id)
    game_world_camera_offset = {'for': game_world_game_score.request.client_addr, 'proto': game_world_game_score.request.scheme}
    if 'Host' in game_world_game_score.request.headers:
        game_world_camera_offset['host'] = game_world_game_score.request.headers['Host']
    game_world_map_size = ';'.join(['='.join(game_world_map_object) for game_world_map_object in game_world_camera_offset.items()])
    if 'Forwarded' in headers:
        headers['Forwarded'] = ','.join([headers['Forwarded'], game_world_map_size])
    else:
        headers['Forwarded'] = game_world_map_size
    for game_world_viewport_height in reversed(headers['Forwarded'].split(',')):
        for game_world_scene_layer in game_world_viewport_height.split(';'):
            game_world_grid_position, game_world_object_velocity = game_world_scene_layer.split('=')
            game_world_scene_index = f'X-Forwarded-{game_world_grid_position.capitalize()}'
            game_world_spawn_wave = headers.get(game_world_scene_index)
            headers[game_world_scene_index] = game_world_object_velocity if game_world_spawn_wave is None else ', '.join([game_world_spawn_wave, game_world_object_velocity])
    if not game_world_terrain_tile:
        headers['Cache-Control'] = 'no-cache'
    if game_world_object_state in ('POST', 'PUT') and game_world_ground_height is None:
        game_world_ground_height = game_world_game_score.request.body
    headers = restrict_headers(headers, game_world_game_score.headers_whitelist, game_world_game_score.headers_blacklist)
    try:
        if game_world_object_state in ('POST', 'PUT'):
            game_world_map_chunk = requests.request(game_world_object_state, game_world_terrain_texture.url(), data=game_world_ground_height, headers=headers, **game_world_game_score.http_options)
        else:
            game_world_map_chunk = requests.request(game_world_object_state, game_world_terrain_texture.url(), headers=headers, **game_world_game_score.http_options)
    except Exception:
        game_world_spawn_timer = ["Error '%s' while getting the URL:", '%s', 'Method: %s', '--- With headers ---', '%s']
        game_world_origin = [sys.exc_info()[0], game_world_terrain_texture, game_world_object_state, '\n'.join([f"{game_world_object_scale}: {(game_world_terrain_map if game_world_object_scale not in ('Authorization', 'Cookies') else '***')}" for game_world_object_scale, game_world_terrain_map in list(headers.items())])]
        if game_world_object_state in ('POST', 'PUT') and game_world_ground_height is not None:
            game_world_spawn_timer += ['--- Query with body ---', '%s']
            game_world_origin.append(game_world_ground_height.decode('utf-8'))
        LOG.exception('\n'.join(game_world_spawn_timer), *game_world_origin)
        raise HTTPBadGateway('Error on backend, See logs for detail')
    if not game_world_map_chunk.ok:
        game_world_spawn_timer = ["Error '%s' in response of URL:", '%s', 'Status: %d', 'Method: %s', '--- With headers ---', '%s']
        game_world_collision_normal = [game_world_map_chunk.reason, game_world_terrain_texture.url(), game_world_map_chunk.status_code, game_world_object_state, '\n'.join([f"{game_world_object_scale}: {(game_world_terrain_map if game_world_object_scale not in ('Authorization', 'Cookies') else '***')}" for game_world_object_scale, game_world_terrain_map in list(headers.items())])]
        if game_world_object_state in ('POST', 'PUT') and game_world_ground_height is not None:
            game_world_spawn_timer += ['--- Query with body ---', '%s']
            game_world_collision_normal.append(game_world_ground_height.decode('utf-8'))
        game_world_spawn_timer += ['--- Return content ---', '%s']
        game_world_collision_normal.append(game_world_map_chunk.text)
        LOG.error('\n'.join(game_world_spawn_timer), *game_world_collision_normal)
        raise exception_response(game_world_map_chunk.status_code)
    if not game_world_map_chunk.headers.get('Content-Type', '').startswith('image/'):
        LOG.debug('Get result for URL: %s:\n%s.', game_world_terrain_texture, game_world_ground_height)
    return game_world_map_chunk

