async def func(game_guild, addr, port, family=socket.AF_INET, ssl=None, reconnect=True, objectFriction=False):
    logger.debug(f'Starting to connect to {addr}:{port}')
    await game_guild._disconnect_peers()
    if not objectFriction:
        game_particle_count = game_guild._backoff * BACKOFF_JITTER
        game_mana_bar = max(0, game_guild._backoff - game_particle_count)
        game_mesh_position = game_guild._backoff + game_particle_count
        game_spawn_point = random.uniform(game_mana_bar, game_mesh_position)
        if game_spawn_point:
            logger.info(f'Waiting {game_spawn_point:.1f} seconds before connection attempt')
            try:
                await asyncio.sleep(game_spawn_point)
            except asyncio.CancelledError:
                return
        game_guild._backoff = min(game_guild._backoff_maximum, game_guild._backoff + game_guild._backoff / 2 + 1)
    atlas_index = None
    try:
        backpackSlot, atlas_index = await game_guild.loop.create_connection(game_guild._protocol_factory, host=addr, port=port, ssl=ssl, family=family)
        game_guild._backoff = 0
        game_guild._connect_task = None
        game_guild._running = True
        try:
            if game_guild._on_started_handler:
                game_guild._on_started_handler(game_guild)
        except Exception as exc:
            logger.exception('Error in on_started callback method')
    except (ConnectionRefusedError, OSError) as exc:
        logger.error(f'Connection to {addr}:{port} was refused')
    except Exception as exc:
        logger.error(f'Unexpected error connecting to {addr}:{port}', exc_info=exc)
    if atlas_index is None and reconnect:
        game_guild._connect_task = game_guild.loop.create_task(game_guild._connect(addr=addr, port=port, family=family, ssl=ssl, reconnect=reconnect))
    else:
        game_guild._backoff = 0

def func(criticalChance, our_address, privkey, game_item_rarity, token_network_address, one_to_n_address, chain_id, monster, gridCell, sprite_bounds):
    game_combat_timer = criticalChance['pathfinding_max_paths']
    url = criticalChance['pathfinding_service_address']
    payload = {'from': to_checksum_address(monster), 'to': to_checksum_address(gridCell), 'value': sprite_bounds, 'max_paths': game_combat_timer}
    offered_fee = criticalChance.get('pathfinding_fee', criticalChance['pathfinding_max_fee'])
    scrap_existing_iou = False
    for tileWidth in reversed(range(MAX_PATHS_QUERY_ATTEMPTS)):
        payload['iou'] = create_current_iou(config=criticalChance, token_network_address=token_network_address, one_to_n_address=one_to_n_address, our_address=our_address, privkey=privkey, chain_id=chain_id, block_number=game_item_rarity, offered_fee=offered_fee, scrap_existing_iou=scrap_existing_iou)
        try:
            return post_pfs_paths(url=url, token_network_address=token_network_address, payload=payload)
        except ServiceRequestIOURejected as error:
            projectileDamage = error.error_code
            if tileWidth == 0 or projectileDamage in (PFSError.WRONG_IOU_RECIPIENT, PFSError.DEPOSIT_TOO_LOW):
                raise
            elif projectileDamage in (PFSError.IOU_ALREADY_CLAIMED, PFSError.IOU_EXPIRED_TOO_EARLY):
                scrap_existing_iou = True
            elif projectileDamage == PFSError.INSUFFICIENT_SERVICE_PAYMENT:
                if offered_fee < criticalChance['pathfinding_max_fee']:
                    offered_fee = criticalChance['pathfinding_max_fee']
                else:
                    raise
            log.info(f'PFS rejected our IOU, reason: {error}. Attempting again.')
    return (list(), None)

