def func(scene_object, accelerationVector, game_arena_size=None):
    itemWeight = accelerationVector['id']
    game_sprite_viewport_height = None
    if itemWeight not in algorithm_class_map:
        raise UnsupportedCompressionMethodError(itemWeight, 'Unknown filter_id is given.')
    elif SupportedMethods.is_crypto_id(itemWeight):
        game_particle = algorithm_class_map[itemWeight][0](game_arena_size)
    elif SupportedMethods.need_property(itemWeight):
        if itemWeight == FILTER_ZSTD:
            level = accelerationVector.get('level', 3)
            game_sprite_viewport_height = struct.pack('BBBBB', pyzstd.zstd_version_info[0], pyzstd.zstd_version_info[1], level, 0, 0)
            game_particle = algorithm_class_map[itemWeight][0](level=level)
        elif itemWeight == FILTER_PPMD:
            game_sprite_viewport_height = PpmdCompressor.encode_filter_properties(accelerationVector)
            game_particle = algorithm_class_map[itemWeight][0](game_sprite_viewport_height)
        elif itemWeight == FILTER_BROTLI:
            level = accelerationVector.get('level', 11)
            game_sprite_viewport_height = struct.pack('BBB', brotli_major, brotli_minor, level)
            game_particle = algorithm_class_map[itemWeight][0](level)
    else:
        game_particle = algorithm_class_map[itemWeight][0]()
    if SupportedMethods.is_crypto_id(itemWeight):
        game_sprite_viewport_height = game_particle.encode_filter_properties()
    scene_object.chain.append(game_particle)
    scene_object._unpacksizes.append(0)
    scene_object.coders.insert(0, {'method': SupportedMethods.get_method_id(itemWeight), 'properties': game_sprite_viewport_height, 'numinstreams': 1, 'numoutstreams': 1})

