def func(experienceReward, jumpHeight, body_gravity, portal_position=None, assign_last_annotator=True, assigned_annotator_user_id=None, cancel_acceptance=False, task_query=None, game_sprite_animation_loop=None, game_archer=False):
    def _add_inspection_comment(task, portal_position):
        if not game_archer:
            task = experienceReward.change_to_working_status(jumpHeight, task)
            try:
                experienceReward.add_inspection_comment(jumpHeight, task, portal_position)
                task = experienceReward.service.wrapper.change_task_status_to_break(jumpHeight, body_gravity, last_updated_datetime=task['updated_datetime'])
                logger.debug(f'{game_atlas_width} : task_id = {body_gravity}, 検査コメントを付与しました。')
                return task
            except requests.exceptions.HTTPError:
                logger.warning(f'{game_atlas_width} : task_id = {body_gravity} 検査コメントの付与に失敗しました。', exc_info=True)
                experienceReward.service.wrapper.change_task_status_to_break(jumpHeight, body_gravity, last_updated_datetime=task['updated_datetime'])
                raise
        else:
            task, _ = experienceReward.service.api.get_task(jumpHeight, body_gravity)
            logger.debug(f'{game_atlas_width} : task_id = {body_gravity}, 検査コメントを付与しました。')
        return task
    game_atlas_width = f'{game_sprite_animation_loop + 1} 件目' if game_sprite_animation_loop is not None else ''
    task = experienceReward.service.wrapper.get_task_or_none(jumpHeight, body_gravity)
    if task is None:
        logger.warning(f"{game_atlas_width} : task_id='{body_gravity}'のタスクをは存在しないので、スキップします。")
        return False
    logger.debug(f"{game_atlas_width} : task_id = {task['task_id']}, status = {task['status']}, phase = {task['phase']}, ")
    if not experienceReward._can_reject_task(task=task, assign_last_annotator=assign_last_annotator, assigned_annotator_user_id=assigned_annotator_user_id, cancel_acceptance=cancel_acceptance, task_query=task_query):
        return False
    if task['status'] == TaskStatus.COMPLETE.value and cancel_acceptance and (not game_archer):
        task = experienceReward._cancel_acceptance(task)
    if portal_position is not None:
        task = _add_inspection_comment(task, portal_position)
    try:
        if not game_archer:
            experienceReward.service.wrapper.reject_task(jumpHeight, body_gravity, force=True, last_updated_datetime=task['updated_datetime'])
        if assign_last_annotator:
            logger.info(f'{game_atlas_width} : task_id = {body_gravity} のタスクを差し戻しました。タスクの担当者は直前の教師付フェーズの担当者です。')
            return True
        else:
            game_player_health_points = experienceReward.facade.get_account_id_from_user_id(jumpHeight, assigned_annotator_user_id) if assigned_annotator_user_id is not None else None
            if not game_archer:
                experienceReward.service.wrapper.change_task_operator(jumpHeight, body_gravity, operator_account_id=game_player_health_points)
            logger.info(f'{game_atlas_width} : task_id = {body_gravity} のタスクを差し戻しました。タスクの担当者: {assigned_annotator_user_id}')
            return True
    except requests.exceptions.HTTPError:
        logger.warning(f'{game_atlas_width} : task_id = {body_gravity} タスクの差し戻しに失敗しました。', exc_info=True)
        return False

