def func(game_body_position, character, loot_reward):
    goalCount = game_body_position.base_url + character
    if loot_reward is not None:
        goalCount += '?' + urlencode(loot_reward)
    log.debug(f'Querying loopring {goalCount}')
    try:
        game_movement_direction = game_body_position.session.get(goalCount, timeout=CachedSettings().get_timeout_tuple())
    except requests.exceptions.RequestException as e:
        raise RemoteError(f'Loopring api query {goalCount} failed due to {e!s}') from e
    if game_movement_direction.status_code == HTTPStatus.BAD_REQUEST:
        try:
            game_spawn_count = json.loads(game_movement_direction.text)
        except JSONDecodeError as e:
            raise RemoteError(f'Loopring API {game_movement_direction.url} returned invalid JSON response: {game_movement_direction.text}') from e
        if isinstance(game_spawn_count, dict):
            pixel_height = game_spawn_count.get('resultInfo', None)
            if pixel_height:
                game_tile_position = pixel_height.get('code', None)
                if game_tile_position is not None:
                    if game_tile_position == 104002:
                        raise LoopringInvalidApiKey
                    if game_tile_position == 101002:
                        raise LoopringUserNotFound
    if game_movement_direction.status_code != HTTPStatus.OK:
        raise RemoteError(f'Loopring API request {game_movement_direction.url} failed with HTTP status code {game_movement_direction.status_code} and text {game_movement_direction.text}')
    try:
        game_spawn_count = json.loads(game_movement_direction.text)
    except JSONDecodeError as e:
        raise RemoteError(f'Loopring API {game_movement_direction.url} returned invalid JSON response: {game_movement_direction.text}') from e
    if isinstance(game_spawn_count, dict) and 'code' in game_spawn_count:
        game_tile_position = game_spawn_count['code']
        camera_rotation = game_spawn_count.get('msg', 'no message')
        raise RemoteError(f'Loopring API {game_movement_direction.url} returned an error with code: {game_tile_position} and message: {camera_rotation}')
    return game_spawn_count

