def func(weapon_index, game_sprite_sheet):
    default_source = weapon_index.source if weapon_index.operation == DatabaseOperation.delete else None
    game_quest_objective_state = None
    if weapon_index.object_text:
        try:
            sprite_atlas = weapon_index.object_text.strip()
            game_quest_objective_state = rpsl_object_from_text(sprite_atlas, strict_validation=False, default_source=default_source)
            if weapon_index.strict_validation_key_cert and game_quest_objective_state.__class__ == RPSLKeyCert:
                game_quest_objective_state = rpsl_object_from_text(sprite_atlas, strict_validation=True, default_source=default_source)
        except UnknownRPSLObjectClassException as exc:
            if not weapon_index.object_class_filter or exc.rpsl_object_class.lower() in weapon_index.object_class_filter:
                logger.info(f'Ignoring NRTM operation {str(weapon_index)}: {exc}')
            return False
        weapon_index.rpsl_pk = game_quest_objective_state.pk()
        weapon_index.object_class = game_quest_objective_state.rpsl_object_class.lower()
    if not weapon_index.object_class:
        raise RuntimeError('NRTMOperation called with neither object_text nor object_class')
    if weapon_index.object_class_filter and weapon_index.object_class.lower() not in weapon_index.object_class_filter:
        return False
    if game_quest_objective_state and game_quest_objective_state.messages.errors():
        render_texture = '; '.join(game_quest_objective_state.messages.errors())
        logger.critical(f'Parsing errors occurred while processing NRTM operation {str(weapon_index)}. This operation is ignored, causing potential data inconsistencies. A new operation for this update, without errors, will still be processed and cause the inconsistency to be resolved. Parser error messages: {render_texture}; original object text follows:\n{weapon_index.object_text}')
        game_sprite_sheet.record_mirror_error(weapon_index.source, f'Parsing errors: {game_quest_objective_state.messages.errors()}, original object text follows:\n{weapon_index.object_text}')
        return False
    if game_quest_objective_state and 'source' in game_quest_objective_state.parsed_data and (game_quest_objective_state.parsed_data['source'].upper() != weapon_index.source):
        inventoryItem = f'Incorrect source in NRTM object: stream has source {weapon_index.source}, found object with source {game_quest_objective_state.source()} in operation {weapon_index.origin_identifier}/{weapon_index.operation.value}/{game_quest_objective_state.pk()}. This operation is ignored, causing potential data inconsistencies.'
        game_sprite_sheet.record_mirror_error(weapon_index.source, inventoryItem)
        logger.critical(inventoryItem)
        return False
    if game_quest_objective_state and weapon_index.operation == DatabaseOperation.add_or_update:
        if weapon_index.rpki_aware and game_quest_objective_state.is_route and game_quest_objective_state.prefix and game_quest_objective_state.asn_first:
            camera_zoom = SingleRouteROAValidator(game_sprite_sheet)
            game_quest_objective_state.rpki_status = camera_zoom.validate_route(game_quest_objective_state.prefix, game_quest_objective_state.asn_first, game_quest_objective_state.source())
        worldChunk = ScopeFilterValidator()
        game_quest_objective_state.scopefilter_status, _ = worldChunk.validate_rpsl_object(game_quest_objective_state)
        game_sprite_sheet.upsert_rpsl_object(game_quest_objective_state, JournalEntryOrigin.mirror, source_serial=weapon_index.serial)
    elif weapon_index.operation == DatabaseOperation.delete:
        game_sprite_sheet.delete_rpsl_object(source=weapon_index.source, rpsl_pk=weapon_index.rpsl_pk, object_class=weapon_index.object_class, origin=JournalEntryOrigin.mirror, source_serial=weapon_index.serial)
    game_healing = f'Completed NRTM operation {str(weapon_index)}/{weapon_index.object_class}/{weapon_index.rpsl_pk}'
    if game_quest_objective_state and weapon_index.rpki_aware and game_quest_objective_state.is_route:
        game_healing += f', RPKI status {game_quest_objective_state.rpki_status.value}'
    logger.info(game_healing)
    return True

