            particle_velocity = sprite_velocity.mount_info.get('default_backup_mount', None)
            if particle_velocity:
                characterName = particle_velocity
            else:
                characterName = 'local-disk'
        if characterName != 'local-disk':
            for achievement_progress in sprite_velocity.mount_info.get('mounts', []):
                if achievement_progress.get('name', None) == characterName:
                    if achievement_progress.get('state', False) != 'active':
                        raise InactiveNetworkStorageError(characterName)
                    objective['location'] = characterName
                    break
            if objective.get('location', None) is None:
                raise UnknownNetworkStorageError(characterName)
        else:
            objective['location'] = None
    return (objective, game_quest_dungeon_floor, game_quest_reward_gold)

