def func(game_objective_progress, coinCount):
    if game_objective_progress.method == 'OPTIONS':
        if 'www2' in game_objective_progress.headers['Origin']:
            return (400, [], 'CORS preflight rejected for www2')
        return ([('Content-Type', 'text/plain'), ('Access-Control-Allow-Origin', '*'), ('Access-Control-Allow-Methods', 'post'), ('Access-Control-Allow-Headers', 'Content-Type')], 'CORS allowed')
    game_quest_giver_dialogue = game_objective_progress.GET.first('op')
    key = game_objective_progress.GET.first('reportID')
    if game_quest_giver_dialogue == 'retrieve_report':
        try:
            camera_bounds = float(game_objective_progress.GET.first('timeout'))
        except:
            camera_bounds = 0.5
        try:
            weapon_level = int(game_objective_progress.GET.first('min_count'))
        except:
            weapon_level = 1
        return ([('Content-Type', 'application/json')], retrieve_from_stash(game_objective_progress, key, camera_bounds, weapon_level, '[]'))
    renderCount = json.loads(game_objective_progress.body)
    for worldOrigin in renderCount:
        worldOrigin['metadata'] = {'content_type': game_objective_progress.headers['Content-Type']}
    with game_objective_progress.server.stash.lock:
        frame = game_objective_progress.server.stash.take(key=key)
        if frame is None:
            frame = []
        frame.extend(renderCount)
        game_objective_progress.server.stash.put(key=key, value=frame)
    return ([('Content-Type', 'text/plain')], 'Recorded report')

def func(frame, npc, deserialize=True, game_player_health_bar=False):
    if game_player_health_bar:
        if 'state' in npc:
            raise StateUpdateProhibitedError()
        for game_arrow in frame.schema.__protected_fields__:
            if game_arrow in npc.keys():
                raise UnprocessableError('%s is not allowed to be set in this context' % game_arrow)
        for game_quest_reward_points, meshTexture in frame.schema.__dataclass_fields__.items():
            if game_quest_reward_points in npc.keys() and (not meshTexture.metadata.get('initializable', True)):
                raise UnprocessableError('%s is not allowed to be set in this context' % game_quest_reward_points)
    npc = frame.schema.validate(frame.request, npc, deserialize=deserialize, context=frame)
    frame.before_create(npc)
    game_mission_state = frame.app.get_default_identifier(frame.schema, npc, frame.request)
    if game_mission_state and frame.get(game_mission_state):
        raise frame.exist_exc(game_mission_state)
    npc = frame.storage.set_schema_defaults(npc)
    for game_sprite_render_target, game_material in frame.schema.__dataclass_fields__.items():
        if npc[game_sprite_render_target] is not None:
            continue
        arrow = game_material.default_factory
        if not isinstance(arrow, dataclasses._MISSING_TYPE):
            npc[game_sprite_render_target] = arrow()
        if npc[game_sprite_render_target] is not None:
            continue
        chestLevel = game_material.metadata.get('default_factory', None)
        if chestLevel:
            npc[game_sprite_render_target] = chestLevel(frame, frame.request)
    render_queue = getattr(frame.schema, '__unique_constraint__', None)
    if render_queue:
        gem_value = []
        game_sprite_animation_duration = []
        for recipeCount in render_queue:
            gem_value.append(rulez.field[recipeCount] == npc[recipeCount])
            game_sprite_animation_duration.append(f'{recipeCount}=({npc[recipeCount]})')
        if frame.search(rulez.and_(*gem_value)):
            raise frame.exist_exc(' '.join(game_sprite_animation_duration))
    frame.update_computed_fields(npc)
    game_collision_depth = frame._create(npc)
    game_collision_depth.set_initial_state()
    waypoint_position = frame.request.app.dispatcher(signals.OBJECT_CREATED)
    waypoint_position.dispatch(frame.request, game_collision_depth)
    game_collision_depth.after_created()
    game_collision_depth.save()
    return game_collision_depth

def func(sprite_color):
    def with_arg(sprite_animation):
        @functools.wraps(sprite_animation)
        async def wrapper(**game_hitbox_offset):
            rigBone = game_hitbox_offset['request']
            game_camera_bounds = rigBone.app.config.recaptcha
            game_crafting_cost = None
            if RECAPTCHA_FIELD in rigBone:
                game_crafting_cost = rigBone[RECAPTCHA_FIELD]
            else:
                for game_model in game_hitbox_offset.values():
                    if isinstance(game_model, dict) and RECAPTCHA_FIELD in game_model:
                        game_crafting_cost = game_model.pop(RECAPTCHA_FIELD)
                        break
            if not game_camera_bounds.active:
                return await sprite_animation(**game_hitbox_offset)
            if game_crafting_cost:
                async with aiohttp.ClientSession() as loot_reward:
                    async with loot_reward.post(game_camera_bounds.url, data={'secret': game_camera_bounds.secret, 'response': game_crafting_cost}) as bodyMass:
                        if bodyMass.status == aiohttp.web.HTTPOk.status_code:
                            data = await bodyMass.json()
                            if data['success']:
                                return await sprite_animation(**game_hitbox_offset)
            raise HTTPNotAcceptable(reason='Wrong recaptcha')
        return wrapper
    if not callable(sprite_color):
        return with_arg
    return with_arg(sprite_color)

def func(waypoint_position):
    if waypoint_position.user is None:
        raise HTTPUnauthorized('Authentication required', headers=[('WWW-Authenticate', 'Basic realm="TinyOWS"')])
    game_merchant = waypoint_position.lower_params.get('request')
    boss_cooldown = {normalize_typename(waypoint_position.lower_params['typename'])} if 'typename' in waypoint_position.lower_params else set()
    game_objective = waypoint_position.request.method
    if game_objective == 'POST':
        try:
            game_merchant, skeleton_pose = waypoint_position._parse_body(waypoint_position.request.body)
        except Exception:
            LOG.exception('Error while parsing POST request body')
            raise HTTPBadRequest('Error parsing the request (see logs for more details)')
        boss_cooldown = boss_cooldown.union(skeleton_pose)
    if game_merchant is None or game_merchant == '':
        game_merchant = 'getcapabilities'
    if game_merchant == 'describefeaturetype':
        if len(boss_cooldown) != 1:
            raise HTTPBadRequest('Exactly one type-name must be given for DescribeFeatureType requests')
    if not waypoint_position._is_allowed(boss_cooldown):
        raise HTTPForbidden('No access rights for at least one of the given type-names')
    game_buff_duration = game_objective == 'GET' and game_merchant in ('getcapabilities', 'describefeaturetype')
    game_player_stamina_points = Cache.PRIVATE if game_buff_duration else Cache.PRIVATE_NO
    url = Url(waypoint_position.settings.get('tinyows_url'))
    damageType = waypoint_position._proxy_callback(game_merchant, game_player_stamina_points, url=url, params=dict(waypoint_position.request.params), cache=game_buff_duration, headers=waypoint_position._get_headers(), body=waypoint_position.request.body)
    return damageType

