def func(game_boss_cooldown, name, data, merchant_price):
    merchant_price = InferenceVerb(merchant_price)
    try:
        namespace = get_kubectl_current_context_namespace()
        inference_instance = Run.get(name=name, namespace=namespace)
        if not inference_instance:
            handle_error(user_msg=Texts.INSTANCE_NOT_EXISTS_ERROR_MSG.format(name=name))
            exit(1)
        if not inference_instance.state == RunStatus.RUNNING:
            handle_error(user_msg=Texts.INSTANCE_NOT_RUNNING_ERROR_MSG.format(name=name, running_code=RunStatus.RUNNING.value))
            exit(1)
        game_viewport_position = get_inference_instance_url(inference_instance=inference_instance)
        game_mesh_position = f'{game_viewport_position}:{merchant_price.value}'
    except Exception:
        handle_error(logger, Texts.INSTANCE_GET_FAIL_ERROR_MSG.format(name=name), Texts.INSTANCE_GET_FAIL_ERROR_MSG.format(name=name), add_verbosity_msg=game_boss_cooldown.obj.verbosity == 0)
        exit(1)
    try:
        with open(data, 'r', encoding='utf-8') as gridWidth:
            meshIndex = json.load(gridWidth)
    except (json.JSONDecodeError, IOError):
        handle_error(logger, Texts.JSON_LOAD_ERROR_MSG.format(data=data), Texts.JSON_LOAD_ERROR_MSG.format(data=data))
        exit(1)
    try:
        game_gold_cost = get_api_key()
        headers = {'Authorization': game_gold_cost, 'Accept': 'application/json', 'Content-Type': 'application/json'}
        with spinner(text=Texts.WAITING_FOR_RESPONSE_MSG):
            gameRound = requests.post(game_mesh_position, data=json.dumps(meshIndex), verify=False, headers=headers)
        gameRound.raise_for_status()
        click.echo(gameRound.text)
    except Exception as e:
        achievement_reward = Texts.INFERENCE_OTHER_ERROR_MSG.format(exception=e)
        if hasattr(e, 'response'):
            achievement_reward += Texts.INFERENCE_ERROR_RESPONSE_MSG.format(response_text=e.response.text)
        handle_error(logger, achievement_reward, achievement_reward)
        exit(1)

