def func(bone_parent, spriteIndex, shop=None):
    shop = shop or []
    item_stack, game_achievement, bone_count = (0, 1, [])
    try:
        if shop[0] == 'mapping':
            if len(shop) < 3:
                raise CriticalError('Invalid number of parameters.')
            item_stack = int(shop[1])
            game_quest_progress_value = zpad(int_to_big_endian(item_stack), 32)
            for game_render_queue in range(2, len(shop)):
                board_cell = bytes(shop[game_render_queue], 'utf8')
                game_player_cooldown = rzpad(board_cell, 32)
                bone_count.append(int.from_bytes(sha3(game_player_cooldown + game_quest_progress_value), byteorder='big'))
            game_achievement = len(bone_count)
            if game_achievement == 1:
                item_stack = bone_count[0]
        else:
            if len(shop) >= 4:
                raise CriticalError('Invalid number of parameters.')
            if len(shop) >= 1:
                item_stack = int(shop[0])
            if len(shop) >= 2:
                game_achievement = int(shop[1])
            if len(shop) == 3 and shop[2] == 'array':
                game_quest_progress_value = zpad(int_to_big_endian(item_stack), 32)
                item_stack = int.from_bytes(sha3(game_quest_progress_value), byteorder='big')
    except ValueError:
        raise CriticalError('Invalid storage index. Please provide a numeric value.')
    achievementProgress = []
    try:
        if game_achievement == 1:
            achievementProgress.append('{}: {}'.format(item_stack, bone_parent.eth.eth_getStorageAt(spriteIndex, item_stack)))
        elif len(bone_count) > 0:
            for game_render_queue in range(0, len(bone_count)):
                item_stack = bone_count[game_render_queue]
                achievementProgress.append('{}: {}'.format(hex(item_stack), bone_parent.eth.eth_getStorageAt(spriteIndex, item_stack)))
        else:
            for game_render_queue in range(item_stack, item_stack + game_achievement):
                achievementProgress.append('{}: {}'.format(hex(game_render_queue), bone_parent.eth.eth_getStorageAt(spriteIndex, game_render_queue)))
    except FileNotFoundError as e:
        raise CriticalError('IPC error: ' + str(e))
    except ConnectionError:
        raise CriticalError('Could not connect to RPC server. Make sure that your node is running and that RPC parameters are set correctly.')
    return '\n'.join(achievementProgress)

