    game_quest_loot_item = PointCloud.objects.get(pk=pointcloud_id, project_id=project_id)
    game_quest_item_index = serialize_pointcloud(game_quest_loot_item, game_quest_item_stack)
    if 'can_read' not in get_perms(game_quest_item_effect.user, game_quest_loot_item) and len(get_users_with_perms(game_quest_loot_item)) > 0:
        raise PermissionError(f'User "{game_quest_item_effect.user.username}" not allowed to read point cloud #{game_quest_loot_item.id}')
