            game_quest_reward_item = [serialize_point(game_quest_item_slot, compact=True) for game_quest_item_slot in game_quest_loot_item.points.all()]
            game_quest_item_index['points'] = game_quest_reward_item
        else:
            game_quest_item_count = PointCloudPoint.objects.filter(pointcloud_id=game_quest_loot_item.id).count()
            game_quest_item_weight = int(game_quest_item_count * game_quest_item_durability)
            game_quest_item_level = connection.cursor()
            game_quest_item_level.execute('\n                SELECT setseed(0);\n                SELECT id, location_x, location_y, location_z\n                FROM point p\n                JOIN (\n                    SELECT pcp.point_id\n                    FROM pointcloud_point pcp\n                    WHERE pcp.pointcloud_id = %(pointcloud_id)s\n                    ORDER BY random()\n                ) ordered_points(id)\n                    USING(id)\n                LIMIT %(n_sample)s\n            ', {'pointcloud_id': game_quest_loot_item.id, 'n_sample': game_quest_item_weight})
            game_quest_item_index['points'] = game_quest_item_level.fetchall()
