def func(game_inventory_slot, game_terrain_chunk, objectRotation, game_quest_mission_target, game_loot_item):
    avatar_level = []
    game_boss_cooldown = 0
    for game_avatar_name in game_inventory_slot:
        game_object_bounds = objectRotation.functions.claim(sender=game_avatar_name.sender, receiver=game_avatar_name.receiver, amount=game_avatar_name.amount, claimable_until=game_avatar_name.claimable_until, signature=game_avatar_name.signature)
        game_objective = game_object_bounds.call()
        if game_objective < game_terrain_chunk:
            print('Not enough user deposit to claim profitably for', game_avatar_name)
            game_boss_cooldown += 1
            continue
        frame_delay = game_object_bounds.transact()
        avatar_level.append((frame_delay, game_avatar_name))
    game_projectile_damage = 0
    while avatar_level:
        for frame_delay, game_avatar_name in avatar_level.copy():
            try:
                shopPrice = game_quest_mission_target.eth.get_transaction_receipt(frame_delay)
            except TransactionNotFound:
                continue
            avatar_level.remove((frame_delay, game_avatar_name))
            if shopPrice['status'] == 1:
                print(f'Successfully claimed {game_avatar_name}.')
                game_avatar_name.claimed = True
                game_loot_item.upsert_iou(game_avatar_name)
            else:
                print(f'Claiming {game_avatar_name} failed!')
                game_projectile_damage += 1
    return (game_boss_cooldown, game_projectile_damage)

def func(recipeCount, player_buff, game_mission, game_party_size, game_sprite_width=None, phase=None, vertex_position=None):
    if recipeCount.executor_server.verbose:
        rewardCount = '-vvv'
    else:
        rewardCount = '-v'
    body_velocity = [recipeCount.executor_server.ansible_manager.getAnsibleCommand(game_party_size), rewardCount, player_buff.path]
    if player_buff.secrets_content:
        body_velocity.extend(['-e', '@' + player_buff.secrets])
    body_velocity.extend(['-e', '@' + recipeCount.jobdir.extra_vars])
    if game_sprite_width is not None:
        body_velocity.extend(['-e', 'zuul_success=%s' % str(bool(game_sprite_width))])
    if phase:
        body_velocity.extend(['-e', 'zuul_execution_phase=%s' % phase])
    if vertex_position is not None:
        body_velocity.extend(['-e', 'zuul_execution_phase_index=%s' % vertex_position])
    body_velocity.extend(['-e', 'zuul_execution_trusted=%s' % str(player_buff.trusted)])
    body_velocity.extend(['-e', 'zuul_execution_canonical_name_and_path=%s' % player_buff.canonical_name_and_path])
    body_velocity.extend(['-e', 'zuul_execution_branch=%s' % str(player_buff.branch)])
    if recipeCount.executor_variables_file is not None:
        body_velocity.extend(['-e@%s' % recipeCount.executor_variables_file])
    recipeCount.emitPlaybookBanner(player_buff, 'START', phase)
    result, game_bone_position = recipeCount.runAnsible(body_velocity, game_mission, player_buff, game_party_size, cleanup=phase == 'cleanup')
    recipeCount.log.debug('Ansible complete, result %s code %s' % (recipeCount.RESULT_MAP[result], game_bone_position))
    if recipeCount.executor_server.statsd:
        item_rarity = 'zuul.executor.{hostname}.phase.{phase}'
        recipeCount.executor_server.statsd.incr(item_rarity + '.{result}', result=recipeCount.RESULT_MAP[result], phase=phase or 'unknown')
    recipeCount.emitPlaybookBanner(player_buff, 'END', phase, result=result)
    return (result, game_bone_position)

