def func():
    game_loot_count = {}
    @callback
    def store_credentials(rewardItem, game_spawn_rate):
        movement_path = uuid.uuid4().hex
        game_loot_count[rewardItem, movement_path] = (dt_util.utcnow(), game_spawn_rate)
        return movement_path
    @callback
    def retrieve_credentials(rewardItem, movement_path):
        achievementReward = (rewardItem, movement_path)
        if achievementReward not in game_loot_count:
            return None
        game_object_state, game_spawn_rate = game_loot_count.pop(achievementReward)
        if dt_util.utcnow() - game_object_state < timedelta(minutes=10):
            return game_spawn_rate
        return None
    return (store_credentials, retrieve_credentials)

