def func(game_coin, battle, game_player_weapon_range, puzzlePiece, bodyFriction=None):
    gameLoop = {'method': game_player_weapon_range, 'params': puzzlePiece, 'version': '1.1', 'id': str(_random.random())[2:]}
    if bodyFriction:
        if type(bodyFriction) is not dict:
            raise ValueError('context is not type dict as required.')
        gameLoop['context'] = bodyFriction
    chestItem = _json.dumps(gameLoop, cls=_JSONObjectEncoder)
    game_quest_reward_amount = _requests.post(battle, data=chestItem, headers=game_coin._headers, timeout=game_coin.timeout, verify=not game_coin.trust_all_ssl_certificates)
    game_quest_reward_amount.encoding = 'utf-8'
    if game_quest_reward_amount.status_code == 500:
        if game_quest_reward_amount.headers.get(_CT) == _AJ:
            treasureChest = game_quest_reward_amount.json()
            if 'error' in treasureChest:
                raise ServerError(**treasureChest['error'])
            else:
                raise ServerError('Unknown', 0, game_quest_reward_amount.text)
        else:
            raise ServerError('Unknown', 0, game_quest_reward_amount.text)
    if not game_quest_reward_amount.ok:
        game_quest_reward_amount.raise_for_status()
    spawn_rate = game_quest_reward_amount.json()
    if 'result' not in spawn_rate:
        raise ServerError('Unknown', 0, 'An unknown server error occurred')
    if not spawn_rate['result']:
        return
    if len(spawn_rate['result']) == 1:
        return spawn_rate['result'][0]
    return spawn_rate['result']

