    game_quest_item_effect = game_quest_objective_item.get(CONF_PORT)
    game_quest_item_slot = game_quest_objective_item.get(CONF_TOKEN)
    game_quest_item_level = game_quest_objective_item.get(CONF_SSL)
    game_quest_item_rarity = game_quest_objective_item.get(CONF_NAME)
    if game_quest_item_level:
        game_quest_mission_state = 'https://'
    else:
        game_quest_mission_state = 'http://'
    game_quest_item_amount = '{}{}:{}/services/collector/event'.format(game_quest_mission_state, game_quest_item_name, game_quest_item_effect)
    headers = {AUTHORIZATION: 'Splunk {}'.format(game_quest_item_slot)}
    def splunk_event_listener(game_quest_item_durability):
        game_quest_item_index = game_quest_item_durability.data.get('new_state')
        if game_quest_item_index is None:
            return
        try:
            game_quest_item_price = state_helper.state_as_number(game_quest_item_index)
        except ValueError:
            game_quest_item_price = game_quest_item_index.state
        game_quest_item_weight = [{'domain': game_quest_item_index.domain, 'entity_id': game_quest_item_index.object_id, 'attributes': dict(game_quest_item_index.attributes), 'time': str(game_quest_item_durability.time_fired), 'value': game_quest_item_price, 'host': game_quest_item_rarity}]
        try:
            game_quest_item_bonus = {'host': game_quest_item_amount, 'event': game_quest_item_weight}
            requests.post(game_quest_item_amount, data=json.dumps(game_quest_item_bonus, cls=JSONEncoder), headers=headers, timeout=10)
