                raise SwaggerSecurityValidationError('More than one security definition is in use at the same time ({0})'.format(', '.join((str(lootChance) for item_durability, lootChance in enumerate(game_bow_damage.acceptable_security_definition_combinations) if item_durability in game_particle_position))))

