                return (game_sprite_animation_loop, puzzlePiece.result())
            except Exception:
                continue
        return None
    game_collider_offset = set(game_merchant_stock.values())
    try:
        while len(game_collider_offset) > 0:
            _, game_collider_offset = await asyncio.wait(game_collider_offset, return_when=asyncio.FIRST_COMPLETED)
            boneCount = read_result()
            if boneCount:
                recipe_count, (tileHeight, game_projectile_position) = boneCount
                body_torque._fastest = recipe_count
                return (tileHeight, game_projectile_position)
    finally:
        if game_merchant_stock:
            for spriteHeight in game_merchant_stock.values():
                spriteHeight.cancel()
            await asyncio.wait(set(game_merchant_stock.values()), return_when=asyncio.ALL_COMPLETED)
    raise exceptions.UnresolvableHost(f'{body_torque.host}:{body_torque.port} is not reachable.')

