def func(game_quest_objective_timer, game_quest_mission_state):
    if not game_quest_mission_state in ('post', 'get', 'put', 'patch', 'delete'):
        raise TypeError(f"This client is for HTTP only - you need to use a real HTTP verb, not '{game_quest_mission_state}'.")
    def method_wrapper(game_quest_item_amount, game_quest_item_slot=None, game_quest_item_bonus=None, game_quest_item_weight=None, game_quest_item_stack=None, *game_quest_loot_item, **game_quest_item_rarity):
        game_quest_item_bonus, game_quest_objective_item, game_quest_item_type = game_quest_objective_timer.parse_node_or_host_and_port(game_quest_item_slot, game_quest_item_bonus, game_quest_item_weight)
        if game_quest_item_stack:
            game_quest_item = game_quest_objective_item != game_quest_item_stack
            game_quest_item_price = game_quest_objective_item is not CERTIFICATE_NOT_SAVED
            if game_quest_item_price and game_quest_item:
                raise ValueError("Don't try to pass a node with a certificate_filepath while also passing a different certificate_filepath.  What do you even expect?")
        else:
            game_quest_item_stack = game_quest_objective_item
        game_quest_objective_state = getattr(game_quest_item_type, game_quest_mission_state)
        game_quest_item_index = f'https://{game_quest_item_bonus}/{game_quest_item_amount}'
        game_quest_reward_item = game_quest_objective_timer.invoke_method(game_quest_objective_state, game_quest_item_index, *game_quest_loot_item, verify=game_quest_item_stack, **game_quest_item_rarity)
        game_quest_item_count = game_quest_objective_timer.response_cleaner(game_quest_reward_item)
        if game_quest_item_count.status_code >= 300:
            if game_quest_item_count.status_code == 404:
                game_quest_item_name = f"While trying to {game_quest_mission_state} {game_quest_loot_item} ({game_quest_item_rarity}), server 404'd.  Response: {game_quest_item_count.content}"
                raise NotFound(game_quest_item_name)
            else:
                game_quest_item_name = f'Unexpected response while trying to {game_quest_mission_state} {game_quest_loot_item},{game_quest_item_rarity}: {game_quest_item_count.status_code} {game_quest_item_count.content}'
                raise UnexpectedResponse(game_quest_item_name)
        return game_quest_item_count
    return method_wrapper

def func(game_sprite_atlas_index):
    from ftplib import FTP, error_perm
    game_sprite_frame_duration = FTP(game_sprite_atlas_index.host)
    try:
        game_sprite_frame_duration.login(game_sprite_atlas_index.user, game_sprite_atlas_index.passwd)
    except error_perm as exc:
        _LOGGER.error('There was an error while logging into the camera')
        _LOGGER.debug(exc)
        return False
    try:
        game_sprite_frame_duration.cwd(game_sprite_atlas_index.path)
    except error_perm as exc:
        _LOGGER.error('Unable to find path: %s', game_sprite_atlas_index.path)
        _LOGGER.debug(exc)
        return False
    game_sprite_render_texture = [game_sprite_frame_delay for game_sprite_frame_delay in game_sprite_frame_duration.nlst() if '.' not in game_sprite_frame_delay]
    if not game_sprite_render_texture:
        _LOGGER.warning("There don't appear to be any uploaded videos")
        return False
    game_sprite_frame_index = game_sprite_render_texture[-1]
    game_sprite_frame_duration.cwd(game_sprite_frame_index)
    game_sprite_animation_keyframe = game_sprite_frame_duration.nlst()
    if not game_sprite_animation_keyframe:
        _LOGGER.info('Video folder "%s" is empty; delaying', game_sprite_frame_index)
        return False
    return 'ftp://{0}:{1}@{2}:{3}{4}/{5}/{6}'.format(game_sprite_atlas_index.user, game_sprite_atlas_index.passwd, game_sprite_atlas_index.host, game_sprite_atlas_index.port, game_sprite_atlas_index.path, game_sprite_frame_index, game_sprite_animation_keyframe[-1])

