        textureCount, _, backpackSlot = body_impulse.partition(b':')
        game_loot_item = int(textureCount)
        game_loot_quality = backpackSlot[:game_loot_item]
        if backpackSlot[game_loot_item:game_loot_item + 1] != b'|':
