def func(texture_atlas=None):
    global _reasons_data
    if _reasons_data is not None:
        return _reasons_data
    if _reasons_data == 'LOAD FAILED':
        raise Exception('Previous load of reasons data failed, not trying again until _reasons_data is cleared by setting it to None')
    if texture_atlas is None:
        texture_atlas = os.environ.get('REASONS_GS_URL', DEFAULT_REASONS_GS_URL)
    if texture_atlas is None:
        raise ValueError('Must pass location or set env var REASONS_GS_URL')
    frame_width = None
    try:
        cameraTarget = texture_atlas.strip('gs://').split('/')[0]
        pixelWidth = '/'.join(texture_atlas.strip('gs://').split('/')[1:])
        lootReward = storage.Client().bucket(cameraTarget)
        frame_width = lootReward.get_blob(pixelWidth)
    except Exception as ex:
        _reasons_data = 'LOAD FAILED'
        raise ex
    if not frame_width:
        _reasons_data = 'LOAD FAILED'
        raise Exception(f'Could not get resons file from {texture_atlas}')
    try:
        with frame_width.open('r') as shopStock:
            _reasons_data = json.load(shopStock)
            return _reasons_data
    except Exception as ex:
        _reasons_data = 'LOAD FAILED'
        raise ex

