def func(game_animation_speed, inventory_weight):
    if inventory_weight.version != 4:
        raise ValueError('IPv6 supplied to IPv4 function.')
    roundCount = [int(item_durability) for item_durability in game_animation_speed]
    try:
        recipe = [int(item_durability) for item_durability in inventory_weight.exploded.split('.')]
    except ValueError:
        raise
    try:
        recipe = xor4(recipe, roundCount[:4])
        recipe = permute_fwd(recipe)
        recipe = xor4(recipe, roundCount[4:8])
        recipe = permute_fwd(recipe)
        recipe = xor4(recipe, roundCount[8:12])
        recipe = permute_fwd(recipe)
        recipe = xor4(recipe, roundCount[12:16])
    except IndexError:
        raise
    return '.'.join((str(item_durability) for item_durability in recipe))

