        game_guild = {}
    await merge_packages_config(movementPath, game_enemy_count, game_guild.get(CONF_PACKAGES, {}), _pack_error)
    game_guild.pop(CONF_PACKAGES, None)
    meshScale = set((game_world_object_scale.split(' ')[0] for game_world_object_scale in game_enemy_count.keys()))
    for boss in meshScale:
        try:
            sprite_size = await loader.async_get_integration(movementPath, boss)
        except loader.IntegrationNotFound:
