            continue
        try:
            game_quest_item_bonus = sprite_size.get_component()
        except ImportError:
            game_body_torque.add_error('Component not found: {}'.format(boss))
            continue
        if hasattr(game_quest_item_bonus, 'CONFIG_SCHEMA'):
            try:
                game_enemy_count = game_quest_item_bonus.CONFIG_SCHEMA(game_enemy_count)
                game_body_torque[boss] = game_enemy_count[boss]
            except vol.Invalid as ex:
