                continue
        treasure_chest = getattr(game_quest_item_bonus, 'PLATFORM_SCHEMA_BASE', getattr(game_quest_item_bonus, 'PLATFORM_SCHEMA', None))
        if treasure_chest is None:
            continue
        buff_duration = []
        for game_quest_item_stack, partyMember in config_per_platform(game_enemy_count, boss):
            try:
                loot_reward = treasure_chest(partyMember)
            except vol.Invalid as ex:
                _comp_error(ex, boss, game_enemy_count)
                continue
            if game_quest_item_stack is None:
                buff_duration.append(loot_reward)
                continue
            try:
                material_count = await loader.async_get_integration(movementPath, game_quest_item_stack)
            except loader.IntegrationNotFound:
                game_body_torque.add_error('Integration {} not found when trying to verify its {} platform.'.format(game_quest_item_stack, boss))
