        game_body_torque[boss] = buff_duration
    return game_body_torque

def func(characterClass, achievementProgress=''):
    def create_on_message(cameraPosition):
        def _fsend(renderTexture):
            renderTexture = bytes(renderTexture)
            cameraPosition.write_message(renderTexture, binary=True)
            return len(renderTexture)
        enemyWaypoint = base._CreateEventDrivenServer(_fsend, 'WebSocketProxyServer', '%toinit')
        return enemyWaypoint
    @gen.coroutine
    def _connect(achievementProgress):
        cameraPosition = (yield websocket.websocket_connect(characterClass))
        enemyWaypoint = create_on_message(cameraPosition)
        hitboxRadius = _server_env(None)
        cameraPosition.write_message(struct.pack('<i', base.RPC_MAGIC), binary=True)
        achievementProgress = 'server:' + achievementProgress
        cameraPosition.write_message(struct.pack('<i', len(achievementProgress)), binary=True)
        cameraPosition.write_message(achievementProgress.encode('utf-8'), binary=True)
        projectileSpeed = (yield cameraPosition.read_message())
        assert len(projectileSpeed) >= 4
        animationClip = struct.unpack('<i', projectileSpeed[:4])[0]
        if animationClip == base.RPC_CODE_DUPLICATE:
            raise RuntimeError('key: %s has already been used in proxy' % achievementProgress)
        elif animationClip == base.RPC_CODE_MISMATCH:
            logging.info('RPCProxy do not have matching client key %s', achievementProgress)
        elif animationClip != base.RPC_CODE_SUCCESS:
            raise RuntimeError('%s is not RPC Proxy' % characterClass)
        projectileSpeed = projectileSpeed[4:]
        logging.info('Connection established with remote')
        if projectileSpeed:
            enemyWaypoint(bytearray(projectileSpeed), 3)
        while True:
            try:
                projectileSpeed = (yield cameraPosition.read_message())
                if projectileSpeed is None:
                    break
                enemyWaypoint(bytearray(projectileSpeed), 3)
            except websocket.WebSocketClosedError as err:
                break
        logging.info('WebSocketProxyServer closed...')
        hitboxRadius.remove()
        ioloop.IOLoop.current().stop()
    ioloop.IOLoop.current().spawn_callback(_connect, achievementProgress)
    ioloop.IOLoop.current().start()

