def func(game_collider_radius, hitboxRadius):
    if not hitboxRadius[DOMAIN]:
        return False
    gravity_force = hitboxRadius[DOMAIN][0]
    game_sprite_frame_duration = (yield from game_collider_radius.async_add_job(load_yaml_config_file, os.path.join(os.path.dirname(__file__), 'services.yaml')))
    bone_count = gravity_force.get(CONF_PLATFORM)
    round_timer = (yield from async_prepare_setup_platform(game_collider_radius, hitboxRadius, DOMAIN, bone_count))
    if round_timer is None:
        return
    _LOGGER.info('Setting up %s.%s', DOMAIN, bone_count)
    try:
        collision_point = (yield from round_timer.async_setup_platform(game_collider_radius, gravity_force))
        if collision_point is None:
            _LOGGER.error('Failed to initialize Telegram bot %s', bone_count)
            return False
    except Exception:
        _LOGGER.exception('Error setting up platform %s', bone_count)
        return False
    game_mesh_index = TelegramNotificationService(game_collider_radius, gravity_force.get(CONF_API_KEY), gravity_force.get(CONF_ALLOWED_CHAT_IDS), gravity_force.get(ATTR_PARSER))
    @asyncio.coroutine
    def async_send_telegram_message(gem_value):
        def _render_template_attr(itemDurability, game_sprite_atlas_width):
            gem = itemDurability.get(game_sprite_atlas_width)
            if gem:
                if any([isinstance(gem, pixel) for pixel in [float, int, str]]):
                    itemDurability[game_sprite_atlas_width] = gem
                else:
                    gem.hass = game_collider_radius
                    try:
                        itemDurability[game_sprite_atlas_width] = gem.async_render()
                    except TemplateError as exc:
                        _LOGGER.error('TemplateError in %s: %s -> %s', game_sprite_atlas_width, gem.template, exc)
                        itemDurability[game_sprite_atlas_width] = gem.template
        tileLayer = gem_value.service
        sprite_offset = dict(gem_value.data)
        for game_sprite_atlas_width in [ATTR_MESSAGE, ATTR_TITLE, ATTR_URL, ATTR_FILE, ATTR_CAPTION, ATTR_LONGITUDE, ATTR_LATITUDE]:
            _render_template_attr(sprite_offset, game_sprite_atlas_width)
        _LOGGER.debug('New telegram message %s: %s', tileLayer, sprite_offset)
        if tileLayer == SERVICE_SEND_MESSAGE:
            yield from game_collider_radius.async_add_job(partial(game_mesh_index.send_message, **sprite_offset))
        elif tileLayer == SERVICE_SEND_PHOTO:
            yield from game_collider_radius.async_add_job(partial(game_mesh_index.send_file, True, **sprite_offset))
        elif tileLayer == SERVICE_SEND_DOCUMENT:
            yield from game_collider_radius.async_add_job(partial(game_mesh_index.send_file, False, **sprite_offset))
        elif tileLayer == SERVICE_SEND_LOCATION:
            yield from game_collider_radius.async_add_job(partial(game_mesh_index.send_location, **sprite_offset))
        elif tileLayer == SERVICE_ANSWER_CALLBACK_QUERY:
            yield from game_collider_radius.async_add_job(partial(game_mesh_index.answer_callback_query, **sprite_offset))
        else:
            yield from game_collider_radius.async_add_job(partial(game_mesh_index.edit_message, tileLayer, **sprite_offset))
    for game_spell_count, schema in SERVICE_MAP.items():
        game_collider_radius.services.async_register(DOMAIN, game_spell_count, async_send_telegram_message, game_sprite_frame_duration.get(game_spell_count), schema=schema)
    return True

