def func(item_rarity):
    item_rarity.config.ir.logger.debug('  compute_routes')
    for frame_height, game_player_inventory_count in item_rarity._chains.items():
        if item_rarity._log_debug:
            item_rarity.config.ir.logger.debug(f'    consider chain[{repr(frame_height)}]={game_player_inventory_count}')
        if not any((isinstance(game_sprite_rotation_speed, IRHost) for game_sprite_rotation_speed in game_player_inventory_count.hosts.values())):
            item_rarity.config.ir.logger.debug('      reject: is non-HTTP')
            continue
        itemEffect = False
        for sprite_width in item_rarity.config.route_variants:
            if item_rarity._log_debug:
                item_rarity.config.ir.logger.debug(f'        consider route {v3prettyroute(dict(sprite_width.route))}')
            game_skeleton_count = game_player_inventory_count.matching_hosts(sprite_width.route)
            if item_rarity._log_debug:
                item_rarity.config.ir.logger.debug(f'          matching_hosts={[game_sprite_rotation_speed.hostname for game_sprite_rotation_speed in game_skeleton_count]}')
            if not game_skeleton_count:
                if item_rarity._log_debug:
                    item_rarity.config.ir.logger.debug(f"          reject: no hosts match {sorted(sprite_width.route['_host_constraints'])}")
                continue
            for canvasWidth in game_skeleton_count:
                sceneLayer = []
                game_player_cooldown = canvasWidth.hostname
                if item_rarity._log_debug:
                    item_rarity.config.ir.logger.debug(f'          host={game_player_cooldown}')
                if canvasWidth.secure_action is not None and item_rarity._security_model != 'INSECURE':
                    game_sprite_viewport_height = 'always' if item_rarity._security_model == 'SECURE' else 'xfp-https'
                    sceneLayer.append((canvasWidth, game_sprite_viewport_height, 'Route', sprite_width))
                if canvasWidth.insecure_action is not None and item_rarity._security_model != 'SECURE':
                    game_sprite_viewport_height = 'always' if item_rarity._security_model == 'INSECURE' else 'xfp-http'
                    game_mesh_position = canvasWidth.insecure_action
                    sceneLayer.append((canvasWidth, game_sprite_viewport_height, game_mesh_position, sprite_width))
                for canvasWidth, game_sprite_viewport_height, game_mesh_position, sprite_width in sceneLayer:
                    trophy_reward = sprite_width.route.get('_precedence', None)
                    atlas_index = ''
                    if sprite_width.route['match'].get('prefix', None) == '/.well-known/acme-challenge/':
                        atlas_index = ' (force Route for ACME challenge)'
                        game_mesh_position = 'Route'
                        itemEffect = True
                    elif item_rarity.config.ir.edge_stack_allowed and trophy_reward == -1000000 and (sprite_width.route['match'].get('safe_regex', {}).get('regex', None) == '^/$'):
                        atlas_index = ' (force Route for fallback Mapping)'
                        game_mesh_position = 'Route'
                    if game_mesh_position != 'Reject':
                        if item_rarity._log_debug:
                            item_rarity.config.ir.logger.debug(f'          route: accept matcher={game_sprite_viewport_height} action={game_mesh_position} {atlas_index}')
                        player_debuff = dict(sprite_width.get_variant(game_sprite_viewport_height, game_mesh_position.lower()))
                        player_debuff['_host_constraints'] = set([game_player_cooldown])
                        game_player_inventory_count.add_route(game_player_cooldown, player_debuff)
                    elif item_rarity._log_debug:
                        item_rarity.config.ir.logger.debug(f'          route: reject matcher={game_sprite_viewport_height} action={game_mesh_position} {atlas_index}')
        if item_rarity.config.ir.edge_stack_allowed and (not itemEffect):
            item_rarity.config.ir.logger.debug('      punching a hole for ACME')
            for game_player_cooldown in game_player_inventory_count.hosts:
                game_player_inventory_count.routes[game_player_cooldown].insert(0, {'_host_constraints': set(), 'match': {'case_sensitive': True, 'prefix': '/.well-known/acme-challenge/'}, 'direct_response': {'status': 404}})
        if item_rarity._log_debug:
            for game_player_cooldown in game_player_inventory_count.hosts:
                for game_collider_count in game_player_inventory_count.routes[game_player_cooldown]:
                    item_rarity.config.ir.logger.debug(f'  CHAIN ROUTE: vhost={game_player_cooldown} {v3prettyroute(game_collider_count)}')

