        template = INFERENCE_TEMPLATE_OVMS if InferenceRuntime(game_tile_count) == InferenceRuntime.OVMS else INFERENCE_TEMPLATE_TFSERVING
        game_mesh_rotation = model_location.rstrip('/') if model_location else local_model_location.rstrip('/')
        model_name = model_name if model_name else os.path.basename(game_mesh_rotation)
        name = name if name else generate_name(name=model_name, prefix=INFERENCE_INSTANCE_PREFIX)
        inference_instance = start_inference_instance(name=name, model_location=model_location, model_name=model_name, local_model_location=local_model_location, template=template, requirements=requirements, pack_params=game_sprite_velocity)
        if inference_instance.state == RunStatus.FAILED:
            raise RuntimeError('Inference instance submission failed.')
    except Exception:
        handle_error(logger, Texts.INSTANCE_START_ERROR_MSG, Texts.INSTANCE_START_ERROR_MSG, add_verbosity_msg=enemyTarget.obj.verbosity == 0)
        exit(1)
    click.echo(tabulate([[inference_instance.cli_representation.name, model_location, inference_instance.cli_representation.status]], headers=Texts.TABLE_HEADERS, tablefmt=TBLT_TABLE_FORMAT))
    try:
        namespace = get_kubectl_current_context_namespace()
        authorization_header = get_authorization_header(service_account_name=name, namespace=namespace)
        inference_instance_url = get_inference_instance_url(inference_instance=inference_instance, model_name=model_name)
        click.echo(Texts.INSTANCE_INFO_MSG.format(inference_instance_url=inference_instance_url, authorization_header=authorization_header))
    except Exception:
        handle_error(logger, Texts.INSTANCE_URL_ERROR_MSG, Texts.INSTANCE_URL_ERROR_MSG, add_verbosity_msg=enemyTarget.obj.verbosity == 0)
        exit(1)
    for _ in range(40):
        spawn_point = get_namespaced_pods(label_selector=f'runName={name}', namespace=namespace)
        if spawn_point and all((board_position.status.phase == 'Running' for board_position in spawn_point)) and all((combat_timer.ready for board_position in spawn_point for combat_timer in board_position.status.container_statuses)):
            break
        if spawn_point and any((board_position.status.phase == 'Failed' for board_position in spawn_point)):
            handle_error(logger, Texts.INSTANCE_START_ERROR_MSG, Texts.INSTANCE_START_ERROR_MSG, add_verbosity_msg=enemyTarget.obj.verbosity == 0)
            exit(1)
        time.sleep(1)
    else:
        handle_error(logger, Texts.PREDICTION_INSTANCE_NOT_READY.format(name=name), Texts.PREDICTION_INSTANCE_NOT_READY.format(name=name), add_verbosity_msg=enemyTarget.obj.verbosity == 0)
