def func(playerDebuff, objectIndex, dungeon_floor):
    try:
        game_animation_count = socks.create_connection((playerDebuff._host, playerDebuff._port), proxy_type=playerDebuff._socks_options['socks_version'], proxy_addr=playerDebuff._socks_options['proxy_host'], proxy_port=playerDebuff._socks_options['proxy_port'], proxy_username=playerDebuff._socks_options['username'], proxy_password=playerDebuff._socks_options['password'], proxy_rdns=playerDebuff._socks_options['rdns'], timeout=objectIndex, **dungeon_floor)
    except SocketTimeout as e:
        raise ConnectTimeoutError(playerDebuff, 'Connection to %s timed out. (connect timeout=%s)' % (playerDebuff._host, objectIndex))
    except socks.ProxyError as e:
        if e.socket_err:
            dungeon_loot = e.socket_err
            if isinstance(dungeon_loot, SocketTimeout):
                raise ConnectTimeoutError(playerDebuff, 'Connection to %s timed out. (connect timeout=%s)' % (playerDebuff._host, objectIndex))
            else:
                raise NewConnectionError(playerDebuff, 'Failed to establish a new connection: %s' % dungeon_loot)
        else:
            raise NewConnectionError(playerDebuff, 'Failed to establish a new connection: %s' % e)
    except SocketError as e:
