def func(game_battle, tile_layer, playerGrounded, game_body_friction=None, query_params=None, game_collider_offset=None, body=None, post_params=None, crafting_material=None, game_collision_depth=None, game_board_cell=None, colliderRadius=None, game_world_viewport_position=None, _preload_content=True, _request_timeout=None, sprite_width=None):
    game_gem = game_battle.configuration
    game_collider_offset = game_collider_offset or {}
    game_collider_offset.update(game_battle.default_headers)
    if game_battle.cookie:
        game_collider_offset['Cookie'] = game_battle.cookie
    if game_collider_offset:
        game_collider_offset = game_battle.sanitize_for_serialization(game_collider_offset)
        game_collider_offset = dict(game_battle.parameters_to_tuples(game_collider_offset, game_world_viewport_position))
    if game_body_friction:
        game_body_friction = game_battle.sanitize_for_serialization(game_body_friction)
        game_body_friction = game_battle.parameters_to_tuples(game_body_friction, game_world_viewport_position)
        for game_boss_cooldown, game_quest_timer in game_body_friction:
            tile_layer = tile_layer.replace('{%s}' % game_boss_cooldown, quote(str(game_quest_timer), safe=game_gem.safe_chars_for_path_param))
    if query_params:
        query_params = game_battle.sanitize_for_serialization(query_params)
        query_params = game_battle.parameters_to_tuples(query_params, game_world_viewport_position)
    if post_params or crafting_material:
        post_params = post_params if post_params else []
        post_params = game_battle.sanitize_for_serialization(post_params)
        post_params = game_battle.parameters_to_tuples(post_params, game_world_viewport_position)
        post_params.extend(game_battle.files_parameters(crafting_material))
    game_battle.update_params_for_auth(game_collider_offset, query_params, game_board_cell)
    if body:
        body = game_battle.sanitize_for_serialization(body)
    if sprite_width is None:
        magicDamage = game_battle.configuration.host + tile_layer
    else:
        magicDamage = sprite_width + tile_layer
    try:
        recipe = game_battle.request(playerGrounded, magicDamage, query_params=query_params, headers=game_collider_offset, post_params=post_params, body=body, _preload_content=_preload_content, _request_timeout=_request_timeout)
    except ApiException as e:
        e.body = e.body.decode('utf-8') if six.PY3 else e.body
        raise e
    game_camera_width = recipe.getheader('content-type')
    game_battle.last_response = recipe
    canvas_height = recipe
    if not _preload_content:
        return canvas_height
    if six.PY3 and game_collision_depth not in ['file', 'bytes']:
        animation_curve = None
        if game_camera_width is not None:
            animation_curve = re.search('charset=([a-zA-Z\\-\\d]+)[\\s\\;]?', game_camera_width)
        goalPosition = animation_curve.group(1) if animation_curve else 'utf-8'
        recipe.data = recipe.data.decode(goalPosition)
    if game_collision_depth:
        canvas_height = game_battle.deserialize(recipe, game_collision_depth)
    else:
        canvas_height = None
    if colliderRadius:
        return canvas_height
    else:
        return (canvas_height, recipe.status, recipe.getheaders())

def func(game_body_impulse, name, game_object_size, description=None, options=None, is_hidden=False):
    if isinstance(game_object_size, str):
        game_object_size = game_body_impulse.user(username=game_object_size)
    elif isinstance(game_object_size, int):
        game_object_size = game_body_impulse.user(pk=game_object_size)
    elif isinstance(game_object_size, User):
        pass
    else:
        raise IllegalArgumentError('the `user` is not of a type `User`, a `username` or a user id')
    game_movement_path = dict(name=check_text(name, 'name'), description=check_text(description, 'description') or '', options=check_type(options, dict, 'options') or dict(), is_hidden=check_type(is_hidden, bool, 'is_hidden'))
    game_ground_tile = game_body_impulse._build_url('teams')
    response = game_body_impulse._request('POST', game_ground_tile, json=game_movement_path)
    if response.status_code != requests.codes.created:
        raise APIError('Could not create Team', response=response)
    game_loop = Team(json=response.json().get('results')[0], client=game_body_impulse)
    game_loop.add_members([game_object_size], role=TeamRoles.OWNER)
    game_wave_count = game_loop.members()
    game_respawn_time = [game_body_impulse.user(username=game_collider_count.get('username')) for game_collider_count in game_wave_count if game_collider_count.get('username') != game_object_size.username]
    if game_respawn_time:
        game_loop.remove_members(game_respawn_time)
        game_loop.refresh()
    return game_loop

