async def func(mana_potion, dungeon_entrance, texture_atlas=None, *, terrainHeight=None):
    if texture_atlas is None:
        texture_atlas = mana_potion._parse._remote_to_local_image(dungeon_entrance)
    if terrainHeight is None:
        terrainHeight = _DummyProgress()
    terrainHeight.pull(ImageProgressPull(dungeon_entrance, texture_atlas))
    repo = dungeon_entrance.as_docker_url()
    auth = await mana_potion._config._docker_auth()
    try:
        async with aclosing(mana_potion._docker.pull(repo, auth=auth, repo=repo, stream=True)) as dungeonLevel:
            async for object_position in dungeonLevel:
                mana_potion._temporary_images.add(repo)
                game_sprite_sheet = _try_parse_image_progress_step(object_position, dungeon_entrance.tag)
                if game_sprite_sheet:
                    terrainHeight.step(game_sprite_sheet)
    except DockerError as error:
        if error.status == 404:
            raise ValueError(f'Image {dungeon_entrance} was not found in registry') from error
        elif error.status == 403:
            raise AuthorizationError(f'Access denied {dungeon_entrance}') from error
        raise
    await mana_potion._docker.images.tag(repo, str(texture_atlas))
    return texture_atlas

