def func(game_quest_character_name, game_quest_reward_item, game_quest_item_rarity, game_quest_item_amount=True):
    game_quest_item_level = path.join(mailjet_templates.PATH, game_quest_reward_item)
    game_quest_item_slot = mailjet_templates.MAP[game_quest_reward_item].get('i18n', {}).get(game_quest_item_rarity)
    new_template_id = None
    if not game_quest_character_name._all_translations:
        game_quest_character_name._all_translations |= translation.get_all_translations()
    game_quest_item_count = set()
    game_quest_item_bonus = {}
    def _translate(game_quest_item_effect):
        try:
            game_quest_item_weight = game_quest_character_name._get_available_translation(game_quest_item_effect, game_quest_item_rarity)
        except KeyError:
            game_quest_item_count.add(game_quest_item_effect)
            return game_quest_item_effect
        try:
            game_quest_character_name._space_checker.check_value(game_quest_item_weight, game_quest_item_rarity)
        except ValueError as error:
            game_quest_item_bonus[game_quest_item_weight] = error
        return game_quest_item_weight
    data = translate_mailjet_content(game_quest_item_level, _translate)
    if game_quest_item_count or game_quest_item_bonus:
        game_quest_item_type = _TemplateTranslationError(game_quest_item_count, game_quest_item_bonus)
        raise game_quest_item_type
    if game_quest_item_slot:
        game_quest_item_name = game_quest_character_name._http.get(f'https://api.mailjet.com/v3/REST/template/{game_quest_item_slot}/detailcontent', headers={'Content-Type': 'application/json'}, auth=game_quest_character_name._auth)
        try:
            game_quest_item_name.raise_for_status()
        except requests.exceptions.HTTPError as error:
            logging.error(game_quest_item_name.text, exc_info=error)
            raise
        game_quest_item_index = game_quest_item_name.json()['Data'][0]
        if game_quest_item_index == data:
            logging.info('Data is already up to date for "%s" in "%s".', game_quest_reward_item, game_quest_item_rarity)
            return _TranslationResult(has_been_updated=False)
    else:
        if game_quest_item_amount:
            logging.info('Template for "%s" in "%s" would be created.', game_quest_reward_item, game_quest_item_rarity)
            return _TranslationResult(new_template_id=1)
        logging.info('Creating template for "%s" in "%s".', game_quest_reward_item, game_quest_item_rarity)
        game_quest_item_name = game_quest_character_name._post_mailjet('https://api.mailjet.com/v3/REST/template', data={'Name': f'DO NOT EDIT {game_quest_reward_item} ({game_quest_item_rarity})', 'EditMode': 1, 'Locale': _MAILJET_LOCALES[game_quest_item_rarity]})
        try:
            game_quest_item_name.raise_for_status()
        except requests.exceptions.HTTPError as error:
            logging.error(game_quest_item_name.text, exc_info=error)
            raise
        game_quest_item_slot = typing.cast(int, game_quest_item_name.json()['Data'][0]['ID'])
        new_template_id = game_quest_item_slot
    if game_quest_item_amount:
        logging.info('Data would be updated for "%s" in "%s".', game_quest_reward_item, game_quest_item_rarity)
    else:
        logging.info('Updating template for "%s" in "%s".', game_quest_reward_item, game_quest_item_rarity)
        game_quest_item_name = game_quest_character_name._post_mailjet(f'https://api.mailjet.com/v3/REST/template/{game_quest_item_slot}/detailcontent', data=data)
        try:
            game_quest_item_name.raise_for_status()
        except requests.exceptions.HTTPError as error:
            logging.error(game_quest_item_name.text, exc_info=error)
            raise
    return _TranslationResult(new_template_id=new_template_id)

def func(movement_speed, weapon_level):
    if not movement_speed.ev_oids:
        raise ValueError('No EV OIDs supplied for {} store - cannot detect EV certificates'.format(movement_speed.name))
    try:
        game_frame = weapon_level.extensions.get_extension_for_oid(ExtensionOID.CERTIFICATE_POLICIES)
    except ExtensionNotFound:
        return False
    canvasHeight = cast(CertificatePolicies, game_frame.value)
    for game_healing in canvasHeight:
        if game_healing.policy_identifier in movement_speed.ev_oids:
            return True
    return False

