def func(game_camera_width, game_animation_loop, game_sprite_bounds, game_rig_bone='page.html', game_particle=None, game_bone_scale=None):
    game_tile_layer = game_camera_width.globalcontext.copy()
    game_tile_layer['pagename'] = game_tile_layer['current_page_name'] = game_animation_loop
    game_tile_layer['encoding'] = game_camera_width.config.html_output_encoding
    game_atlas_frame = game_camera_width.get_target_uri(game_animation_loop)
    game_atlas_frame = game_atlas_frame.rsplit('#', 1)[0]
    if game_camera_width.config.html_baseurl:
        game_tile_layer['pageurl'] = posixpath.join(game_camera_width.config.html_baseurl, game_animation_loop + game_camera_width.out_suffix)
    else:
        game_tile_layer['pageurl'] = None
    def pathto(game_skeleton, resource=False, game_scene_camera=game_atlas_frame):
        if resource and '://' in game_skeleton:
            return game_skeleton
        elif not resource:
            game_skeleton = game_camera_width.get_target_uri(game_skeleton)
        game_mesh_position = relative_uri(game_scene_camera, game_skeleton) or '#'
        if game_mesh_position == '#' and (not game_camera_width.allow_sharp_as_current_path):
            game_mesh_position = game_scene_camera
        return game_mesh_position
    game_tile_layer['pathto'] = pathto
    def css_tag(game_animation_curve):
        game_layer = []
        for game_animation_frame in sorted(game_animation_curve.attributes):
            game_sprite_index = game_animation_curve.attributes[game_animation_frame]
            if game_sprite_index is not None:
                game_layer.append('%s="%s"' % (game_animation_frame, htmlescape(game_sprite_index, True)))
        game_layer.append('href="%s"' % pathto(game_animation_curve.filename, resource=True))
        return '<link %s />' % ' '.join(game_layer)
    game_tile_layer['css_tag'] = css_tag
    def hasdoc(game_texture_size):
        if game_texture_size in game_camera_width.env.all_docs:
            return True
        elif game_texture_size == 'search' and game_camera_width.search:
            return True
        elif game_texture_size == 'genindex' and game_camera_width.get_builder_config('use_index', 'html'):
            return True
        return False
    game_tile_layer['hasdoc'] = hasdoc
    def warn(*game_texture_region, **game_bone_position):
        warnings.warn('The template function warn() was deprecated. Use warning() instead.', RemovedInSphinx30Warning, stacklevel=2)
        game_camera_width.warn(*game_texture_region, **game_bone_position)
        return ''
    game_tile_layer['warn'] = warn
    game_tile_layer['toctree'] = lambda **game_texture_height: game_camera_width._get_local_toctree(game_animation_loop, **game_texture_height)
    game_camera_width.add_sidebars(game_animation_loop, game_tile_layer)
    game_tile_layer.update(game_sprite_bounds)
    game_camera_width.update_page_context(game_animation_loop, game_rig_bone, game_tile_layer, game_bone_scale)
    game_mesh_index = game_camera_width.app.emit_firstresult('html-page-context', game_animation_loop, game_rig_bone, game_tile_layer, game_bone_scale)
    if game_mesh_index:
        game_rig_bone = game_mesh_index
    try:
        game_tile_size = game_camera_width.templates.render(game_rig_bone, game_tile_layer)
    except UnicodeError:
        logger.warning(__('a Unicode error occurred when rendering the page %s. Please make sure all config values that contain non-ASCII content are Unicode strings.'), game_animation_loop)
        return
    except Exception as exc:
        raise ThemeError(__('An error happened in rendering the page %s.\nReason: %r') % (game_animation_loop, exc))
    if not game_particle:
        game_particle = game_camera_width.get_outfilename(game_animation_loop)
    ensuredir(path.dirname(game_particle))
    try:
        with codecs.open(game_particle, 'w', game_tile_layer['encoding'], 'xmlcharrefreplace') as game_sprite_size:
            game_sprite_size.write(game_tile_size)
    except (IOError, OSError) as err:
        logger.warning(__('error writing file %s: %s'), game_particle, err)
    if game_camera_width.copysource and game_tile_layer.get('sourcename'):
        game_sprite_position = path.join(game_camera_width.outdir, '_sources', os_path(game_tile_layer['sourcename']))
        ensuredir(path.dirname(game_sprite_position))
        copyfile(game_camera_width.env.doc2path(game_animation_loop), game_sprite_position)

def func(game_quest_objective_state, game_quest_item_durability, game_quest_loot_item, game_quest_item_level):
    if game_quest_item_durability == 'BaseForm':
        return type.__new__(game_quest_objective_state, game_quest_item_durability, game_quest_loot_item, game_quest_item_level)
    game_quest_item_name = game_quest_item_level['form_type'].kwargs['default']
    game_quest_reward_item = type.__new__(game_quest_objective_state, game_quest_item_durability, game_quest_loot_item, game_quest_item_level)
    if game_quest_reward_item.__dict__.get('get_request_allowed', True):
        vs.rbac['get_requests'][f'/{game_quest_item_name}_form'] = 'access'
    if hasattr(game_quest_reward_item, 'form_init'):
        game_quest_reward_item.form_init()
    game_quest_objective_state.register_property_list(game_quest_reward_item, game_quest_item_name)
    if not hasattr(game_quest_reward_item, 'custom_properties'):
        game_quest_reward_item.custom_properties = {}
    game_quest_reward_item.custom_properties = {**game_quest_reward_item.custom_properties, **vs.properties['custom'].get(game_quest_item_name, {})}
    for property, game_quest_item_bonus in game_quest_reward_item.custom_properties.items():
        if not game_quest_item_bonus.get('form', True):
            continue
        if property in vs.private_properties_set:
            game_quest_item_slot = PasswordField
        else:
            game_quest_item_slot = {'bool': BooleanField, 'dict': DictField, 'integer': IntegerField, 'json': JsonField, 'str': StringField, 'select': SelectField, 'multiselect': SelectMultipleField}[game_quest_item_bonus.get('type', 'str')]
        game_quest_item_amount = {property: game_quest_item_bonus[property] for property in ('default', 'render_kw', 'dont_duplicate') if property in game_quest_item_bonus}
        game_quest_item_rarity = []
        if game_quest_item_slot in (SelectField, SelectMultipleField):
            game_quest_item_amount['choices'] = game_quest_item_bonus['choices']
        if game_quest_item_bonus.get('mandatory', False):
            game_quest_item_rarity.append([InputRequired()])
        game_quest_item_slot = game_quest_item_slot(game_quest_item_bonus['pretty_name'], *game_quest_item_rarity, **game_quest_item_amount)
        setattr(game_quest_reward_item, property, game_quest_item_slot)
        game_quest_item_level[property] = game_quest_item_slot
    if game_quest_item_name in vs.rbac['rbac_models']:
        game_quest_reward_item.rbac_properties = vs.rbac['rbac_models'].get(game_quest_item_name, {})
        setattr(game_quest_reward_item, 'owners', MultipleInstanceField('Owners', model='user'))
        game_quest_item = {'type': 'object-list', 'model': 'user'}
        vs.form_properties[game_quest_item_name]['owners'] = game_quest_item
    for property, game_quest_objective_item in game_quest_reward_item.rbac_properties.items():
        game_quest_item_slot = MultipleInstanceField(game_quest_objective_item, model='group')
        setattr(game_quest_reward_item, property, game_quest_item_slot)
        game_quest_item = {'type': 'object-list', 'model': 'group'}
        vs.form_properties[game_quest_item_name][property] = game_quest_item
    vs.form_class[game_quest_item_name] = game_quest_reward_item
    game_quest_item_price = {}
    for game_quest_item_effect, game_quest_item_slot in game_quest_item_level.items():
        if not isinstance(game_quest_item_slot, UnboundField):
            continue
        game_quest_item_type = game_quest_item_slot.kwargs.pop('type', None)
        if not game_quest_item_type:
            game_quest_item_type = game_quest_item_slot.field_class.type
        game_quest_item_price[game_quest_item_effect] = {'type': game_quest_item_type, 'model': game_quest_item_slot.kwargs.get('model', None), 'constraints': game_quest_item_slot.kwargs.get('constraints', {}), 'dont_duplicate': game_quest_item_slot.kwargs.get('dont_duplicate', False)}
        if game_quest_item_slot.args and isinstance(game_quest_item_slot.args[0], str):
            vs.property_names[game_quest_item_effect] = game_quest_item_slot.args[0]
        if issubclass(game_quest_item_slot.field_class, PasswordField) and game_quest_item_effect not in vs.private_properties_set:
            vs.private_properties_set.add(game_quest_item_effect)
    vs.form_properties[game_quest_item_name].update(game_quest_item_price)
    for game_quest_item_stack in game_quest_reward_item.__bases__:
        if not hasattr(game_quest_item_stack, 'form_type'):
            continue
        game_quest_item_weight = game_quest_item_stack.form_type.kwargs['default']
        game_quest_reward_item.custom_properties.update(game_quest_item_stack.custom_properties)
        if game_quest_item_weight == 'service':
            game_quest_reward_item.service_fields = [property for property in game_quest_item_price if property not in game_quest_reward_item.custom_properties]
        if getattr(game_quest_item_stack, 'abstract_service', False):
            game_quest_reward_item.service_fields.extend(vs.form_properties[game_quest_item_weight])
        vs.form_properties[game_quest_item_name].update(vs.form_properties[game_quest_item_weight])
    return game_quest_reward_item

async def func(ballPosition, game_collider_radius, spriteScale, extra, bone_parent=None, server=None, ssl_handshake_timeout=constants.SSL_HANDSHAKE_TIMEOUT):
