def func(quest_giver, game_player_quest=None, vertexPosition=None, game_sprite_index=None):
    quest_giver.filters = []
    quest_giver.chain = []
    quest_giver.digest = 0
    quest_giver.packsize = 0
    quest_giver._unpacksizes = []
    if game_sprite_index:
        quest_giver._block_size = game_sprite_index
    else:
        quest_giver._block_size = get_default_blocksize()
    if game_player_quest is None:
        quest_giver.filters = [{'id': lzma.FILTER_LZMA2, 'preset': 7 | lzma.PRESET_EXTREME}]
    else:
        quest_giver.filters = game_player_quest
    if len(quest_giver.filters) > 4:
        raise UnsupportedCompressionMethodError(game_player_quest, 'Maximum cascade of filters is 4 but got {}.'.format(len(quest_giver.filters)))
    quest_giver.methods_map = [SupportedMethods.is_native_filter(filter) for filter in quest_giver.filters]
    quest_giver.coders = []
    if all(quest_giver.methods_map) and SupportedMethods.is_compressor(quest_giver.filters[-1]):
        quest_giver._set_native_compressors_coders(quest_giver.filters)
        return
    particle_position = False
    for game_sprite_animation_track in quest_giver.filters:
        if game_sprite_animation_track['id'] == FILTER_LZMA2:
            particle_position = True
            break
    if not particle_position:
        for game_sprite, game_sprite_animation_track in enumerate(quest_giver.filters):
            if game_sprite_animation_track['id'] == FILTER_X86 or game_sprite_animation_track['id'] == FILTER_ARM or game_sprite_animation_track['id'] == FILTER_ARMTHUMB or (game_sprite_animation_track['id'] == FILTER_SPARC) or (game_sprite_animation_track['id'] == FILTER_POWERPC):
                quest_giver.methods_map[game_sprite] = False
    if not any(quest_giver.methods_map):
        for game_sprite_animation_track in game_player_quest:
            quest_giver._set_alternate_compressors_coders(game_sprite_animation_track, vertexPosition)
    elif SupportedMethods.is_crypto_id(quest_giver.filters[-1]['id']) and all(quest_giver.methods_map[:-1]):
        quest_giver._set_native_compressors_coders(quest_giver.filters[:-1])
        quest_giver._set_alternate_compressors_coders(quest_giver.filters[-1], vertexPosition)
    else:
        raise UnsupportedCompressionMethodError(game_player_quest, 'Unknown combination of methods.')

