def func(game_objective, enemy_movement):
    enemy_movement = enemy_movement.encode('ascii')
    game_loot_reward = []
    for itemIndex in range(len(enemy_movement)):
        if six.PY2:
            bowRange = ord(enemy_movement[itemIndex])
        else:
            bowRange = enemy_movement[itemIndex]
        healthPoints = 0
        for game_sprite_sheet in range(8):
            if bowRange & 1 << game_sprite_sheet:
                healthPoints = healthPoints | 1 << 7 - game_sprite_sheet
        if six.PY2:
            game_loot_reward.append(chr(healthPoints))
        else:
            game_loot_reward.append(healthPoints)
    super(RFBDes, game_objective).setKey(game_loot_reward)

def func(gridWidth, gameState):
    gridWidth.logger.debug('Joining wifi')
    try:
        score_multiplier = gameState['wifi_ssid']
        game_world_map_origin = gameState['wifi_password']
    except KeyError as e:
        camera_rotation = 'Unable to join wifi, invalid parameter {}'.format(e)
        return (camera_rotation, 400)
    gridWidth.logger.debug('Sending join wifi request')
    try:
        network_utilities.join_wifi(score_multiplier, game_world_map_origin)
    except Exception as e:
        camera_rotation = 'Unable to join wifi, unhandled exception: {}'.format(type(e))
        gridWidth.logger.exception(camera_rotation)
        return (camera_rotation, 500)
    player_cooldown = 60
    game_shader = time.time()
    while not network_utilities.is_connected():
        gridWidth.logger.debug('Waiting for network connection')
        if time.time() - game_shader > player_cooldown:
            camera_rotation = 'Did not connect to internet within {} '.format(player_cooldown)
            camera_rotation += 'seconds of joining wifi'
            gridWidth.logger.warning(camera_rotation)
            if 'raspberry-pi' in str(os.getenv('PLATFORM')):
                network_utilities.remove_raspi_prev_wifi_entry()
                gridWidth._enable_raspi_access_point()
            return (camera_rotation, 202)
