def func(game_collision_mask):
    game_collision_mask.config.ir.logger.debug('  compute_tcpchains')
    for player_weapon in game_collision_mask.config.ir.ordered_groups():
        if not isinstance(player_weapon, IRTCPMappingGroup):
            continue
        if game_collision_mask._log_debug:
            game_collision_mask.config.ir.logger.debug(f'    consider {player_weapon}')
        if player_weapon.bind_to() != game_collision_mask.bind_to:
            game_collision_mask.config.ir.logger.debug('      reject')
            continue
        game_collision_mask.config.ir.logger.debug('      accept')
        game_canvas_width = player_weapon.get('host', None)
        if not game_canvas_width:
            game_collision_mask.add_chain('tcp', None, '*', '*').add_tcphost(player_weapon)
        else:
            game_world_object_layer = tlscontext_for_tcpmapping(player_weapon, game_collision_mask.config)
            if not game_world_object_layer:
                player_weapon.post_error('No matching TLSContext found, disabling!')
                continue
            board_position = game_canvas_width
            game_collision_mask.add_chain('tcp', game_world_object_layer, game_canvas_width, board_position).add_tcphost(player_weapon)

