def func(inventoryItem, game_enemy_waypoint, game_hitbox_offset, *, game_mesh_position=None, player_spawn=None, collision_depth=None):
    assert collision_depth is None or isinstance(collision_depth, str)
    if game_mesh_position:
        if collision_depth is None:
            raise ValueError('you have to pass server_hostname when using ssl')
    elif collision_depth is not None:
        raise ValueError('server_hostname is only meaningful with ssl')
    if game_hitbox_offset is not None:
        if player_spawn is not None:
            raise ValueError('path and sock can not be specified at the same time')
        player_spawn = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM, 0)
        try:
            player_spawn.setblocking(False)
            yield from inventoryItem.sock_connect(player_spawn, game_hitbox_offset)
        except:
            player_spawn.close()
            raise
    else:
        if player_spawn is None:
            raise ValueError('no path and sock were specified')
        if player_spawn.family != socket.AF_UNIX or not base_events._is_stream_socket(player_spawn):
            raise ValueError('A UNIX Domain Stream Socket was expected, got {!r}'.format(player_spawn))
        player_spawn.setblocking(False)
    manaPoints, weaponRange = (yield from inventoryItem._create_connection_transport(player_spawn, game_enemy_waypoint, game_mesh_position, collision_depth))
    return (manaPoints, weaponRange)

