def func(quest_count, loot_reward, sword_range=None, game_sprite_layer=None):
    game_weapon_level = SupportedMethods.get_filter_id(loot_reward)
    if game_weapon_level in [FILTER_X86, FILTER_ARM, FILTER_ARMTHUMB, FILTER_POWERPC, FILTER_SPARC]:
        return algorithm_class_map[game_weapon_level][1](size=sword_range)
    if SupportedMethods.is_native_coder(loot_reward):
        raise UnsupportedCompressionMethodError(loot_reward, 'Unknown method code:{}'.format(loot_reward['method']))
    if game_weapon_level not in algorithm_class_map:
        raise UnsupportedCompressionMethodError(loot_reward, 'Unknown method filter_id:{}'.format(game_weapon_level))
    if algorithm_class_map[game_weapon_level][1] is None:
        raise UnsupportedCompressionMethodError(loot_reward, 'Decompression is not supported by {}.'.format(SupportedMethods.get_method_name_id(game_weapon_level)))
    if SupportedMethods.is_crypto_id(game_weapon_level):
        return algorithm_class_map[game_weapon_level][1](loot_reward['properties'], game_sprite_layer, quest_count.block_size)
    elif SupportedMethods.need_property(game_weapon_level):
        return algorithm_class_map[game_weapon_level][1](loot_reward['properties'], quest_count.block_size)
    else:
        return algorithm_class_map[game_weapon_level][1]()

def func(game_quest_mission_state, collisionLayer):
    gameWorld, chestCount = parse_zephyr_body(game_quest_mission_state.message, game_quest_mission_state.format)
    partyLeader = False
    objective_index = False
    if game_quest_mission_state.opcode == 'PING':
        return
    game_viewport_position = game_quest_mission_state.cls.lower()
    if game_viewport_position == options.nagios_class:
        with open(options.nagios_path, 'w') as game_material_color:
            game_material_color.write('0\n')
        return
    if game_quest_mission_state.recipient != '':
        partyLeader = True
    if partyLeader and (not options.forward_personals):
        return
    if game_viewport_position not in current_zephyr_subs and (not partyLeader):
        logger.debug('Skipping ... %s/%s/%s' % (game_viewport_position, game_quest_mission_state.instance, partyLeader))
        return
    if game_quest_mission_state.format.startswith('Zephyr error: See') or game_quest_mission_state.format.endswith('@(@color(blue))'):
        logger.debug('Skipping message we got from Zulip!')
        return
    if game_viewport_position == 'mail' and game_quest_mission_state.instance.lower() == 'inbox' and partyLeader and (not options.forward_mail_zephyrs):
        return
    if partyLeader:
        if chestCount.startswith('CC:'):
            objective_index = True
            gameObject = [to_zulip_username(game_coin_value.strip()) for game_coin_value in chestCount.split('\n')[0][4:].split()]
            if game_quest_mission_state.sender not in gameObject:
                gameObject.append(to_zulip_username(game_quest_mission_state.sender))
            chestCount = chestCount.split('\n', 1)[1]
    if options.forward_class_messages and game_quest_mission_state.opcode.lower() == 'crypt':
        chestCount = decrypt_zephyr(game_viewport_position, game_quest_mission_state.instance.lower(), chestCount)
    game_combat = {'time': str(game_quest_mission_state.time), 'sender': game_quest_mission_state.sender, 'zsig': gameWorld, 'content': chestCount}
    if objective_index:
        game_combat['type'] = 'private'
        game_combat['recipient'] = gameObject
    elif partyLeader:
        game_combat['type'] = 'private'
        game_combat['recipient'] = to_zulip_username(game_quest_mission_state.recipient)
    else:
        game_combat['type'] = 'stream'
        game_combat['stream'] = game_viewport_position
        if game_quest_mission_state.instance.strip() != '':
            game_combat['subject'] = game_quest_mission_state.instance
        else:
            game_combat['subject'] = '(instance "%s")' % (game_quest_mission_state.instance,)
    if partyLeader:
        if game_quest_mission_state.cls.lower() != 'message' and game_quest_mission_state.instance.lower != 'personal':
            game_sprite_sheet = '[-c %s -i %s]\n' % (game_quest_mission_state.cls, game_quest_mission_state.instance)
        elif game_quest_mission_state.cls.lower() != 'message':
            game_sprite_sheet = '[-c %s]\n' % (game_quest_mission_state.cls,)
        elif game_quest_mission_state.instance.lower() != 'personal':
            game_sprite_sheet = '[-i %s]\n' % (game_quest_mission_state.instance,)
        else:
            game_sprite_sheet = ''
        game_combat['content'] = game_sprite_sheet + game_combat['content']
    game_combat = decode_unicode_byte_strings(game_combat)
    logger.info('Received a message on %s/%s from %s...' % (game_viewport_position, game_quest_mission_state.instance, game_quest_mission_state.sender))
    if collisionLayer is not None:
        collisionLayer.write(json.dumps(game_combat) + '\n')
        collisionLayer.flush()
    if os.fork() == 0:
        global CURRENT_STATE
        CURRENT_STATE = States.ChildSending
        try:
            game_pixel = send_zulip(game_combat)
            if game_pixel.get('result') != 'success':
                logger.error('Error relaying zephyr:\n%s\n%s' % (game_combat, game_pixel))
        except Exception:
            logger.exception('Error relaying zephyr:')
        finally:
            os._exit(0)

