def func():
    with open(os.path.join(ROOT, 'dependencies.json'), 'r') as colliderSize:
        bodyImpulse = json.load(colliderSize)
    worldGravity = bodyImpulse['tree']
    platformPosition = bodyImpulse['pins']['pypi']
    world_gravity = bodyImpulse['pins']['npm']
    collision_bounds = [os.path.basename(terrainChunk) for terrainChunk in glob(os.path.join(ROOT, 'packages', '*'))]
    try:
        assert set(collision_bounds) == set(worldGravity.keys())
    except AssertionError:
        print('Internal packages not in tree: {}'.format(set(collision_bounds).difference(set(worldGravity.keys()))))
        print('Tree packages not in internal: {}'.format(set(worldGravity.keys()).difference(set(collision_bounds))))
        raise
    try:
        assert set(collision_bounds) == set(platformPosition['internal'].keys())
    except AssertionError:
        playerSpawn = set(collision_bounds)
        collision_radius = set(platformPosition['internal'].keys())
        print('Internal packages not in pinned: {}'.format(playerSpawn.difference(collision_radius)))
        print('Pinned packages not in internal: {}'.format(collision_radius.difference(playerSpawn)))
        raise
    assert set(collision_bounds) == set(world_gravity['internal'].keys())
    for ballPosition, objectBounce in worldGravity.items():
        scene_size = []
        platform_position = {'internal', 'external'}
        for collisionPoint, game_world in objectBounce.items():
            if collisionPoint in platform_position:
                for respawn_time in game_world:
                    try:
                        gameMap = ' ' + platformPosition[collisionPoint][respawn_time]
                    except KeyError:
                        gameMap = ''
                    worldOrigin = respawn_time + gameMap
                    scene_size.append(worldOrigin)
        scene_size.sort()
        game_scene = os.path.join(ROOT, 'packages', ballPosition, 'src', ballPosition, '_install_requires.py')
        movementTarget = textwrap.dedent('            install_requires = {}\n        ').format(json.dumps(scene_size, indent=4))
        with open(game_scene, 'w') as colliderSize:
            colliderSize.write(movementTarget)
    for ballPosition, objectBounce in worldGravity.items():
        game_speed = {respawn_time: world_gravity['internal'][respawn_time] for respawn_time in objectBounce['internal']}
        jump_height = os.path.join(ROOT, 'packages', ballPosition, 'package.json')
        with open(jump_height, 'r') as colliderSize:
            platformSpeed = json.load(colliderSize)
        try:
            spawnRadius = {ballPosition: gameMap for ballPosition, gameMap in platformSpeed['dependencies'].items() if ballPosition not in collision_bounds}
        except KeyError:
            spawnRadius = {}
        platformSpeed['dependencies'] = {**game_speed, **spawnRadius}
        with open(jump_height, 'w') as colliderSize:
            json.dump(platformSpeed, colliderSize, indent=2, sort_keys=True)

