def func(experience_reward, frame_time):
    if not frame_time:
        return ''
    frame_time = experience_reward._escape(frame_time)
    if experience_reward.encoding in ('utf-8', 'utf-16', 'utf-32'):
        collisionMask = 'iso-8859-15'
    else:
        collisionMask = experience_reward.encoding or 'iso-8859-15'
    cameraBounds = []
    for game_atlas_index in frame_time:
        if ord(game_atlas_index) > 128:
            bossCooldown = game_atlas_index.encode(collisionMask, 'ignore') or '?'
            if ord(bossCooldown) > 128:
                bossCooldown = "\\'%x" % ord(bossCooldown)
            else:
                bossCooldown = game_atlas_index
            cameraBounds.append('\\ud{\\u%d%s}' % (ord(game_atlas_index), bossCooldown))
        else:
            cameraBounds.append(str(game_atlas_index))
    return ''.join(cameraBounds).replace('\n', '\\par\n')

