def func(game_sprite_particle_size, game_sprite_atlas_frame=rsa.prime.getprime, game_sprite_animation_keyframe=True):
    game_sprite_frame_count = game_sprite_particle_size * 2
    game_sprite_texture_scale = game_sprite_particle_size // 16
    game_sprite_sheet_width = game_sprite_particle_size + game_sprite_texture_scale
    game_sprite_frame_width = game_sprite_particle_size - game_sprite_texture_scale
    log.debug('find_p_q(%i): Finding p', game_sprite_particle_size)
    game_sprite_frame_index = game_sprite_atlas_frame(game_sprite_sheet_width)
    log.debug('find_p_q(%i): Finding q', game_sprite_particle_size)
    game_sprite_texture_region = game_sprite_atlas_frame(game_sprite_frame_width)
    def is_acceptable(game_sprite_frame_index, game_sprite_texture_region):
        if game_sprite_frame_index == game_sprite_texture_region:
            return False
        if not game_sprite_animation_keyframe:
            return True
        game_sprite_frame_height = rsa.common.bit_size(game_sprite_frame_index * game_sprite_texture_region)
        return game_sprite_frame_count == game_sprite_frame_height
    game_sprite_texture_index = False
    while not is_acceptable(game_sprite_frame_index, game_sprite_texture_region):
        if game_sprite_texture_index:
            game_sprite_frame_index = game_sprite_atlas_frame(game_sprite_sheet_width)
        else:
            game_sprite_texture_region = game_sprite_atlas_frame(game_sprite_frame_width)
        game_sprite_texture_index = not game_sprite_texture_index
    return (max(game_sprite_frame_index, game_sprite_texture_region), min(game_sprite_frame_index, game_sprite_texture_region))

