def func(collision_mask, game_world_object):
    if collision_mask < 2:
        return False
    game_enemy_movement = collision_mask - 1
    game_player_input = 0
    while not game_enemy_movement & 1:
        game_player_input += 1
        game_enemy_movement >>= 1
    for _ in range(game_world_object):
        game_round_count = rsa.randnum.randint(collision_mask - 4) + 2
        game_backpack = pow(game_round_count, game_enemy_movement, collision_mask)
        if game_backpack == 1 or game_backpack == collision_mask - 1:
            continue
        for _ in range(game_player_input - 1):
            game_backpack = pow(game_backpack, 2, collision_mask)
            if game_backpack == 1:
                return False
            if game_backpack == collision_mask - 1:
                break
        else:
            return False
    return True

