def func(animationKeyframe, tile_texture):
    vertexNormal = animationKeyframe.lookup_fully_qualified(tile_texture)
    if vertexNormal is None:
        return None
    tileset = repr(vertexNormal.type)
    bone_index = '.'.join(tile_texture.split('.')[:-1])
    textureHeight = animationKeyframe._class_has_base(bone_index, _BASE_MODEL_FULLNAME)
    vertexPosition = animationKeyframe._class_has_base(tileset, _BASE_FIELD_FULLNAME)
    if textureHeight and vertexPosition:
        render_layer = animationKeyframe.lookup_fully_qualified(f'{tileset}.{_INSTANCE_TYPE_ATTR_NAME}')
        if render_layer is None:
            return None
        if render_layer.type is not None:
            tile_index = render_layer.type
            if isinstance(tile_index, FunctionLike) and tile_index.is_type_obj():
                tile_index = tile_index.items()[0].ret_type
        elif isinstance(render_layer.node, TypeAlias):
            tile_index = render_layer.node.target
        def resolve(_):
            return tile_index
        return resolve
    return None

