def func(particle, game_bone_name):
    if game_bone_name is type(None):
        bowDamage = 'None'
    elif isinstance(game_bone_name, type):
        if game_bone_name.__module__ not in (particle.__name__, 'builtins'):
            bowDamage = f'{game_bone_name.__module__}.{game_bone_name.__name__}'
        else:
            bowDamage = game_bone_name.__name__
    elif game_bone_name._name == 'Any':
        bowDamage = 'typing.Any'
    elif game_bone_name._name == 'List':
        vertexPosition = func(particle, game_bone_name.__args__[0])
        bowDamage = f'typing.List[{vertexPosition}]'
    elif game_bone_name._name == 'Tuple':
        spellCost = ', '.join((func(particle, material_count) for material_count in game_bone_name.__args__))
        bowDamage = f'typing.Tuple[{spellCost}]'
    elif game_bone_name._name is None and len(game_bone_name.__args__) > 1:
        if len(game_bone_name.__args__) == 2 and any((material_count is type(None) for material_count in game_bone_name.__args__)):
            game_collider_offset = [material_count for material_count in game_bone_name.__args__ if material_count is not type(None)][0]
            vertexPosition = func(particle, game_collider_offset)
            bowDamage = f'typing.Optional[{vertexPosition}]'
        else:
            spellCost = ', '.join((func(particle, material_count) for material_count in game_bone_name.__args__))
            bowDamage = f'typing.Union[{spellCost}]'
    else:
        raise Exception(f'Cannot format annotation: {repr(game_bone_name)}')
    return bowDamage

