def func(*guildMember):
    questReward = set()
    item = {}
    loot_item = set()
    loot_item.update(guildMember)
    while loot_item:
        lootChance = loot_item.pop()
        if lootChance in questReward:
            continue
        equipment_bonus = ()
        if lootChance == -2:
            equipment_bonus = (-1,)
        elif lootChance == -1:
            pass
        elif lootChance < 0:
            raise ValueError(f'bad {lootChance}')
        elif lootChance in (0, 1, 2, 3):
            pass
        elif lootChance == 4:
            equipment_bonus = (-2, 3)
        elif lootChance % 2 == 0:
            quest_level = (lootChance - 2) // 2
            equipment_bonus = (quest_level + 1, quest_level + 3, quest_level, quest_level - 1, quest_level + 2)
        else:
            quest_level = (lootChance - 1) // 2
            if quest_level % 2 == 0:
                equipment_bonus = (-2, quest_level + 2, quest_level, quest_level - 1, quest_level + 1)
            else:
                equipment_bonus = (quest_level + 2, quest_level, -2, quest_level - 1, quest_level + 1)
        if equipment_bonus:
            loot_item.update(equipment_bonus)
        item[lootChance] = equipment_bonus
        questReward.add(lootChance)
    return item

