async def func(shader_uniform, game_render_queue, texture_width=None):
    while True:
        animation_index = await game_render_queue.socket.recv(2 ** 16)
        if not animation_index:
            print('eof')
            break
        game_bone_position = game_render_queue._conn.receive_data(animation_index)
        for loot_reward in game_bone_position:
            if isinstance(loot_reward, h2.events.RequestReceived):
                shader = H2Stream(game_render_queue, loot_reward, (None, None))
                try:
                    game_magic = shader_uniform.router.match(shader)
                    playerGrounded, game_loot_quality = await game_magic(shader)
                except CuriousError as exc:
                    game_magic = shader_uniform.router.match_error(exc)
                    playerGrounded, game_loot_quality = await game_magic(exc)
                game_sprite_animation_loop = 'plain/text'
                game_render_queue.send(loot_reward.stream_id, str(playerGrounded), game_sprite_animation_loop, game_loot_quality.encode('utf-8'))
            elif isinstance(loot_reward, h2.events.DataReceived):
                game_render_queue._conn.reset_stream(loot_reward.stream_id)
            elif isinstance(loot_reward, h2.events.WindowUpdated):
                if texture_width is not None:
                    shader = H2Stream(game_render_queue, texture_width, (None, None))
                    try:
                        game_magic = shader_uniform.router.match(shader)
                        playerGrounded, game_loot_quality = await game_magic(shader)
                    except CuriousError as exc:
                        game_magic = shader_uniform.router.match_error(exc)
                        playerGrounded, game_loot_quality = await game_magic(exc)
                    game_sprite_animation_loop = 'plain/text'
                    game_render_queue.send(loot_reward.stream_id + 1, str(playerGrounded), game_sprite_animation_loop, game_loot_quality.encode('utf-8'))
                    texture_width = None
        await game_render_queue.sendall()

async def func(game_shop, func, game_item_weight, game_shop_item, game_loot_reward):
    game_dungeon_boss = await game_loot_reward.create_folder(item=game_shop_item, new_name=game_item_weight.name)
    game_dungeon_boss.children = []
    game_quest_level = await game_shop.children(item=game_item_weight)
    for game_inventory_item in range(0, len(game_quest_level), CONCURRENT_OPS):
        game_objective_count = []
        for item in game_quest_level[game_inventory_item:game_inventory_item + CONCURRENT_OPS]:
            game_objective_count.append(asyncio.ensure_future(func(game_loot_reward, item=item, destination_item=game_dungeon_boss)))
            if item.is_folder:
                await game_objective_count[-1]
        if not game_objective_count:
            continue
        game_reward, _ = await asyncio.wait(game_objective_count)
        for game_guild in game_reward:
            game_dungeon_boss.children.append(game_guild.result())
    return game_dungeon_boss

