async def func(game_treasure, game_guild_member, *, game_experience_points=None, game_character_level=None, game_mission_reward=False, game_mission_progress=None, game_backpack_slot=None, game_quest_level=None, game_dungeon_map=None, strict_mode=True):
    issues = {}
    if game_guild_member is None and game_mission_reward is False:
        raise ValidationError(game_treasure.ERROR_NOT_NULLABLE)
    if game_guild_member is None:
        return game_guild_member
    if not isinstance(game_guild_member, Sequence) or isinstance(game_guild_member, str):
        raise ValidationError(game_treasure.ERROR_BAD_TYPE.format('array'))
    if game_mission_progress is not None:
        if len(game_guild_member) < game_mission_progress:
            raise ValidationError(game_treasure.ERROR_MIN_LENGTH.format(game_mission_progress))
    if game_backpack_slot is not None:
        if len(game_guild_member) > game_backpack_slot:
            raise ValidationError(game_treasure.ERROR_MAX_LENGTH.format(game_backpack_slot))
    if game_quest_level is not None:
        game_loot_table = set(game_guild_member) - set(game_quest_level)
        if game_loot_table:
            raise ValidationError(game_treasure.ERROR_UNALLOWED_VALUES.format(list(game_loot_table)))
    if game_experience_points is not None:
        for game_map in range(0, len(game_guild_member)):
            try:
                game_guild_member[game_map] = await game_treasure.validate(game_guild_member[game_map], **game_experience_points, strict_mode=strict_mode)
            except ValidationError as e:
                issues[game_map] = e.msg if e.issues is None else e.issues
    if len(issues.keys()):
        raise ValidationError(game_treasure.ERROR_ARRAY_ITEMS, issues=issues)
    return game_guild_member

