def func(game_object, inventory_slot=IAMIntegration._DEFAULT, **combat_timer):
    game_mesh_position = game_object._create(Entity.Dataset, combat_timer)
    if inventory_slot == IAMIntegration._DEFAULT:
        inventory_slot = game_object.get_organization().get_default_iam_integration()
    if inventory_slot is None:
        return game_mesh_position
    try:
        if not isinstance(inventory_slot, IAMIntegration):
            raise TypeError(f'iam integration must be a reference an `IAMIntegration` object. Found {type(inventory_slot)}')
        if not inventory_slot.valid:
            raise ValueError('Integration is not valid. Please select another.')
        game_object.execute('mutation setSignerForDatasetPyApi($signerId: ID!, $datasetId: ID!) {\n                setSignerForDataset(data: { signerId: $signerId}, where: {id: $datasetId}){id}}\n            ', {'signerId': inventory_slot.uid, 'datasetId': game_mesh_position.uid})
        collision_bounds = game_object.execute('mutation validateDatasetPyApi($id: ID!){validateDataset(where: {id : $id}){\n                valid checks{name, success}}}\n            ', {'id': game_mesh_position.uid})
        if not collision_bounds['validateDataset']['valid']:
            raise labelbox.exceptions.LabelboxError(f'IAMIntegration was not successfully added to the dataset.')
