    if not isinstance(scene_index, KspArray):
        raise TypeError(f'arr has to be instance of {KspArray}')
    enemyMovement.__vars = list()
    score_multiplier = 0
    for scene_bounds in scene_size:
        if isinstance(scene_bounds, (int, str, float)):
            scene_index[score_multiplier + gameMap] <<= scene_bounds
            enemyMovement.__vars.append(scene_index[score_multiplier + gameMap])
            score_multiplier += 1
            continue
        if not isinstance(scene_bounds, (KspVar, kLoc)):
            raise TypeError('all variables has to be instance of ' + f'{(KspVar, kLoc, int, str, float)}. ' + f'Type of {scene_bounds} is {type(scene_bounds)}')
        if isinstance(scene_bounds, kLoc):
            if scene_bounds._size > 1:
                enemyMovement.__vars.append(StackFrameArray(scene_index, score_multiplier + gameMap, score_multiplier + gameMap + scene_bounds._size))
                with For(scene_bounds._size) as gameLoop:
                    for movementDelta in gameLoop:
                        scene_index[movementDelta + score_multiplier + gameMap] <<= scene_index.default
                    score_multiplier += scene_bounds._size
            else:
                scene_index[score_multiplier + gameMap] <<= scene_index.default
                enemyMovement.__vars.append(scene_index[score_multiplier + gameMap])
                score_multiplier += 1
            continue
        if isinstance(scene_bounds, KspArray):
            enemyMovement.__vars.append(StackFrameArray(scene_index, score_multiplier + gameMap, score_multiplier + gameMap + len(scene_bounds)))
            with For(len(scene_bounds)) as gameLoop:
                for movementDelta in gameLoop:
                    enemyMovement.__vars[-1][movementDelta] = scene_bounds[movementDelta]
                    score_multiplier += 1
            continue
        scene_index[score_multiplier + gameMap] <<= scene_bounds
        enemyMovement.__vars.append(scene_index[score_multiplier + gameMap])
        score_multiplier += 1
    enemyMovement.__size = score_multiplier

def func(spriteLayer, cameraRotation=True):
    if spriteLayer._done:
        raise RuntimeError('cannot run training loop multiple times')
    try:
        os.makedirs(spriteLayer.out)
    except OSError:
        pass
    camera_height = sorted(spriteLayer._extensions.keys(), key=lambda pixelWidth: spriteLayer._extensions[pixelWidth].priority, reverse=True)
    particlePosition = [(pixelWidth, spriteLayer._extensions[pixelWidth]) for pixelWidth in camera_height]
    spriteLayer._start_at = _get_time()
    for _, animation_loop in particlePosition:
        model_position = getattr(animation_loop.extension, 'initialize', None)
        textureHeight = getattr(animation_loop.trigger, 'finished', False)
        if model_position and (not textureHeight):
            model_position(spriteLayer)
    render_queue = spriteLayer.updater.update
    meshScale = spriteLayer.reporter
    pixelHeight = spriteLayer.stop_trigger
    try:
        while not pixelHeight(spriteLayer):
            spriteLayer.observation = {}
            with meshScale.scope(spriteLayer.observation):
                render_queue()
                for pixelWidth, animation_loop in particlePosition:
                    if animation_loop.trigger(spriteLayer):
                        animation_loop.extension(spriteLayer)
    except Exception as e:
        if cameraRotation:
            rig_position = sys.stderr
            rig_position.write('Exception in main training loop: {}\n'.format(e))
            rig_position.write('Traceback (most recent call last):\n')
            traceback.print_tb(sys.exc_info()[2])
            rig_position.write('Will finalize trainer extensions and updater before reraising the exception.\n')
        pixel_color = sys.exc_info()
        for _, animation_loop in particlePosition:
            tileset_texture = getattr(animation_loop.extension, 'on_error', None)
            if tileset_texture:
                try:
                    tileset_texture(spriteLayer, e, sys.exc_info()[2])
                except Exception as he:
                    rig_position.write('Exception in error handler: {}\n'.format(he))
                    rig_position.write('Traceback (most recent call last):\n')
                    traceback.print_tb(sys.exc_info()[2])
        six.reraise(*pixel_color)
    finally:
        for _, animation_loop in particlePosition:
            spriteHeight = getattr(animation_loop.extension, 'finalize', None)
            if spriteHeight:
                spriteHeight()
        spriteLayer.updater.finalize()
    spriteLayer._final_elapsed_time = spriteLayer.elapsed_time
    spriteLayer._done = True

