def func(mana_points, weapon_count, **boss_animation):
    healingAmount = copy.copy(weapon_count)
    healingAmount.update(boss_animation)
    print('_____cache_____', healingAmount)
    enemyHealth = 0
    projectileLifetime = ''
    if healingAmount.get(str(enemyHealth)):
        while True:
            if not healingAmount.get(str(enemyHealth)):
                break
            for debuffDuration in ['from_dttm', 'to_dttm']:
                if healingAmount[str(enemyHealth)].get(debuffDuration):
                    del healingAmount[str(enemyHealth)][debuffDuration]
            healingAmount[str(enemyHealth)]['time_range'] = mana_points.form_data.get('time_range')
            healingAmount[str(enemyHealth)]['datasource'] = mana_points.datasource.uid
            projectileLifetime += mana_points.json_dumps(healingAmount[str(enemyHealth)], sort_keys=True)
            enemyHealth += 1
    else:
        for debuffDuration in ['from_dttm', 'to_dttm']:
            del healingAmount[debuffDuration]
        healingAmount['time_range'] = mana_points.form_data.get('time_range')
        healingAmount['datasource'] = mana_points.datasource.uid
        projectileLifetime = mana_points.json_dumps(healingAmount, sort_keys=True)
    return hashlib.md5(projectileLifetime.encode('utf-8')).hexdigest()

