def func(game_sprite_animation_loop, gridPosition):
    if gridPosition:
        game_sprite_animation_loop.update_count(gridPosition)
    else:
        game_sprite_animation_loop.update_valid_canbe(gridPosition)
    itemBonus, skeletonCount = (False, False)
    game_goal_count, game_sprite_origin_position = (False, False)
    game_mission, goldReward = (False, False)
    for game_quest_timer in colors:
        game_animation_curve = len(game_sprite_animation_loop.bot.game.playedCards[game_quest_timer]) + 1
        for game_wizard in game_sprite_animation_loop.bot.values:
            if game_sprite_animation_loop.cantBe[game_quest_timer][game_wizard]:
                continue
            if game_wizard < game_animation_curve:
                skeletonCount = True
                game_sprite_origin_position = True
                game_mission = True
            elif game_wizard == game_animation_curve:
                itemBonus = True
                if not game_goal_count or not game_sprite_origin_position:
                    paletteColor = maxCards[game_wizard]
                    if game_sprite_animation_loop.bot.botPlayedCount[game_quest_timer][game_wizard] == paletteColor - 1:
                        game_goal_count = True
                    else:
                        game_sprite_origin_position = True
                goldReward = True
            else:
                skeletonCount = True
                if not game_goal_count or not game_sprite_origin_position:
                    if game_sprite_animation_loop.bot.isValuable(game_quest_timer, game_wizard):
                        game_goal_count = True
                    else:
                        game_sprite_origin_position = True
                if not game_mission or not goldReward:
                    if game_sprite_animation_loop.bot.isWorthless(game_quest_timer, game_wizard):
                        game_mission = True
                    else:
                        goldReward = True
        if itemBonus and game_goal_count and game_mission:
            break
    assert itemBonus or skeletonCount
    assert game_goal_count or game_sprite_origin_position
    assert game_mission or goldReward
    game_sprite_animation_loop.playable = (None if skeletonCount else True) if itemBonus else False
    game_sprite_animation_loop.valuable = (None if game_sprite_origin_position else True) if game_goal_count else False
    game_sprite_animation_loop.worthless = (None if goldReward else True) if game_mission else False
    if game_sprite_animation_loop.worthless is True:
        assert game_sprite_animation_loop.valuable is False
        assert game_sprite_animation_loop.playable is False

