def func(colliderCount):
    if colliderCount is None:
        return '?'
    if issubclass(colliderCount, Initializer) and colliderCount != Initializer:
        playerStamina = colliderCount()._init_function
        return f'{playerStamina.__module__}.{playerStamina.__name__}'
    item_price = getattr(colliderCount, '__origin__', None)
    quest_index = getattr(colliderCount, '__args__', ())
    if item_price == Dict:
        object_position, objectMass = quest_index
        return f'Dict[{func(object_position)}, {func(objectMass)}]'
    elif item_price in (Tuple, List, Sequence):
        return f"{_remove_prefix(str(item_price))}[{', '.join((func(object_scale) for object_scale in quest_index))}]"
    elif item_price == Union:
        if len(quest_index) == 2 and quest_index[-1] == type(None):
            return f'Optional[{func(quest_index[0])}]'
        else:
            return f"Union[{', '.join((func(object_scale) for object_scale in quest_index))}]"
    else:
        return _remove_prefix(f'{colliderCount.__module__}.{colliderCount.__name__}')

