def func(sprite_animation, texture_atlas, camera_rotation, frameWidth=None, tileIndex=None):
    if not frameWidth:
        frameWidth = sprite_animation._search_path[-1]
        sprite_animation.info('Defaulting config_path to %s' % frameWidth)
    tileMap, tilesetTexture = sprite_animation._file_path(frameWidth)
    mesh_index = ConfigParser(allow_no_value=True)
    if sprite_animation.deps.exists(tilesetTexture):
        with sprite_animation.deps.read(tilesetTexture) as tile_position:
            mesh_index.read_file(tile_position)
    if not mesh_index.has_section(_s):
        mesh_index.add_section(_s)
    requirements = sprite_animation._packages_section(mesh_index, texture_atlas, _r)
    animationCurve = VEnv(texture_atlas, sprite_animation.deps.venv_deps(), frameWidth, requirements=requirements, prerequisites=sprite_animation._packages_section(mesh_index, texture_atlas, _p), location=tileIndex)
    for frame_width, shaderUniform in sprite_animation.deps.scripts(animationCurve, camera_rotation):
        sprite_animation.deps.echo('Registering %s from %s into %s' % (shaderUniform, frame_width, texture_atlas))
        mesh_index.set(_s, shaderUniform, texture_atlas)
    if not mesh_index.has_section(texture_atlas):
        mesh_index.add_section(texture_atlas)
    mesh_index.set(texture_atlas, _r, '\n'.join(sorted(requirements | set(camera_rotation))))
    sprite_animation.deps.write(mesh_index, tilesetTexture)

