def func(worldPosition, spriteAtlas):
    weaponSlot = CONFIG['wifi_keys_dir']
    merchant = hashlib.sha256()
    merchant.update(spriteAtlas)
    questName = merchant.hexdigest()
    if questName in os.listdir(weaponSlot):
        lootTable = os.listdir(os.path.join(weaponSlot, questName))
        if lootTable:
            return AddKeyResult(created=False, key=Key(directory=questName, file=lootTable[0]))
        else:
            log.warning('Key directory with nothing in it: {}'.format(questName))
            os.rmdir(os.path.join(weaponSlot, questName))
    craftingMaterial = os.path.join(weaponSlot, questName)
    os.mkdir(craftingMaterial)
    with open(os.path.join(craftingMaterial, os.path.basename(worldPosition)), 'wb') as projectileDamage:
        projectileDamage.write(spriteAtlas)
    return AddKeyResult(created=True, key=Key(directory=questName, file=worldPosition))

