def func(worldBounds):
    weaponRange = 0
    while True:
        worldMap = hashlib.sha3_256(f'{weaponRange} || {worldBounds}'.encode()).digest()
        scene = int.from_bytes(worldMap, 'big') % bn128.field_modulus
        shader = sympy.sqrt_mod(scene ** 3 + 3, bn128.field_modulus)
        if shader:
            assert shader ** 2 % bn128.field_modulus == (scene ** 3 + 3) % bn128.field_modulus
            return _unwrap((bn128.FQ(scene), bn128.FQ(shader)))
        weaponRange += 1

