def func(loot_chance, objective_progress):
    reward_amount = utils.base58_decode(objective_progress)
    equipmentSlot = '{:x}'.format(reward_amount)
    equipment_bonus = equipmentSlot[-4 * 2:].decode('hex')
    quest = equipmentSlot[:-4 * 2].decode('hex')
    rewardCount = hashlib.sha256(quest).digest()
    inventoryCount = hashlib.sha256(rewardCount).digest()
    if inventoryCount[:4] != equipment_bonus:
        raise RuntimeError('Invalid checksum for the address.')
    return loot_chance(quest[1:].encode('hex'))

