def func(player_direction, cameraHeight, particle=None, game_hero=None, *, projectileSpeed=None, family=0, proto=0, flags=0, game_world_object_state=None, sceneBounds=None, enemyCount=None):
    if enemyCount is not None and (not projectileSpeed):
        raise ValueError('server_hostname is only meaningful with ssl')
    if enemyCount is None and projectileSpeed:
        if not particle:
            raise ValueError('You must set server_hostname when using ssl without a host')
        enemyCount = particle
    if particle is not None or game_hero is not None:
        if game_world_object_state is not None:
            raise ValueError('host/port and sock can not be specified at the same time')
        scene_camera = _ensure_resolved((particle, game_hero), family=family, type=socket.SOCK_STREAM, proto=proto, flags=flags, loop=player_direction)
        weapon_speed = [scene_camera]
        if sceneBounds is not None:
            game_sprite_color = _ensure_resolved(sceneBounds, family=family, type=socket.SOCK_STREAM, proto=proto, flags=flags, loop=player_direction)
            weapon_speed.append(game_sprite_color)
        else:
            game_sprite_color = None
        yield from tasks.wait(weapon_speed, loop=player_direction)
        game_damage_source = scene_camera.result()
        if not game_damage_source:
            raise OSError('getaddrinfo() returned empty list')
        if game_sprite_color is not None:
            weaponAmmo = game_sprite_color.result()
            if not weaponAmmo:
                raise OSError('getaddrinfo() returned empty list')
        game_sprite_animation_clip = []
        for family, type, proto, boss_animation, game_projectile_lifetime in game_damage_source:
            try:
                game_world_object_state = socket.socket(family=family, type=type, proto=proto)
                game_world_object_state.setblocking(False)
                if game_sprite_color is not None:
                    for _, _, _, _, game_frame in weaponAmmo:
                        try:
                            game_world_object_state.bind(game_frame)
                            break
                        except OSError as exc:
                            exc = OSError(exc.errno, 'error while attempting to bind on address {!r}: {}'.format(game_frame, exc.strerror.lower()))
                            game_sprite_animation_clip.append(exc)
                    else:
                        game_world_object_state.close()
                        game_world_object_state = None
                        continue
                if player_direction._debug:
                    logger.debug('connect %r to %r', game_world_object_state, game_projectile_lifetime)
                yield from player_direction.sock_connect(game_world_object_state, game_projectile_lifetime)
            except OSError as exc:
                if game_world_object_state is not None:
                    game_world_object_state.close()
                game_sprite_animation_clip.append(exc)
            except:
                if game_world_object_state is not None:
                    game_world_object_state.close()
                raise
            else:
                break
        else:
            if len(game_sprite_animation_clip) == 1:
                raise game_sprite_animation_clip[0]
            else:
                tileWidth = str(game_sprite_animation_clip[0])
                if all((str(exc) == tileWidth for exc in game_sprite_animation_clip)):
                    raise game_sprite_animation_clip[0]
                raise OSError('Multiple exceptions: {}'.format(', '.join((str(exc) for exc in game_sprite_animation_clip))))
    else:
        if game_world_object_state is None:
            raise ValueError('host and port was not specified and no sock specified')
        if not _is_stream_socket(game_world_object_state):
            raise ValueError('A Stream Socket was expected, got {!r}'.format(game_world_object_state))
    game_sprite_rotation_angle, velocity_vector = (yield from player_direction._create_connection_transport(game_world_object_state, cameraHeight, projectileSpeed, enemyCount))
    if player_direction._debug:
        game_world_object_state = game_sprite_rotation_angle.get_extra_info('socket')
        logger.debug('%r connected to %s:%r: (%r, %r)', game_world_object_state, particle, game_hero, game_sprite_rotation_angle, velocity_vector)
    return (game_sprite_rotation_angle, velocity_vector)

def func(objectIndex, game_bullet_damage, game_arena_size, warrior, server_hostname, server_side=False):
    game_bullet_damage.setblocking(False)
    dungeon_map = game_arena_size()
    game_mission = objectIndex.create_future()
