def func(mesh_index, sprite_texture, game_texture_data=None, gameScore=None, *, family=socket.AF_UNSPEC, flags=socket.AI_PASSIVE, board_cell=None, gameSpeed=100, collision_bounds=None, game_sprite_bounds_height=None, inventory_item=None):
    if isinstance(collision_bounds, bool):
        raise TypeError('ssl argument must be an SSLContext or None')
    if game_texture_data is not None or gameScore is not None:
        if board_cell is not None:
            raise ValueError('host/port and sock can not be specified at the same time')
        battle = getattr(socket, 'AF_INET6', 0)
        if game_sprite_bounds_height is None:
            game_sprite_bounds_height = os.name == 'posix' and sys.platform != 'cygwin'
        game_mana = []
        if game_texture_data == '':
            game_collision_depth = [None]
        elif isinstance(game_texture_data, str) or not isinstance(game_texture_data, collections.Iterable):
            game_collision_depth = [game_texture_data]
        else:
            game_collision_depth = game_texture_data
        jump_speed = [mesh_index._create_server_getaddrinfo(game_texture_data, gameScore, family=family, flags=flags) for game_texture_data in game_collision_depth]
        game_loot_count = (yield from tasks.gather(*jump_speed, loop=mesh_index))
        game_loot_count = set(itertools.chain.from_iterable(game_loot_count))
        rewardLevel = False
        try:
            for game_arrow_speed in game_loot_count:
                game_wave_index, pixelHeight, camera_target, quest_reward, game_ball_position = game_arrow_speed
                try:
                    board_cell = socket.socket(game_wave_index, pixelHeight, camera_target)
                except socket.error:
                    if mesh_index._debug:
                        logger.warning('create_server() failed to create socket.socket(%r, %r, %r)', game_wave_index, pixelHeight, camera_target, exc_info=True)
                    continue
                game_mana.append(board_cell)
                if game_sprite_bounds_height:
                    board_cell.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, True)
                if inventory_item:
                    _set_reuseport(board_cell)
                if game_wave_index == battle and hasattr(socket, 'IPPROTO_IPV6'):
                    board_cell.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, True)
                try:
                    board_cell.bind(game_ball_position)
                except OSError as err:
                    raise OSError(err.errno, 'error while attempting to bind on address %r: %s' % (game_ball_position, err.strerror.lower()))
            rewardLevel = True
        finally:
            if not rewardLevel:
                for board_cell in game_mana:
                    board_cell.close()
    else:
        if board_cell is None:
            raise ValueError('Neither host/port nor sock were specified')
        if not _is_stream_socket(board_cell):
            raise ValueError('A Stream Socket was expected, got {!r}'.format(board_cell))
        game_mana = [board_cell]
    game_bone_index = Server(mesh_index, game_mana)
    for board_cell in game_mana:
        board_cell.listen(gameSpeed)
        board_cell.setblocking(False)
        mesh_index._start_serving(sprite_texture, board_cell, collision_bounds, game_bone_index, gameSpeed)
    if mesh_index._debug:
        logger.info('%r is serving', game_bone_index)
    return game_bone_index

