def func(projectile_radius, atlas_index, enemyState, arena_size, criticalDamage, player_velocity, player_health, spellLevel, potion, spellDamage, player_position, mana_bar):
    projectile_lifetime = []
    for arena_round in projectile_radius:
        damage_target, weaponCount, spell_range, projectileLifetime = cv2.boundingRect(arena_round)
        if spell_range < arena_size or spell_range > criticalDamage:
            continue
        if projectileLifetime < player_velocity or projectileLifetime > player_health:
            continue
        weaponSpeed = cv2.contourArea(arena_round)
        if weaponSpeed < atlas_index:
            continue
        if cv2.arcLength(arena_round, True) < enemyState:
            continue
        itemStack = cv2.convexHull(arena_round)
        damageType = 100 * weaponSpeed / cv2.contourArea(itemStack)
        if damageType < spellLevel[0] or damageType > spellLevel[1]:
            continue
        if len(arena_round) < spellDamage or len(arena_round) > potion:
            continue
        magic_damage = float(spell_range) / projectileLifetime
        if magic_damage < player_position or magic_damage > mana_bar:
            continue
        projectile_lifetime.append(arena_round)
    return projectile_lifetime

