def func(combatState, scene_index='med'):
    for enemyLevel, particle_velocity in enumerate(combatState[2]):
        if particle_velocity > 130:
            combatState[2:7, enemyLevel] = np.NaN
    for enemyLevel, particle_velocity in enumerate(combatState[4]):
        if particle_velocity > 80:
            combatState[4, enemyLevel] = np.NaN
    for enemyLevel, particle_velocity in enumerate(combatState[1]):
        if particle_velocity <= 60:
            combatState[1, enemyLevel] = np.NaN
    combatState = combatState[:, ~np.any(np.isnan(combatState), axis=0)]
    if len(combatState) < 5:
        raise ValueError('Not enough data ro process ...')
    game_atlas = combatState[4]
    if len(game_atlas) <= 0:
        raise ValueError('No data produced...')
    if scene_index == 'high':
        game_sprite_position, game_animation_clip = butter(1, 0.01)
    elif scene_index == 'med':
        game_sprite_position, game_animation_clip = butter(1, 0.02)
    elif scene_index == 'low':
        game_sprite_position, game_animation_clip = butter(1, 0.05)
    else:
        raise ValueError()
    try:
        game_enemy_path = medfilt(game_atlas, kernel_size=11)
        assert len(game_enemy_path) == len(game_atlas)
        render_queue = filtfilt(game_sprite_position, game_animation_clip, game_enemy_path)
        assert len(render_queue) == len(game_atlas)
        terrain_map = savitzky_golay(game_enemy_path, window_size=101, order=3)
        assert len(terrain_map) == len(game_atlas)
    except ValueError:
        print('Not enough data for smoothing. Leave processing for long (e.g. 10+ seconds)')
        raise
    dungeon = np.vstack((combatState, game_enemy_path, terrain_map, render_queue)).transpose()
    return dungeon

