def func(combat, hitbox_offset):
    jump_speed = cast(List[Clamp], combat.filter_types(combat.selections, Clamp))
    if len(jump_speed) > 0:
        bodyTorque = jump_speed[0]
    else:
        bodyTorque = None
    if hitbox_offset.mono == 0:
        bossCooldown = (1, 1, -1, -1)
    elif hitbox_offset.mono == 1:
        bossCooldown = (1, 1)
    else:
        bossCooldown = (-1, -1)
    dungeon_loot = []
    for damage_target, enemySpawn in enumerate(bossCooldown):
        spellLevel = combat.order(desc=False if enemySpawn == 1 else True)
        spell_count, playerDamage = hitbox_offset.values
        if bodyTorque is not None:
            spell_count = max(spell_count, bodyTorque.ll)
            playerDamage = min(playerDamage, bodyTorque.ul)
        battle_round = combat.selections.index(hitbox_offset)
        weapon_range = spellLevel[battle_round]
        arena = []
        for game_object in spellLevel:
            if game_object is None:
                arena.append(None)
            elif game_object < weapon_range:
                arena.append(spell_count - 1 - (weapon_range - game_object))
            elif game_object == weapon_range:
                if damage_target % 2 == 0:
                    arena.append(spell_count - 1)
                else:
                    arena.append(playerDamage + 1)
            else:
                arena.append(playerDamage + 1 - (weapon_range - game_object))
        arena[battle_round] = None
        damage = [FittedSelection(player_stamina, playerWeapon) for player_stamina, playerWeapon in zip(combat.selections, arena)]
        dungeon_loot.append(Blueprint(damage, enemySpawn))
    return dungeon_loot

