def func(rigid_body, camera_offset, sprite_size, bodyMass, worldBounds, playerSpeed, worldTile=False):
    scene_object = camera_offset.gradient(sprite_size, bodyMass) * playerSpeed
    if worldTile:
        movementDelta = -np.ones_like(scene_object)
    else:
        movementDelta = np.sum([camera_offset.gradient(sprite_size, worldOrigin) * playerSpeed - scene_object for worldOrigin in worldBounds], 0)
    game_score = np.abs(scene_object) * np.abs(movementDelta) * np.sign(scene_object * movementDelta)
    platform_speed = np.argmin(game_score)
    platform_speed = np.unravel_index(platform_speed, playerSpeed.shape)
    world_position = np.sign(scene_object)[platform_speed]
    return (platform_speed, world_position)

