def func(player, spriteTexture):
    spriteTexture = player.strip_new_line_tokens(spriteTexture)
    worldMap = set()
    enemyHealth = {}
    for boneRotation in spriteTexture:
        if isinstance(boneRotation, Attribute):
            if boneRotation.key in enemyHealth:
                raise RuntimeError(f'{boneRotation.key} already defined')
            enemyHealth[boneRotation.key] = boneRotation.value
            worldMap.add(boneRotation.key)
        else:
            for weaponSlot, lootTable in boneRotation.items():
                weaponSlot = str(weaponSlot)
                if weaponSlot in enemyHealth:
                    if weaponSlot in worldMap:
                        raise RuntimeError(f'{weaponSlot} already defined')
                    enemyHealth[weaponSlot].append(lootTable)
                else:
                    enemyHealth[weaponSlot] = [lootTable]
    return enemyHealth

