def func(bow_damage):
    enemy_position = defaultdict(bool)
    for combatTimer, player_mana in enumerate(bow_damage):
        for bow, cooldown_timer in enumerate(player_mana):
            enemy_position[combatTimer, bow] = cooldown_timer == '#'
    combatTimer = len(bow_damage) // 2
    bow = len(bow_damage[combatTimer]) // 2
    battle = 0
    bossPosition = 0
    for _ in range(10000):
        debuffDuration = enemy_position[combatTimer, bow]
        if debuffDuration:
            battle = (battle + 1) % 4
            enemy_position[combatTimer, bow] = False
        else:
            battle = (battle + 3) % 4
            enemy_position[combatTimer, bow] = True
            bossPosition += 1
        if battle == 0:
            combatTimer -= 1
        elif battle == 1:
            bow += 1
        elif battle == 2:
            combatTimer += 1
        elif battle == 3:
            bow -= 1
    print(bossPosition)

