def func(game_world_map_width, game_world_spawn_position, game_world_viewport_position):
    if len(game_world_map_width) % 16 == 0:
        game_world_grid_height = len(game_world_map_width) // 16
    else:
        game_world_grid_height = len(game_world_map_width) // 16 + 1
    game_world_ground_tile = []
    game_world_scene_index = None
    for game_world_grid_index in range(0, game_world_grid_height):
        game_world_terrain_texture = game_world_map_width[game_world_grid_index * 16:(game_world_grid_index + 1) * 16]
