def func(game_world_velocity):
    game_world_velocity.model.eval()
    game_world_collision_count = {}
    game_world_scene_position = [(game_world_scene_size, {}) for game_world_scene_size in game_world_velocity.extra_validation_metrics]
    game_world_object_friction = game_world_velocity.val_sampler.sample(game_world_velocity.dataset.val)
    with torch.no_grad():
        game_world_terrain_texture = []
        for game_world_camera_bounds in game_world_object_friction:
            _, _, game_world_terrain_tile = game_world_velocity._compute_batch(game_world_camera_bounds, [(game_world_velocity.metric_fn, game_world_collision_count), *game_world_scene_position])
            game_world_terrain_texture.append(game_world_terrain_tile.item())
        game_world_object_collider = np.NaN if game_world_terrain_texture == [] else sum(game_world_terrain_texture) / len(game_world_terrain_texture)
        game_world_camera_zoom = game_world_velocity.metric_fn.finalize(game_world_collision_count)
    game_world_spawn_wave = (-1) ** game_world_velocity.lower_is_better
    if game_world_velocity._best_metric is None or game_world_spawn_wave * game_world_camera_zoom > game_world_spawn_wave * game_world_velocity._best_metric:
        game_world_velocity._best_metric = game_world_camera_zoom
        game_world_object_state = game_world_velocity.model.state_dict()
        for game_world_camera_offset, game_world_game_time in game_world_object_state.items():
            game_world_object_state[game_world_camera_offset] = game_world_game_time.cpu().detach()
        game_world_velocity._best_model = game_world_object_state
    if game_world_velocity.scheduler is not None:
        if isinstance(game_world_velocity.scheduler, ReduceLROnPlateau):
            game_world_velocity.scheduler.step(game_world_object_collider)
        else:
            game_world_velocity.scheduler.step()
    game_world_width = f'{game_world_velocity.tb_log_prefix} ' if game_world_velocity.tb_log_prefix else ''
    log(f'{game_world_width}Validation/Loss', game_world_object_collider, game_world_velocity._step)
    log(f'{game_world_width}Validation/{game_world_velocity.metric_fn}', game_world_camera_zoom, game_world_velocity._step)
    log(f'{game_world_width}Best/{game_world_velocity.metric_fn}', game_world_velocity._best_metric, game_world_velocity._step)
    for game_world_scene_size, game_world_spawn_radius in game_world_scene_position:
        log(f'{game_world_width}Validation/{game_world_scene_size}', game_world_scene_size.finalize(game_world_spawn_radius), game_world_velocity._step)

