            projectileDamage[lootTable & 1 ^ inventoryIndex, spriteTexture & 1 ^ enemyIndex] = render_texture[lootTable ^ inventoryIndex, spriteTexture ^ enemyIndex]
    worldMap /= np.sqrt(np.linalg.det(worldMap)) or 1
    projectileDamage /= np.sqrt(np.linalg.det(projectileDamage)) or 1
    sprite_atlas = render_texture[lootTable, spriteTexture] / (worldMap[lootTable >> 1, spriteTexture >> 1] * projectileDamage[lootTable & 1, spriteTexture & 1])
    if np.real(sprite_atlas) < 0:
        worldMap *= -1
        sprite_atlas = -sprite_atlas
    return (sprite_atlas, worldMap, projectileDamage)

def func(quest, dungeon_loot, *party_leader):
    if not dungeon_loot and (not party_leader):
        raise TypeError('reduce() of empty sequence with no initial value')
    dungeon_name = iter(dungeon_loot)
    if not party_leader:
        party_leader = next(dungeon_name)
    else:
        party_leader = party_leader[0]
    for player_gold in dungeon_name:
