def func(player, worldVelocity, lootTable, player_grounded, game_round, bodyFriction, enemy_direction):
    objectVelocity = worldVelocity.shape[0]
    collider_radius = 2 * bodyFriction / (enemy_direction ** 2 + EPS)
    bodyTorque = np.sign(bodyFriction) * np.inf
    spriteTexture = collider_radius
    enemyIndex = 0
    while True:
        enemyIndex += 1
        boardHeight = 0
        gameLoop = 0
        if bodyFriction > 0:
            for projectileDamage in range(objectVelocity):
                sceneCount = spriteTexture * lootTable[projectileDamage] / 2
                if lootTable[projectileDamage] > 0:
                    enemyDirection = game_round - worldVelocity[projectileDamage]
                    worldMap = min(enemyDirection, sceneCount)
                    boardHeight += lootTable[projectileDamage] * worldMap
                    gameLoop += worldMap ** 2
                else:
                    enemyDirection = player_grounded - worldVelocity[projectileDamage]
                    worldMap = max(enemyDirection, sceneCount)
                    boardHeight += lootTable[projectileDamage] * worldMap
                    gameLoop += worldMap ** 2
        else:
            for projectileDamage in range(objectVelocity):
                sceneCount = spriteTexture * lootTable[projectileDamage] / 2
                if lootTable[projectileDamage] > 0:
                    enemyDirection = player_grounded - worldVelocity[projectileDamage]
                    worldMap = max(enemyDirection, sceneCount)
                    boardHeight += lootTable[projectileDamage] * worldMap
                    gameLoop += worldMap ** 2
                else:
                    enemyDirection = game_round - worldVelocity[projectileDamage]
                    worldMap = min(enemyDirection, sceneCount)
                    boardHeight += lootTable[projectileDamage] * worldMap
                    gameLoop += worldMap ** 2
        if np.abs(boardHeight) < np.abs(bodyFriction):
            if np.isinf(bodyTorque):
                spriteTexture *= 2
            else:
                collider_radius = spriteTexture
                spriteTexture = (bodyTorque - collider_radius) / 2 + collider_radius
        else:
            bodyTorque = spriteTexture
            spriteTexture = (bodyTorque - collider_radius) / 2 + collider_radius
        if 0.999 * np.abs(bodyFriction) - EPS < np.abs(boardHeight) < 1.001 * np.abs(bodyFriction) + EPS:
            break
    return np.sqrt(gameLoop)

def func(itemCount, questTarget, questStage, dungeonLevel, treasure_chest, questName, guild_count, dungeon, questIndex):
    portal, chest_level = questTarget
    dungeonRoom = questStage.shape[0]
    player_inventory = 0
    portal_position = 0
    item_level = 0
    if chest_level > 0:
        for game_world_map_origin in range(dungeonRoom):
            quest_reward = questStage[game_world_map_origin] - dungeonLevel[game_world_map_origin]
            game_world_spawn_point = treasure_chest[game_world_map_origin]
            missionState = 1 / (2 * chest_level + EPS)
            party_leader = -portal * game_world_spawn_point * missionState - quest_reward
            if np.abs(party_leader) - missionState < 0:
                game_world_chunk = quest_reward
            else:
                game_world_chunk = np.sign(party_leader) * (np.abs(party_leader) - missionState) + quest_reward
                if game_world_chunk + dungeonLevel[game_world_map_origin] < questName:
                    game_world_chunk = questName - dungeonLevel[game_world_map_origin]
                elif game_world_chunk + dungeonLevel[game_world_map_origin] > guild_count:
                    game_world_chunk = guild_count - dungeonLevel[game_world_map_origin]
                else:
                    achievement_progress = np.sign(game_world_chunk - quest_reward) + 2 * chest_level * game_world_chunk + portal * game_world_spawn_point
                    portal_position -= achievement_progress * game_world_spawn_point * missionState
                    item_level -= achievement_progress * 2 * game_world_chunk * missionState
            player_inventory += np.abs(quest_reward - game_world_chunk) + chest_level * game_world_chunk ** 2 + portal * game_world_spawn_point * game_world_chunk
            portal_position += game_world_spawn_point * game_world_chunk
            item_level += game_world_chunk ** 2
    else:
        for game_world_map_origin in range(dungeonRoom):
            quest_reward = questStage[game_world_map_origin] - dungeonLevel[game_world_map_origin]
            game_world_spawn_point = treasure_chest[game_world_map_origin]
            if np.abs(portal * game_world_spawn_point) < 1:
                game_world_chunk = quest_reward
            elif np.sign(portal * game_world_spawn_point) < 0:
                game_world_chunk = guild_count - dungeonLevel[game_world_map_origin]
            else:
                game_world_chunk = questName - dungeonLevel[game_world_map_origin]
            player_inventory += np.abs(quest_reward - game_world_chunk) + chest_level * game_world_chunk ** 2 + portal * game_world_spawn_point * game_world_chunk
            portal_position += game_world_spawn_point * game_world_chunk
            item_level += game_world_chunk ** 2
    player_inventory += -chest_level * questIndex ** 2 - portal * dungeon
    portal_position -= dungeon
    item_level -= questIndex ** 2
    return (-player_inventory, -np.array([portal_position, item_level]))

