def func(game_sprite_render_texture, game_sprite_texture_format, game_sprite_animation_state):
    if game_sprite_render_texture.get('ANGLE') == 0.0 and game_sprite_render_texture.get('B') is not None:
        game_sprite_frame = game_sprite_render_texture['B'] / game_sprite_texture_format.brho
        game_sprite_render_texture['ANGLE'] = game_sprite_render_texture['L'] * game_sprite_frame
    if game_sprite_render_texture['ANGLE'] == 0.0:
        game_sprite_animation_keyframe = 0 * _ureg.tesla
    else:
        game_sprite_animation_keyframe = game_sprite_texture_format.brho / (game_sprite_render_texture['L'] / _np.abs(game_sprite_render_texture['ANGLE']))
    if _np.isnan(game_sprite_render_texture['E1']):
        game_sprite_texture_index = 0.0 * _ureg.radian
    else:
        game_sprite_texture_index = game_sprite_render_texture['E1']
    if _np.isnan(game_sprite_render_texture['E2']):
        game_sprite_texture_region = 0.0 * _ureg.radian
    else:
        game_sprite_texture_region = game_sprite_render_texture['E2']
    if _np.isnan(game_sprite_render_texture['TILT']):
        game_sprite_texture_size = 0.0 * _ureg.radian
    else:
        game_sprite_texture_size = game_sprite_render_texture['TILT']
    if game_sprite_animation_state.get('command', Bend) == Bend:
        game_sprite_frame_duration = Bend(game_sprite_render_texture.name[0:_ZGOUBI_LABEL_LENGTH], XL=game_sprite_render_texture['L'], B1=game_sprite_animation_keyframe, KPOS=3, W_E=game_sprite_texture_index * _np.sign(game_sprite_render_texture['ANGLE']), W_S=game_sprite_texture_region * _np.sign(game_sprite_render_texture['ANGLE']), KINEMATICS=game_sprite_texture_format, LENGTH_IS_ARC_LENGTH=game_sprite_animation_state.get('LENGTH_IS_ARC_LENGTH', True))
    elif game_sprite_animation_state.get('command') == Dipole:
        if game_sprite_render_texture.N is not None and (not _np.isnan(game_sprite_render_texture.N)):
            game_sprite_layer_index = game_sprite_render_texture.N
        elif game_sprite_render_texture.K1 is not None and (not _np.isnan(game_sprite_render_texture.K1)):
            game_sprite_layer_index = -(_np.abs(game_sprite_render_texture.L / game_sprite_render_texture.ANGLE).to('m') ** 2 * getattr(game_sprite_render_texture, 'K1', 0.0 * _ureg.m ** (-2))).magnitude
        else:
            game_sprite_layer_index = 0
        game_sprite_frame_duration = Dipole(game_sprite_render_texture.name[0:_ZGOUBI_LABEL_LENGTH], RM=_np.abs(game_sprite_render_texture.L / game_sprite_render_texture.ANGLE), AT=_np.abs(game_sprite_render_texture.ANGLE), B0=game_sprite_animation_keyframe, N=game_sprite_layer_index)
    if game_sprite_render_texture['TILT'] != 0:
        game_sprite_frame_duration.COLOR = 'goldenrod'
    if game_sprite_render_texture['ANGLE'] < 0:
        return [ChangeRef(game_sprite_render_texture.name + '_CRL', TRANSFORMATIONS=[['XR', -(-game_sprite_texture_size + _np.pi * _ureg.radian)]]), game_sprite_frame_duration, ChangeRef(game_sprite_render_texture.name + '_CRR', TRANSFORMATIONS=[['XR', -game_sprite_texture_size + _np.pi * _ureg.radian]])]
    elif _np.isnan(game_sprite_render_texture['TILT']) or game_sprite_render_texture['TILT'] == 0:
        return [game_sprite_frame_duration]
    else:
        return [ChangeRef(game_sprite_render_texture.name + '_CRL', TRANSFORMATIONS=[['XR', game_sprite_texture_size]]), game_sprite_frame_duration, ChangeRef(game_sprite_render_texture.name + '_CRR', TRANSFORMATIONS=[['XR', -game_sprite_texture_size]])]

