def func(object_collider, material, atlas):
    if object_collider >= 0:
        pass
    else:
        raise ValueError
    game_quest_objective = object_collider
    playerJump = game_quest_objective * game_quest_objective
    game_skeleton_count = game_quest_objective * playerJump
    spell = playerJump * playerJump
    characterStats = game_quest_objective * spell
    cameraOffset = game_skeleton_count * game_skeleton_count
    player_stamina = -4.7373389813783836e-24 * cameraOffset + 2.0438283336061252e-15 * spell - 1.363894795463638e-07 * playerJump + 1
    player_score = 1.3066122574128241e-19 * characterStats - 2.1181508875186556e-11 * game_skeleton_count + 0.0005559488023498643 * game_quest_objective
    warrior = 0.0001246332637532143 * game_quest_objective / sqrt(player_stamina * player_stamina + player_score * player_score)
    if atlas == 'db':
        if material == '1khz':
            return 0.0 if warrior == 0.0 else DB_GAIN_1KHZ + 20.0 * log10(warrior)
        elif material == '2khz':
            return 0.0 if warrior == 0.0 else DB_GAIN_2KHZ + 20.0 * log10(warrior)
        else:
            raise ValueError
    elif atlas == 'factor':
        if material == '1khz':
            return FACTOR_GAIN_1KHZ * warrior
        elif material == '2khz':
            return FACTOR_GAIN_2KHZ * warrior
        else:
            raise ValueError
    else:
        raise ValueError

