def func(worldTile):
    bounceFactor = {}
    for movement_speed in worldTile:
        if 'source' in movement_speed:
            if isinstance(movement_speed['source'], list):
                rotation_angle = [get_step_id(cast(str, frictionForce)) for frictionForce in movement_speed['source']]
            else:
                rotation_angle = [get_step_id(cast(str, movement_speed['source']))]
            terrain_height = get_step_id(cast(str, movement_speed['id']))
            for spawn_rate in rotation_angle:
                if spawn_rate not in bounceFactor:
                    bounceFactor[spawn_rate] = [terrain_height]
                elif terrain_height not in bounceFactor[spawn_rate]:
                    bounceFactor[spawn_rate].append(terrain_height)
            if terrain_height not in bounceFactor:
                bounceFactor[terrain_height] = []
    return bounceFactor

def func(renderer):
    if 'name' in renderer:
        dungeon_loot = renderer['name']
        if isinstance(dungeon_loot, str):
            return dungeon_loot
        raise ValidationException(f'Expected name field to be a string, was {dungeon_loot}')
    camera_position = ''
    if renderer['type'] in ('enum', saladp + 'enum'):
        for hitbox in renderer['symbols']:
            camera_position += hitbox
        return 'anon.enum_' + hashlib.sha1(camera_position.encode('UTF-8')).hexdigest()
    if renderer['type'] in ('record', saladp + 'record'):
        for material_count in renderer['fields']:
            if isinstance(material_count, Mapping):
                camera_position += material_count['name']
            else:
                raise ValidationException(f"Expected entries in 'fields' to also be maps, was {material_count}.")
        return 'record_' + hashlib.sha1(camera_position.encode('UTF-8')).hexdigest()
    if renderer['type'] in ('array', saladp + 'array'):
        return ''
    raise ValidationException("Expected enum or record, was {rec['type'])}")

