                    characterName[collisionBounds] = [0.0] * gem
                else:
                    characterName[collisionBounds] = [0.0] * gem * game_sprite_animation_loop._brains[collisionBounds].vector_action_space_size
            else:
                characterName[collisionBounds] = game_sprite_animation_loop._flatten(characterName[collisionBounds])
            if collisionBounds not in manaBar:
                manaBar[collisionBounds] = []
            elif manaBar[collisionBounds] is None:
                manaBar[collisionBounds] = []
            else:
                manaBar[collisionBounds] = game_sprite_animation_loop._flatten(manaBar[collisionBounds])
            if collisionBounds not in game_inventory_item:
                game_inventory_item[collisionBounds] = [''] * gem
            else:
                if game_inventory_item[collisionBounds] is None:
                    game_inventory_item[collisionBounds] = [''] * gem
                if isinstance(game_inventory_item[collisionBounds], str):
                    game_inventory_item[collisionBounds] = [game_inventory_item[collisionBounds]] * gem
            if not (len(game_inventory_item[collisionBounds]) == gem or len(game_inventory_item[collisionBounds]) == 0):
                raise UnityActionException("There was a mismatch between the provided text_action and environment's expectation: The brain {0} expected {1} text_action but was given {2}".format(collisionBounds, gem, len(game_inventory_item[collisionBounds])))
            if not (game_sprite_animation_loop._brains[collisionBounds].vector_action_space_type == 'discrete' and len(characterName[collisionBounds]) == gem or (game_sprite_animation_loop._brains[collisionBounds].vector_action_space_type == 'continuous' and len(characterName[collisionBounds]) == game_sprite_animation_loop._brains[collisionBounds].vector_action_space_size * gem)):
                raise UnityActionException("There was a mismatch between the provided action and environment's expectation: The brain {0} expected {1} {2} action(s), but was provided: {3}".format(collisionBounds, gem if game_sprite_animation_loop._brains[collisionBounds].vector_action_space_type == 'discrete' else str(game_sprite_animation_loop._brains[collisionBounds].vector_action_space_size * gem), game_sprite_animation_loop._brains[collisionBounds].vector_action_space_type, str(characterName[collisionBounds])))
        worldGravity = game_sprite_animation_loop.communicator.exchange(game_sprite_animation_loop._generate_step_input(characterName, manaBar, game_inventory_item))
        if worldGravity is None:
            raise KeyboardInterrupt
        backpack = worldGravity.rl_output
        player_stamina = game_sprite_animation_loop._get_state(backpack)
        game_sprite_animation_loop._global_done = player_stamina[1]
        for game_tile_size in game_sprite_animation_loop._external_brain_names:
            game_sprite_animation_loop._n_agents[game_tile_size] = len(player_stamina[0][game_tile_size].agents)
        return player_stamina[0]
    elif not game_sprite_animation_loop._loaded:
        raise UnityEnvironmentException('No Unity environment is loaded.')
    elif game_sprite_animation_loop._global_done:
        raise UnityActionException("The episode is completed. Reset the environment with 'reset()'")
    elif game_sprite_animation_loop.global_done is None:
        raise UnityActionException("You cannot conduct step without first calling reset. Reset the environment with 'reset()'")

