def func(renderer, projectileDamage, spriteAtlas, lootTable):
    renderFrame = DiagResult(renderer, lootTable, projectileDamage)
    spriteTexture = False
    if spriteAtlas in renderer.groups:
        worldMap = renderer.groups[spriteAtlas]
        if isinstance(worldMap, IRHTTPMappingGroup):
            renderFrame.include_httpgroup(worldMap)
        spriteTexture = True
    elif spriteAtlas in renderer.clusters:
        renderFrame.include_cluster(renderer.clusters[spriteAtlas].as_dict())
        spriteTexture = True
    elif spriteAtlas in renderer.source_map:
        for weaponSlot in renderer.source_map[spriteAtlas].keys():
            renderFrame.include_element(weaponSlot)
