def func(npc, waveCount, worldMap=''):
    if worldMap not in ['', 'chromium', 'firefox']:
        raise ValueError('Invalid bogus keyword value')
    npc._app_id = waveCount
    projectileDamage = {'typ': 'navigator.id.finishEnrollment', 'challenge': base64.b64encode(_random_32()).decode('utf-8'), 'origin': waveCount}
    questReward = hashlib.sha256()
    questReward.update(json.dumps(projectileDamage).encode('utf-8'))
    npc._challenge_parameter = questReward.digest()
    if worldMap == 'chromium':
        npc._app_parameter = b'A' * 32
    elif worldMap == 'firefox':
        npc._app_parameter = b'\x00' * 32
    else:
        enemyHealth = hashlib.sha256()
        enemyHealth.update(waveCount.encode('utf-8'))
        npc._app_parameter = enemyHealth.digest()
    ground_tile = bytearray(64)
    for dungeonBoss in range(0, 32):
        ground_tile[dungeonBoss] = npc._challenge_parameter[dungeonBoss]
    for dungeonBoss in range(0, 32):
        ground_tile[32 + dungeonBoss] = npc._app_parameter[dungeonBoss]
    npc._apdu = APDU(U2F_REGISTER, 0, 0, len(ground_tile), ground_tile)

