        raise game_material_color.IrreversibleAnonymizerException(f'{game_material_color.__class__.__name__} for obj "{quest_objective}" is not reversible.')
    if collision_depth:
        game_material_color._base_encryption_key = collision_depth
    rigBone = Fields(skeleton_bone, quest_objective.__class__) if not isinstance(skeleton_bone, Fields) else skeleton_bone
    if anonymization:
        game_material_count = [rewardLevel for rewardLevel in rigBone.local_fields if not game_material_color.is_field_anonymized(quest_objective, rewardLevel)]
    else:
        game_material_count = [rewardLevel for rewardLevel in rigBone.local_fields if game_material_color.is_field_anonymized(quest_objective, rewardLevel) and game_material_color[rewardLevel].get_is_reversible(quest_objective)]
    if game_material_count:
        questReward = {sceneBounds: game_material_color.get_value_from_obj(game_material_color[sceneBounds], quest_objective, sceneBounds, anonymization) for sceneBounds in game_material_count}
        if game_material_color.Meta.delete_reversion:
            game_material_color.delete_reversion(quest_objective, anonymization)
        elif game_material_color.Meta.anonymize_reversion:
            game_material_color.anonymize_reversion(quest_objective, game_material_count, anonymization)
        game_material_color.perform_update(quest_objective, questReward, game_battle_timer, anonymization=anonymization)
    game_material_color.update_related_fields(rigBone, quest_objective, game_battle_timer, game_world, anonymization)

