def func(ballSpeed, warrior, item_amount):
    mana_potion = warrior[item_amount]
    game_atlas_width = mana_potion.team
    game_quest_reward_points = (mana_potion.x, mana_potion.y)
    scene_bounds = {(game_bow.x, game_bow.y) for game_bow in warrior.values() if game_bow.team == game_atlas_width}
    game_atlas_frame = {(game_bow.x, game_bow.y) for game_bow in warrior.values() if game_bow.team != game_atlas_width}
    def next_to_enemy(spell_count):
        return any((game_bow in game_atlas_frame for game_bow in positions_around(spell_count[0], spell_count[1])))
    def cellval(spell_count):
        textureIndex, enemy_velocity = spell_count
        if ballSpeed[enemy_velocity][textureIndex] == CELL_WALL or spell_count in scene_bounds:
            return PATH_IMPASSE
        return PATH_PASSABLE
    def pickorder(collisionCount):
        playerPosition, (worldPosition, game_player_input) = collisionCount
        return (playerPosition, game_player_input, worldPosition)
    if not next_to_enemy(game_quest_reward_points):
        game_sprite_atlas = pathfind_from_targets(game_quest_reward_points, [(game_bow.x, game_bow.y) for game_bow in warrior.values() if game_bow.team != game_atlas_width], cellval)
        if game_sprite_atlas:
            _, sprite_height = min(game_sprite_atlas, key=pickorder)
            return sprite_height
    return None

