def func(game_board_cell, status_code=403, playerWeapon=None):
    battleState = [game_board_cell] if isinstance(game_board_cell, str) else list(game_board_cell)
    def decorator(func):
        skeleton = inspect.signature(func)
        for game_texture_region, partySize in enumerate(skeleton.parameters.values()):
            if partySize.name == 'request' or partySize.name == 'websocket':
                spawn_wave = partySize.name
                break
        else:
            raise Exception(f'No "request" or "websocket" argument on function "{func}"')
        if spawn_wave == 'websocket':
            @functools.wraps(func)
            async def websocket_wrapper(*viewport_position, **game_player_weapon_ammo):
                puzzle_piece = game_player_weapon_ammo.get('websocket', viewport_position[game_texture_region] if game_texture_region < len(viewport_position) else None)
                assert isinstance(puzzle_piece, WebSocket)
                if not has_required_scope(puzzle_piece, battleState):
                    await puzzle_piece.close()
                else:
                    await func(*viewport_position, **game_player_weapon_ammo)
            return websocket_wrapper
        elif is_async_callable(func):
            @functools.wraps(func)
            async def async_wrapper(*viewport_position, **game_player_weapon_ammo):
                game_enemy_waypoint = game_player_weapon_ammo.get('request', viewport_position[game_texture_region] if game_texture_region < len(viewport_position) else None)
                assert isinstance(game_enemy_waypoint, Request)
                if not has_required_scope(game_enemy_waypoint, battleState):
                    if playerWeapon is not None:
                        object_velocity = urlencode({'next': str(game_enemy_waypoint.url)})
                        game_world_object_collider = f'{game_enemy_waypoint.url_for(playerWeapon)}?{object_velocity}'
                        return RedirectResponse(url=game_world_object_collider, status_code=303)
                    raise HTTPException(status_code=status_code)
                return await func(*viewport_position, **game_player_weapon_ammo)
            return async_wrapper
        else:
            @functools.wraps(func)
            def sync_wrapper(*viewport_position, **game_player_weapon_ammo):
                game_enemy_waypoint = game_player_weapon_ammo.get('request', viewport_position[game_texture_region] if game_texture_region < len(viewport_position) else None)
                assert isinstance(game_enemy_waypoint, Request)
                if not has_required_scope(game_enemy_waypoint, battleState):
                    if playerWeapon is not None:
                        object_velocity = urlencode({'next': str(game_enemy_waypoint.url)})
                        game_world_object_collider = f'{game_enemy_waypoint.url_for(playerWeapon)}?{object_velocity}'
                        return RedirectResponse(url=game_world_object_collider, status_code=303)
                    raise HTTPException(status_code=status_code)
                return func(*viewport_position, **game_player_weapon_ammo)
            return sync_wrapper
    return decorator

