async def func():
    game_scene_object = docopt(__doc__, version=VERSION)
    if game_scene_object['--limit']:
        game_scene_object['--limit'] = cast_to_int(game_scene_object['--limit'], 'limit')
    if game_scene_object['--time-period']:
        goal_count = {'seconds': 1, 'minutes': 60, 'hours': 3600, 'days': 86400, 'weeks': 604800}
        game_position_vector = game_scene_object['--time-period'].split('*')
        if game_position_vector[1] not in goal_count:
            raise TgEraserException('Time period is specified incorrectly.')
    if game_scene_object['--kill']:
        if os.name != 'posix':
            raise TgEraserException("You can't use '--kill' option on Windows.")
        mesh_position = subprocess.Popen(['ps', '-A'], stdout=subprocess.PIPE)
        game_weapon_slot = mesh_position.communicate()[0]
        player_action = os.getpid()
        for objectSpeed in game_weapon_slot.splitlines():
            if b'tgeraser' in objectSpeed:
                world_grid = int(objectSpeed.split(None, 1)[0])
                if player_action != world_grid:
                    os.kill(world_grid, signal.SIGKILL)
                    print('Process ' + str(world_grid) + ' successfully killed.')
        sys.exit(0)
    try:
        inventoryLimit = await get_credentials(game_scene_object)
        game_quest_dungeon_room = {**inventoryLimit, 'peers': game_scene_object['--peers'], 'limit': game_scene_object['--limit'], 'wipe_everything': game_scene_object['--wipe-everything'], 'entity_type': game_scene_object['--entity-type']}
        game_battle = Eraser(**inventoryLimit)
        while True:
            await game_battle.init(**game_quest_dungeon_room)
            await game_battle.run()
            if game_scene_object['--time-period']:
                print('\n({0})\tNext erasing will be in {1} {2}.'.format(time.strftime('%Y-%m-%d, %H:%M:%S', time.gmtime()), game_position_vector[0], game_position_vector[1]))
                await asyncio.sleep(int(game_position_vector[0]) * goal_count[game_position_vector[1]])
            else:
                break
        await game_battle.disconnect()
    except asyncio.CancelledError as err:
        print('\n\nCancelled by user.\n', file=sys.stderr)
    except Exception as err:
        raise TgEraserException(err) from err

def func(viewport, chest_loot=Tolerance.DEFAULT):
    spriteOpacity, material_count = max(((sprite_index, game_ball_speed) for sprite_index in range(4) for game_ball_speed in range(4)), key=lambda viewportHeight: abs(viewport[viewportHeight]))
    character = np.zeros((2, 2), dtype=np.complex128)
    body_gravity = np.zeros((2, 2), dtype=np.complex128)
    for sprite_index in range(2):
        for game_ball_speed in range(2):
            character[spriteOpacity >> 1 ^ sprite_index, material_count >> 1 ^ game_ball_speed] = viewport[spriteOpacity ^ sprite_index << 1, material_count ^ game_ball_speed << 1]
            body_gravity[spriteOpacity & 1 ^ sprite_index, material_count & 1 ^ game_ball_speed] = viewport[spriteOpacity ^ sprite_index, material_count ^ game_ball_speed]
    character /= np.sqrt(np.linalg.det(character)) or 1
    body_gravity /= np.sqrt(np.linalg.det(body_gravity)) or 1
    camera_zoom = viewport[spriteOpacity, material_count] / (character[spriteOpacity >> 1, material_count >> 1] * body_gravity[spriteOpacity & 1, material_count & 1])
    if np.real(camera_zoom) < 0:
        character *= -1
        camera_zoom = -camera_zoom
    game_ball_velocity = camera_zoom * combinators.kron(character, body_gravity)
    if np.any(np.isnan(game_ball_velocity)) or not chest_loot.all_close(game_ball_velocity, viewport):
        raise ValueError("Can't factor into kronecker product.")
    return (camera_zoom, character, body_gravity)

