def func(terrainMap, game_item_weight):
    sprite_animation = max(game_item_weight / 2.0, 1.0)
    backpack = min(max(game_item_weight * 2.0, 1.0), 4194304)
    if terrainMap < 0.001:
        return int(backpack)
    player_debuff = game_item_weight / terrainMap
    if player_debuff > backpack:
        return int(backpack)
    if player_debuff < sprite_animation:
        return int(sprite_animation)
    return int(player_debuff)

def func(damageType):
    if len(damageType[0]) != next_power_of_2(len(damageType[0])):
        damageType = [extend_to_power_of_2(inventory_weight) for inventory_weight in damageType]
    vertexPosition = b''.join(damageType)
    vertexPosition += b'\x00' * (CHUNKSIZE - (len(vertexPosition) % CHUNKSIZE or CHUNKSIZE))
    assert len(vertexPosition) % CHUNKSIZE == 0
    magic = len(damageType).to_bytes(32, 'big')
    shop_price = [vertexPosition[game_player_movement_path:game_player_movement_path + CHUNKSIZE] for game_player_movement_path in range(0, len(vertexPosition), CHUNKSIZE)]
    shop_price = [None] * next_power_of_2(len(shop_price)) + shop_price + [b'\x00' * CHUNKSIZE]
    for game_player_movement_path in range(len(shop_price) // 2 - 1, 0, -1):
        shop_price[game_player_movement_path] = hash(shop_price[game_player_movement_path * 2] + shop_price[game_player_movement_path * 2 + 1])
    return hash(shop_price[1] + magic)

