def func(questStage, item_stack, objective_progress):
    itemCount = objective_progress.cookies.get(questStage.session_cookie_name)
    if not itemCount:
        return questStage.session_class()
    spawnPosition = item_stack.config['SESSION_CRYPTO_KEY'] if 'SESSION_CRYPTO_KEY' in item_stack.config else item_stack.crypto_key
    gem_color = itemCount.split('.')
    if len(gem_color) != 4:
        return questStage.session_class()
    try:
        if gem_color[0] == 'z':
            spawn_point = True
        else:
            spawn_point = False
        questProgress = base64.b64decode(bytes(gem_color[1], 'utf-8'))
        itemType = base64.b64decode(bytes(gem_color[2], 'utf-8'))
        shop = base64.b64decode(bytes(gem_color[3], 'utf-8'))
        merchantStock = AES.new(spawnPosition, AES.MODE_EAX, shop)
        coin_value = merchantStock.decrypt_and_verify(questProgress, itemType)
        if spawn_point:
            coin_value = zlib.decompress(coin_value)
        dungeon_room = pickle.loads(coin_value)
        return questStage.session_class(dungeon_room)
    except (ValueError, _pickle.UnpicklingError, pickle.UnpicklingError, AttributeError, ModuleNotFoundError):
        return questStage.session_class()

