def func(game_quest_reward, spawn_delay, animation_speed, object_bounce=[], game_player_gold=True):
    spawn_delay = np.array(spawn_delay)
    game_world_collision_normal = spawn_delay.shape[1]
    game_loot = np.zeros((game_world_collision_normal,))
    game_quest_reward.replace = game_player_gold
    for score_board in range(0, game_world_collision_normal):
        if np.in1d(score_board, object_bounce):
            model, player_position = game_quest_reward.compute_woe(game_quest_reward.discretize(spawn_delay[:, score_board]), animation_speed)
        else:
            model, player_position = game_quest_reward.compute_woe(spawn_delay[:, score_board], animation_speed)
        if game_quest_reward.replace:
            spawn_delay[:, score_board] = model
        game_loot[score_board] = player_position
    if game_quest_reward.replace:
        return (spawn_delay, game_loot)
    else:
        return game_loot

