def func(game_quest_objective_position, game_quest_item_rarity):
    if not game_quest_objective_position._codepoints:
        raise RuntimeError('cannot load hangul. chars not initialized, yet!')
    with open(game_quest_item_rarity, 'r', encoding='utf-8') as game_quest_item_stack:
        game_quest_item_bonus = re.compile('^\\s*[0-9]+\\s*0x([0-9A-Fa-f]{4,6})\\s+.*\\((.+)\\)\\s*$')
        for game_quest_loot_item in game_quest_item_stack:
            game_quest_loot_item = game_quest_loot_item.strip()
            game_quest_item_weight = game_quest_item_bonus.match(game_quest_loot_item)
            if game_quest_item_weight is None:
                continue
            game_quest_item_slot = hex2id(game_quest_item_weight.group(1))
            assert game_quest_item_slot is not None
            if game_quest_item_slot >= len(game_quest_objective_position._codepoints):
                continue
            game_quest_item_index = game_quest_item_weight.group(2)
            game_quest_item_price = game_quest_objective_position.get_codepoint(game_quest_item_slot)
            assert game_quest_item_price is not None
            if game_quest_item_price.name() == '<unassigned>':
                game_quest_item_price.set_name(game_quest_item_index)

def func(func, waveCount=None):
    if waveCount is None:
        waveCount = Registry.default()
    game_quest_item_slot = signature(func)
    game_chest_level = {ground_tile: waveCount.get(spriteTexture.annotation) or spriteTexture.annotation for ground_tile, spriteTexture in game_quest_item_slot.parameters.items() if spriteTexture.annotation is not Parameter.empty}
    @wraps(func)
    def wrapper(*inventoryWeight, **game_quest_stage):
        projectileDamage = game_quest_item_slot.bind(*inventoryWeight, **game_quest_stage)
        projectileDamage.apply_defaults()
        dungeonFloor = {}
        for ground_tile, hitboxOffset in game_chest_level.items():
            try:
                projectileDamage.arguments[ground_tile] = hitboxOffset(projectileDamage.arguments[ground_tile])
            except ValueError as exc:
                dungeonFloor[ground_tile] = str(exc)
        if dungeonFloor:
            raise ConversionError(**dungeonFloor)
        return func(*projectileDamage.args, **projectileDamage.kwargs)
    return wrapper

