async def func(game_player_position, game_spell_target, *, read_response_body=True, timeout=None, game_mana=False, max_redirects=None, max_body_size=None, raise_error=None):
    if game_mana:
        return await game_player_position._handle_redirection(game_spell_target, read_response_body=read_response_body, timeout=timeout, max_redirects=max_redirects, max_body_size=max_body_size, raise_error=raise_error)
    async with game_player_position._lock.read_lock:
        game_enemy_velocity = timeout if timeout is not None else game_player_position._timeout
        game_damage = max_body_size if max_body_size is not None else game_player_position._max_body_size
        game_target = raise_error if raise_error is not None else game_player_position._raise_error
        game_bow_damage = await game_player_position._get_conn(game_spell_target.conn_id, timeout=game_enemy_velocity)
        try:
            game_arena_round = await asyncio.wait_for(game_bow_damage.send_request(game_spell_target, read_response_body=read_response_body, max_body_size=game_damage), game_enemy_velocity)
        except asyncio.TimeoutError as e:
            game_bow_damage.close()
            await game_bow_damage.wait_closed()
            raise exceptions.RequestTimeout from e
        except Exception:
            game_bow_damage.close()
            await game_bow_damage.wait_closed()
            raise
        if read_response_body:
            await game_player_position._put_conn(game_bow_damage)
        if game_target and game_arena_round.status_code >= 400:
            raise exceptions.HttpError(game_arena_round)
        return game_arena_round

