def func(game_quest_item_type, game_quest_item_price, game_quest_reward_item=None, game_quest_item_stack=False, dtype=np.float64):
    game_quest_item_level = False
    if game_quest_reward_item is None:
        game_quest_reward_item = game_quest_item_price
        game_quest_item_level = True
    game_quest_item_amount = np.zeros((len(game_quest_item_price), len(game_quest_reward_item)), dtype=dtype)
    if game_quest_item_stack:
        game_quest_item = np.array([game_quest_item_type(game_quest_item_name, game_quest_item_name) for game_quest_item_name in game_quest_item_price], dtype=dtype)
        game_quest_item_count = game_quest_item if game_quest_item_level else np.array([game_quest_item_type(game_quest_item_name, game_quest_item_name) for game_quest_item_name in game_quest_reward_item], dtype=dtype)
    for game_quest_objective_index, game_quest_item_bonus in enumerate(game_quest_item_price):
        for game_quest_stage_name, game_quest_item_weight in enumerate(game_quest_reward_item):
            game_quest_item_effect = (game_quest_item[game_quest_objective_index] * game_quest_item_count[game_quest_stage_name]) ** 0.5 if game_quest_item_stack else 1.0
            if game_quest_item_level and game_quest_objective_index > game_quest_stage_name:
                game_quest_item_amount[game_quest_objective_index, game_quest_stage_name] = game_quest_item_amount[game_quest_stage_name, game_quest_objective_index]
            else:
                game_quest_item_amount[game_quest_objective_index, game_quest_stage_name] = game_quest_item_type(game_quest_item_bonus, game_quest_item_weight) / game_quest_item_effect
    return game_quest_item_amount

