def func(weapon_cooldown, game_boss_cooldown):
    game_sprite_animation_duration = 0
    weapon_cooldown._fields_ = set()
    jump_force = sorted(weapon_cooldown._field_map.items(), key=lambda enemyVelocity: len(enemyVelocity[0].mro()))
    for animationClip, texture_data in weapon_cooldown.__dict__.get('_layout_', {}).items():
        if animationClip not in weapon_cooldown.__annotations__:
            raise ValueError('{} is not annotated'.format(animationClip))
        mesh_scale = weapon_cooldown.__annotations__[animationClip]
        for field_type, material in jump_force:
            if issubclass(mesh_scale, field_type):
                textureCount = material(texture_data, field_type=mesh_scale)
                if hasattr(textureCount, '__set_name__'):
                    textureCount.__set_name__(weapon_cooldown, animationClip)
                setattr(weapon_cooldown, animationClip, textureCount)
                weapon_cooldown._fields_.add(animationClip)
                if hasattr(textureCount, '_end_of_field'):
                    game_sprite_animation_duration = max(game_sprite_animation_duration, textureCount._end_of_field)
                break
        else:
            raise ValueError('{} is not registered'.format(mesh_scale.__name__))
    if game_boss_cooldown is not None:
        weapon_cooldown._size_ = game_boss_cooldown
    if weapon_cooldown._size_ == 0:
        weapon_cooldown._size_ = game_sprite_animation_duration
    if weapon_cooldown._size_ < game_sprite_animation_duration:
        raise ValueError('Size of {} must be larger then {} bytes'.format(weapon_cooldown.__name__, game_sprite_animation_duration))

