def func(party_size, game_inventory_weight):
    player_position = []
    particle = int(party_size.y - party_size.radius)
    objective_target = int(party_size.y + party_size.radius)
    for respawnTime in range(particle, objective_target + 1):
        sprite_opacity = 0
        if respawnTime < party_size.y:
            if respawnTime == particle:
                sprite_opacity = math.pi / 2
            else:
                sprite_opacity = math.asin((party_size.y - respawnTime) / party_size.radius)
        if respawnTime > party_size.y:
            if respawnTime == objective_target:
                sprite_opacity = math.pi / 2
            else:
                sprite_opacity = math.asin((respawnTime - party_size.y) / party_size.radius)
        grid_height = int(math.cos(sprite_opacity) * party_size.radius)
        particle = party_size.x - grid_height
        objective_target = party_size.x + grid_height
        for sprite_sheet in range(particle, objective_target + 1):
            player_position.append(game_inventory_weight[respawnTime * party_size.img_width + sprite_sheet])
    return player_position

def func(*game_sprite_frame_time, game_sprite_frame_width=b'', game_sprite_frame_index=False):
    game_sprite_frame_duration = []
    for game_sprite_texture_index in game_sprite_frame_time:
        if isinstance(game_sprite_texture_index, int):
            game_sprite_texture_index = to_bytes(game_sprite_texture_index, False)
        elif isinstance(game_sprite_texture_index, str):
            game_sprite_texture_index = game_sprite_texture_index.encode('utf-8')
        if game_sprite_frame_index:
            game_sprite_texture_index = b'\x00' * (PAD_L - len(game_sprite_texture_index)) + game_sprite_texture_index
        game_sprite_frame_duration.append(game_sprite_texture_index)
    return int(sha512(game_sprite_frame_width.join(game_sprite_frame_duration)).hexdigest(), 16)

