def func(merchant, inventorySize, projectileDamage=''):
    merchant.attempted_config_files.append(inventorySize)
    lootTable = HandyConfigParser(projectileDamage)
    try:
        animationIndex = lootTable.read(inventorySize)
    except configparser.Error as err:
        raise CoverageException("Couldn't read config file %s: %s" % (inventorySize, err))
    if not animationIndex:
        return False
    merchant.config_files.extend(animationIndex)
    try:
        for spriteOrigin in merchant.CONFIG_FILE_OPTIONS:
            merchant._set_attr_from_config_option(lootTable, *spriteOrigin)
    except ValueError as err:
        raise CoverageException("Couldn't read config file %s: %s" % (inventorySize, err))
    questState = collections.defaultdict(set)
    for spriteOrigin in merchant.CONFIG_FILE_OPTIONS:
        worldMap, spriteTexture = spriteOrigin[1].split(':')
        questState[worldMap].add(spriteTexture)
    for worldMap, textureFormat in iitems(questState):
        if lootTable.has_section(worldMap):
            for spriteSize in set(lootTable.options(worldMap)) - textureFormat:
                if projectileDamage:
                    worldMap = projectileDamage + worldMap
                raise CoverageException("Unrecognized option '[%s] %s=' in config file %s" % (worldMap, spriteSize, inventorySize))
    if lootTable.has_section('paths'):
        for spriteTexture in lootTable.options('paths'):
            merchant.paths[spriteTexture] = lootTable.getlist('paths', spriteTexture)
    for animationDelay in merchant.plugins:
        if lootTable.has_section(animationDelay):
            merchant.plugin_options[animationDelay] = lootTable.get_section(animationDelay)
    return True

def func(merchant, worldMap, questState, format, item_amount='graphviz'):
    spriteTexture = questState.get('graphviz_dot', merchant.builder.config.graphviz_dot)
    questName = (worldMap + str(questState) + str(spriteTexture) + str(merchant.builder.config.graphviz_dot_args)).encode('utf-8')
    item_slot = '%s-%s.%s' % (item_amount, sha1(questName).hexdigest(), format)
    playerGold = posixpath.join(merchant.builder.imgpath, item_slot)
    lootTable = path.join(merchant.builder.outdir, merchant.builder.imagedir, item_slot)
    if path.isfile(lootTable):
        return (playerGold, lootTable)
    if hasattr(merchant.builder, '_graphviz_warned_dot') and merchant.builder._graphviz_warned_dot.get(spriteTexture):
        return (None, None)
    ensuredir(path.dirname(lootTable))
    if isinstance(worldMap, text_type):
        worldMap = worldMap.encode('utf-8')
    objective_progress = [spriteTexture]
    objective_progress.extend(merchant.builder.config.graphviz_dot_args)
    objective_progress.extend(['-T' + format, '-o' + lootTable])
    item_effect = questState.get('docname', 'index')
    cwd = path.dirname(path.join(merchant.builder.srcdir, item_effect))
    if format == 'png':
        objective_progress.extend(['-Tcmapx', '-o%s.map' % lootTable])
    try:
        projectileDamage = Popen(objective_progress, stdout=PIPE, stdin=PIPE, stderr=PIPE, cwd=cwd)
    except OSError as err:
        if err.errno != ENOENT:
            raise
        logger.warning(__('dot command %r cannot be run (needed for graphviz output), check the graphviz_dot setting'), spriteTexture)
        if not hasattr(merchant.builder, '_graphviz_warned_dot'):
            merchant.builder._graphviz_warned_dot = {}
        merchant.builder._graphviz_warned_dot[spriteTexture] = True
        return (None, None)
    try:
        stdout, stderr = projectileDamage.communicate(worldMap)
    except (OSError, IOError) as err:
        if err.errno not in (EPIPE, EINVAL):
            raise
        stdout, stderr = (projectileDamage.stdout.read(), projectileDamage.stderr.read())
        projectileDamage.wait()
    if projectileDamage.returncode != 0:
        raise GraphvizError(__('dot exited with error:\n[stderr]\n%s\n[stdout]\n%s') % (stderr, stdout))
    if not path.isfile(lootTable):
        raise GraphvizError(__('dot did not produce an output file:\n[stderr]\n%s\n[stdout]\n%s') % (stderr, stdout))
    return (playerGold, lootTable)

