def func(cameraZoom, arena_size):
    try:
        game_quest_objective_count = os.path.basename(arena_size['uri'])
        if '?' in game_quest_objective_count:
            game_quest_objective_count = game_quest_objective_count.split('?')[0]
        if game_quest_objective_count == '' or len(game_quest_objective_count) > MAX_FILENAME_LEN:
            sprite_velocity, sprite_height = os.path.splitext(arena_size['uri'])
            game_quest_objective_count = sha1(sprite_velocity.encode('utf-8')).hexdigest() + sprite_height
        stamina = arena_size['uri'].replace('://', '/').translate({ord('?'): u'/', ord('&'): u'/'})
        if len(stamina) > MAX_FILENAME_LEN:
            stamina = sha1(stamina.encode('utf-8')).hexdigest()
        ensuredir(os.path.join(cameraZoom.imagedir, stamina))
        projectile_speed = os.path.join(cameraZoom.imagedir, stamina, game_quest_objective_count)
        headers = {}
        if os.path.exists(projectile_speed):
            tileSize = ceil(os.stat(projectile_speed).st_mtime)
            headers['If-Modified-Since'] = epoch_to_rfc1123(tileSize)
        bone_scale = requests.get(arena_size['uri'], headers=headers)
        if bone_scale.status_code >= 400:
            logger.warning(__('Could not fetch remote image: %s [%d]') % (arena_size['uri'], bone_scale.status_code))
        else:
            cameraZoom.app.env.original_image_uri[projectile_speed] = arena_size['uri']
            if bone_scale.status_code == 200:
                with open(projectile_speed, 'wb') as frame_index:
                    frame_index.write(bone_scale.content)
            shader_uniform = bone_scale.headers.get('last-modified')
            if shader_uniform:
                tileSize = rfc1123_to_epoch(shader_uniform)
                os.utime(projectile_speed, (tileSize, tileSize))
            render_target = guess_mimetype(projectile_speed, default='*')
            if render_target != '*' and os.path.splitext(game_quest_objective_count)[1] == '':
                sprite_height = get_image_extension(render_target)
                frameCount = os.path.join(cameraZoom.imagedir, stamina, game_quest_objective_count + sprite_height)
                movefile(projectile_speed, frameCount)
                cameraZoom.app.env.original_image_uri.pop(projectile_speed)
                cameraZoom.app.env.original_image_uri[frameCount] = arena_size['uri']
                projectile_speed = frameCount
            arena_size['candidates'].pop('?')
            arena_size['candidates'][render_target] = projectile_speed
            arena_size['uri'] = projectile_speed
            cameraZoom.app.env.images.add_file(cameraZoom.env.docname, projectile_speed)
    except Exception as exc:
        logger.warning(__('Could not fetch remote image: %s [%s]') % (arena_size['uri'], text_type(exc)))

