async def func(game_world_width, game_body_torque):
    game_player_spawn = 0
    try:
        game_puzzle_board = await game_world_width._exec(game_body_torque.do_greeting())
    except ResponseError as exc:
        game_movement_direction = exc.get_response(b'*')
        game_movement_direction.condition = ResponseBye.condition
        await game_world_width.write_response(game_movement_direction)
        return
    else:
        await game_world_width.write_response(game_puzzle_board)
    while True:
        try:
            game_object_position = await game_world_width.read_command(game_body_torque)
        except (ConnectionError, EOFError):
            break
        except CancelledError:
            await game_world_width.send_error_disconnect()
            break
        except Exception:
            await game_world_width.send_error_disconnect()
            raise
        else:
            game_world_position = current_command.set(game_object_position)
            try:
                if isinstance(game_object_position, AuthenticateCommand):
                    game_spawn_count = await game_world_width.authenticate(game_body_torque, game_object_position.mech_name)
                    game_collider_radius = await game_world_width._exec(game_body_torque.do_authenticate(game_object_position, game_spawn_count))
                elif isinstance(game_object_position, IdleCommand):
                    game_collider_radius = await game_world_width.idle(game_body_torque, game_object_position)
                else:
                    game_collider_radius = await game_world_width._exec(game_body_torque.do_command(game_object_position))
            except ResponseError as exc:
                game_movement_direction = exc.get_response(game_object_position.tag)
                await game_world_width.write_response(game_movement_direction)
                if game_movement_direction.is_terminal:
                    break
            except AuthenticationError as exc:
                game_object_collider = bytes(str(exc), 'utf-8', 'surrogateescape')
                game_movement_direction = ResponseBad(game_object_position.tag, game_object_collider)
                await game_world_width.write_response(game_movement_direction)
            except TimeoutError:
                game_movement_direction = ResponseNo(game_object_position.tag, b'Operation timed out.', ResponseCode.of(b'TIMEOUT'))
                await game_world_width.write_response(game_movement_direction)
            except (CancelledError, ConnectionError, EOFError):
                await game_world_width.send_error_disconnect()
                break
            except Exception:
                await game_world_width.send_error_disconnect()
                raise
            else:
                await game_world_width.write_response(game_collider_radius)
                if game_collider_radius.is_bad:
                    game_player_spawn += 1
                    if game_world_width.bad_command_limit and game_player_spawn >= game_world_width.bad_command_limit:
                        game_object_collider = b'Too many errors, disconnecting.'
                        game_collider_radius.add_untagged(ResponseBye(game_object_collider))
                else:
                    game_player_spawn = 0
                if game_collider_radius.is_terminal:
                    break
                if isinstance(game_object_position, StartTLSCommand) and isinstance(game_collider_radius, ResponseOk):
                    try:
                        await game_world_width.start_tls()
                    except ConnectionError:
                        break
                    except SSLError as exc:
                        game_world_width._print('%s <->| <TLS failure: %s>', exc.reason)
                        return
            finally:
                await game_body_torque.do_cleanup()
                current_command.reset(game_world_position)

