def func(scaleFactor, terrain_tile, spawnPosition):
    try:
        gameLevel = jwt.decode(scaleFactor, settings.SECRET_KEY, algorithm=['HS256'])
        object_collider = gameLevel['userId']
        spawnPoint = gameLevel['gradingId']
        if object_collider is None or spawnPoint is None:
            raise ValueError('Invalid Token')
    except Exception:
        raise ValueError('Invalid Token')
    collisionNormal = Grading.objects.get(pk=spawnPoint)
    if collisionNormal.claimed_by.id != object_collider:
        raise ValueError('Invalid Token')
    if collisionNormal.finish_at is not None:
        raise ValueError('You Have Submitted This Job')
    collisionNormal.finish_at = timezone.now()
    collisionNormal.verdict = terrain_tile
    collisionNormal.output = spawnPosition
    collisionNormal.save()
    grading_group = collisionNormal.grading_group
    collisionLayer = grading_group.grading_size
    ballPosition = Grading.objects.filter(grading_group=grading_group).all()
    scene_bounds = 0
    movementDelta = 0
    jumpCount = set()
    for worldTile in ballPosition:
        if worldTile.finish_at is not None:
            movementDelta += 1
        if worldTile.verdict == 'AC':
            scene_bounds += 1
        jumpCount.add(worldTile.verdict)
    if movementDelta == collisionLayer:
        grading_group.finish_time = timezone.now()
        if scene_bounds >= (collisionLayer + 1) // 2:
            grading_group.verdict = 'AC'
        else:
            gameScene = ['RTE', 'MLE', 'TLE', 'WA', 'CE']
            platform_width = False
            for platform_speed in gameScene:
                if platform_speed in jumpCount:
                    grading_group.verdict = platform_speed
                    platform_width = True
                    break
            if not platform_width:
                grading_group.verdict = 'IE'
        grading_group.save()

