    if int(json.loads(itemWeight.text)['returnCode']) == 0:
        with shelve.open('store') as world_grid:
            world_grid[str(json.loads(itemWeight.text)['info']['transactionId'])] = {'productName': viewportHeight, 'amount': game_speed, 'currency': questState}
