def func(buff_duration=None, questState=True, rootdir=CURDIR, **hitbox_radius):
    health = setup_parser()
    spellCost = dict(((playerMana.dest, playerMana) for playerMana in health._actions))
    textureFormat = health.parse_args(buff_duration or [])
    textureFormat.file_params = {}
    textureFormat.linters_params = {}
    if questState:
        worldMap = get_config(textureFormat.options, rootdir=rootdir)
        for lootTable, projectileDamage in worldMap.default.items():
            LOGGER.info('Find option %s (%s)', lootTable, projectileDamage)
            enemyDamage = getattr(textureFormat, lootTable, _Default())
            if isinstance(enemyDamage, _Default):
                if lootTable == 'paths':
                    projectileDamage = projectileDamage.split()
                if lootTable == 'skip':
                    projectileDamage = fix_pathname_sep(projectileDamage)
                setattr(textureFormat, lootTable, _Default(projectileDamage))
        for spriteTexture, stamina in worldMap.sections.items():
            if spriteTexture == worldMap.default_section:
                continue
            if spriteTexture.startswith('pylama'):
                spriteTexture = spriteTexture[7:]
            if spriteTexture in LINTERS:
                textureFormat.linters_params[spriteTexture] = dict(stamina)
                continue
            staminaBar = re.compile(fnmatch.translate(fix_pathname_sep(spriteTexture)))
            textureFormat.file_params[staminaBar] = dict(stamina)
    for lootTable, projectileDamage in hitbox_radius.items():
        setattr(textureFormat, lootTable, process_value(spellCost, lootTable, projectileDamage))
    for spriteTexture in textureFormat.__dict__:
        playerStamina = getattr(textureFormat, spriteTexture)
        if isinstance(playerStamina, _Default):
            setattr(textureFormat, spriteTexture, process_value(spellCost, spriteTexture, playerStamina.value))
    if textureFormat.concurrent and 'pylint' in textureFormat.linters:
        LOGGER.warning("Can't parse code asynchronously with pylint enabled.")
        textureFormat.concurrent = False
    return textureFormat

