def func(merchant, lootTable, spriteTexture, renderer):
    if lootTable is None:
        return None
    elif isinstance(lootTable, (int, float)) and lootTable >= 0:
        return lootTable
    elif isinstance(lootTable, datetime):
        return lootTable.replace(tzinfo=timezone.utc).timestamp()
    elif isinstance(lootTable, date):
        projectileDamage = datetime(lootTable.year, lootTable.month, lootTable.day)
        return projectileDamage.replace(tzinfo=timezone.utc).timestamp()
    raise ValidationError('The type is not date or datetime')

def func(game_boss_cooldown, projectileSpeed):
    if len(projectileSpeed) == 1:
        return [projectileSpeed]
    else:
        arrow_count = 0
        rig_pose = []
        dungeon_boss = projectileSpeed[:]
        while arrow_count < len(projectileSpeed):
            game_enemy_index = arrow_count
            while game_enemy_index - 1 >= 0:
                projectileSpeed[game_enemy_index - 1], projectileSpeed[game_enemy_index] = (projectileSpeed[game_enemy_index], projectileSpeed[game_enemy_index - 1])
                game_enemy_index -= 1
            gameTick = game_boss_cooldown.permute(projectileSpeed[game_enemy_index + 1:])
            for game_stamina in gameTick:
                game_stamina = [projectileSpeed[game_enemy_index]] + game_stamina
                rig_pose.append(game_stamina)
            arrow_count += 1
            projectileSpeed[:] = dungeon_boss[:]
        return rig_pose

