async def func(accelerationVector, guildName, headers={}, data='', params='', objectGravity=False, proxy=False):
    if len(headers) == 0:
        headers = {'User-Agent': Core.get_user_agent()}
    timeout = aiohttp.ClientTimeout(total=720)
    try:
        if proxy:
            proxy = random.choice(accelerationVector().proxy_list)
            if params != '':
                async with aiohttp.ClientSession(headers=headers, timeout=timeout) as game_mesh_position:
                    async with game_mesh_position.get(guildName, params=params, proxy=proxy) as scene_object:
                        await asyncio.sleep(5)
                        return await scene_object.text() if objectGravity is False else await scene_object.json()
            else:
                async with aiohttp.ClientSession(headers=headers, timeout=timeout) as game_mesh_position:
                    async with game_mesh_position.get(guildName, proxy=proxy) as scene_object:
                        await asyncio.sleep(5)
                        return await scene_object.text() if objectGravity is False else await scene_object.json()
        elif params == '':
            if isinstance(data, str):
                data = json_loader.loads(data)
            async with aiohttp.ClientSession(headers=headers, timeout=timeout) as game_mesh_position:
                async with game_mesh_position.post(guildName, data=data) as game_party_size:
                    await asyncio.sleep(3)
                    return await game_party_size.text() if objectGravity is False else await game_party_size.json()
        else:
