def func(game_sprite_texture_index, game_sprite_count, game_sprite_particle_lifetime):
    game_sprite_animation_loop = game_sprite_particle_lifetime[0]
    game_sprite_bounds_height = game_sprite_particle_lifetime[1]
    game_sprite_origin = game_sprite_particle_lifetime[2]
    game_sprite_animation_state = 1e-06
    game_sprite_texture = game_sprite_bounds_height - game_sprite_animation_loop
    game_sprite_origin_position = game_sprite_origin - game_sprite_animation_loop
    game_sprite_sheet_width = np.cross(game_sprite_count, game_sprite_origin_position)
    game_sprite_rotation_angle = game_sprite_texture.dot(game_sprite_sheet_width)
    if abs(game_sprite_rotation_angle) < game_sprite_animation_state:
        return (False, None)
    game_sprite_texture_scale = 1.0 / game_sprite_rotation_angle
    game_sprite_texture_size = game_sprite_texture_index - game_sprite_animation_loop
    game_sprite_texture_format = game_sprite_texture_size.dot(game_sprite_sheet_width) * game_sprite_texture_scale
    if game_sprite_texture_format < 0.0 or game_sprite_texture_format > 1.0:
        return (False, None)
    game_sprite_scale = np.cross(game_sprite_texture_size, game_sprite_texture)
    game_sprite_render_queue = game_sprite_count.dot(game_sprite_scale) * game_sprite_texture_scale
    if game_sprite_render_queue < 0.0 or game_sprite_texture_format + game_sprite_render_queue > 1.0:
        return (False, None)
    game_sprite_atlas_region = game_sprite_origin_position.dot(game_sprite_scale) * game_sprite_texture_scale
    if game_sprite_atlas_region < game_sprite_animation_state:
        return (False, None)
    return (True, game_sprite_atlas_region)

