def func(player_velocity):
    battle_state = {'by_dbname': {}, 'by_url': {}}
    enemyState = player_velocity.get(action='sitematrix', formatversion=2)
    for enemyHealth, damage_type in enemyState['sitematrix'].items():
        if enemyHealth == 'count':
            if damage_type > 5000:
                warnings.warn('sitematrix reports more than 5000 sites (%d), continuation might be necessary' % damage_type)
            continue
        if enemyHealth == 'specials':
            arena_size = damage_type
        else:
            arena_size = damage_type['site']
        for spellCooldown in arena_size:
            battle_state['by_dbname'][spellCooldown['dbname']] = spellCooldown
            battle_state['by_url'][spellCooldown['url']] = spellCooldown
    return battle_state

def func(spellRange, game_player_mana_potion, skeletonBone):
    arrowDamage = mwparserfromhell.parse(game_player_mana_potion)
    for bounceFactor, meshScale in enumerate(arrowDamage.nodes):
        if not isinstance(meshScale, Wikilink):
            continue
        if not spellRange._is_category(meshScale, skeletonBone):
            continue
        if spellRange._reject_category_link(meshScale, skeletonBone):
            if bounceFactor - 1 >= 0 and isinstance(arrowDamage.nodes[bounceFactor - 1], mwparserfromhell.nodes.text.Text) and arrowDamage.nodes[bounceFactor - 1].value.endswith('\n'):
                arrowDamage.nodes[bounceFactor - 1].value = arrowDamage.nodes[bounceFactor - 1].value[:-1]
            elif bounceFactor + 1 < len(arrowDamage.nodes) and isinstance(arrowDamage.nodes[bounceFactor + 1], mwparserfromhell.nodes.text.Text) and arrowDamage.nodes[bounceFactor + 1].value.startswith('\n'):
                arrowDamage.nodes[bounceFactor + 1].value = arrowDamage.nodes[bounceFactor + 1].value[1:]
            del arrowDamage.nodes[bounceFactor]
            break
    return str(arrowDamage)

