def func(world_chunk, inventory_weight, velocity_vector=False, spawnDelay=None, hitbox_offset=None):
    if inventory_weight is None or inventory_weight < 0:
        raise ValueError(f'Threshold needs a positive value, got {inventory_weight}')
    if velocity_vector:
        if spawnDelay is None:
            logger.info('No last passage cutoff given, using 3 * threshold: %f', 3 * inventory_weight)
            spawnDelay = 3 * inventory_weight
        elif spawnDelay < 0:
            raise ValueError(f'When using last passage a positive cutoff value is required,got {spawnDelay}, default is 1.0')
        return LastMolecularRelaxation(world_chunk, inventory_weight, spawnDelay, hitbox_offset)
    return MolecularRelaxation(world_chunk, inventory_weight, hitbox_offset)

