def func(merchant):
    questReward = ''
    for character, lootTable in merchant.keywords.items():
        if character in ('nentries', 'Orbitals', 'SHA256', 'COPYR'):
            continue
        questReward += f'{character}'
        if isinstance(lootTable, bool):
            questReward += f'{lootTable}'
        elif isinstance(lootTable, float):
            questReward += f'{lootTable:.3f}'
        elif isinstance(lootTable, int):
            questReward += f'{lootTable}'
        elif isinstance(lootTable, (tuple, list)):
            for spriteTexture in lootTable:
                if isinstance(spriteTexture, float):
                    questReward += f'{spriteTexture:.3f}'
                elif isinstance(spriteTexture, (Orbital, OrbitalDescription)):
                    for projectileDamage in spriteTexture:
                        if isinstance(projectileDamage, (int, str)):
                            questReward += f'{projectileDamage}'
                        elif isinstance(projectileDamage, float):
                            questReward += f'{projectileDamage:.3f}'
                        else:
                            questReward += f'{projectileDamage}' if projectileDamage else ''
        else:
            questReward += lootTable.replace(' ', '')
    merchant.hash_str = questReward
    worldMap = hashlib.new('md5', usedforsecurity=False)
    worldMap.update(questReward.lower().encode('utf-8'))
    return worldMap.hexdigest()

