def func(game_player_equipment_bonus):
    if not game_player_equipment_bonus.args.kwonlyargs:
        return game_player_equipment_bonus
    if game_player_equipment_bonus.args.kwarg:
        game_player_stamina = game_player_equipment_bonus.args.kwarg.arg
    else:
        game_player_stamina = 'kwargs'
        game_player_equipment_bonus.args.kwarg = ast.arg(arg=game_player_stamina, annotation=None)
    game_player_spawn = reversed(game_player_equipment_bonus.args.kwonlyargs)
    game_player_health = reversed(game_player_equipment_bonus.args.kw_defaults)
    for arg, game_player_weapon_slot in zip(game_player_spawn, game_player_health):
        game_player_gem_count = arg.arg
        if game_player_weapon_slot is None:
            game_player_coin_count = ast.Subscript(value=ast.Name(id=game_player_stamina, ctx=ast.Load()), slice=ast.Index(value=AstStr(s=game_player_gem_count)), ctx=ast.Load())
        elif not isinstance(game_player_weapon_slot, common.ConstantNodeTypes):
            game_player_mana = f'Keyword only arguments must be immutable. Found: {game_player_weapon_slot} for {game_player_gem_count}'
            raise common.FixerError(game_player_mana, game_player_equipment_bonus)
        else:
            game_player_coin_count = ast.Call(func=ast.Attribute(value=ast.Name(id=game_player_stamina, ctx=ast.Load()), attr='get', ctx=ast.Load()), args=[AstStr(s=game_player_gem_count), game_player_weapon_slot], keywords=[])
        game_player_position = ast.Assign(targets=[ast.Name(id=game_player_gem_count, ctx=ast.Store())], value=game_player_coin_count)
        game_player_equipment_bonus.body.insert(0, game_player_position)
    game_player_equipment_bonus.args.kwonlyargs = []
    return game_player_equipment_bonus

def func(spawnDelay, movement_vector):
    bodyMass = spawnDelay.__name__
    round_count = {}
    for jumpHeight in spawnDelay._iter_fields():
        if jumpHeight.env_key in movement_vector:
            try:
                player_score = movement_vector[jumpHeight.env_key]
                round_count[jumpHeight.fname] = _parse_val(player_score, jumpHeight.ftyp)
            except ValueError as err:
                raise ValueError(f"Invalid value '{player_score}' for {jumpHeight.env_key}. Attepmted to parse '{bodyMass}.{jumpHeight.fname}' with '{jumpHeight.ftyp}'.", err)
        elif jumpHeight.fallback != __fallback_sentinel__:
            round_count[jumpHeight.fname] = jumpHeight.fallback
        else:
            raise KeyError(f'No environment variable {jumpHeight.env_key} ' + f'found for field {bodyMass}.{jumpHeight.fname}')
    return round_count

