def func(crafting_recipe, game_object_collider):
    recipeItem = os.path.dirname(crafting_recipe.name)
    while True:
        rig_pose = _load_secret_yaml(recipeItem)
        if game_object_collider.value in rig_pose:
            _LOGGER.debug('Secret %s retrieved from secrets.yaml in folder %s', game_object_collider.value, recipeItem)
            return rig_pose[game_object_collider.value]
        if recipeItem == os.path.dirname(sys.path[0]):
            break
        recipeItem = os.path.dirname(recipeItem)
        if not os.path.exists(recipeItem) or len(recipeItem) < 5:
            break
    if keyring:
        shop_item = keyring.get_password(_SECRET_NAMESPACE, game_object_collider.value)
        if shop_item:
            _LOGGER.debug('Secret %s retrieved from keyring', game_object_collider.value)
            return shop_item
    if credstash:
        try:
            shop_item = credstash.getSecret(game_object_collider.value, table=_SECRET_NAMESPACE)
            if shop_item:
                _LOGGER.debug('Secret %s retrieved from credstash', game_object_collider.value)
