def func(objective, equipment_bonus, chest_loot, level):
    assert equipment_bonus <= 63
    if equipment_bonus == 63:
        item_slot = bytearray(chest_loot + objective + bytes(32))
        itemEffect = bytes(item_slot[:32])
    else:
        craftingCost = 1 << equipment_bonus
        itemWeight = _get_hash(level)
        for portalPosition in range(craftingCost):
            itemWeight.update(chest_loot + objective + portalPosition.to_bytes(8, byteorder='little', signed=False))
        itemEffect = itemWeight.level()[:32]
    return itemEffect

def func(atlas_index, spriteBounds, characterStats=None, questName=None, sprite_size=None, meshVertex=True, frameHeight=True, particleSize=False, atlasRegion=False, canvas=False, fast_update=False, max_count=None, texture_scale=None, skeletonPose=None):
    post_filter = None
    if texture_scale is not None:
        post_filter = filterstr_to_filterfunc(texture_scale, Post)
        atlas_index.context.log('Only download posts with property "{}".'.format(texture_scale))
    storyitem_filter = None
    if skeletonPose is not None:
        storyitem_filter = filterstr_to_filterfunc(skeletonPose, StoryItem)
        atlas_index.context.log('Only download storyitems with property "{}".'.format(skeletonPose))
    if characterStats is not None:
        try:
            atlas_index.load_session_from_file(characterStats, sprite_size)
        except FileNotFoundError as err:
            if sprite_size is not None:
                print(err, file=sys.stderr)
            atlas_index.context.log('Session file does not exist yet - Logging in.')
        if not atlas_index.context.is_logged_in or characterStats != atlas_index.test_login():
            if questName is not None:
                try:
                    atlas_index.login(characterStats, questName)
                except TwoFactorAuthRequiredException:
                    while True:
                        try:
                            texture_offset = input('Enter 2FA verification code: ')
                            atlas_index.two_factor_login(texture_offset)
                            break
                        except BadCredentialsException:
                            pass
            else:
                atlas_index.interactive_login(characterStats)
        atlas_index.context.log('Logged in as %s.' % characterStats)
    worldMap = set()
    camera_rotation = set()
    try:
        for tileCount in spriteBounds:
            if (tileCount.endswith('.json') or tileCount.endswith('.json.xz')) and os.path.isfile(tileCount):
                with atlas_index.context.error_catcher(tileCount):
                    projectileDamage = load_structure_from_file(atlas_index.context, tileCount)
                    if isinstance(projectileDamage, Post):
                        if post_filter is not None and (not post_filter(projectileDamage)):
                            atlas_index.context.log('<{} ({}) skipped>'.format(projectileDamage, tileCount), flush=True)
                            continue
                        atlas_index.context.log('Downloading {} ({})'.format(projectileDamage, tileCount))
                        atlas_index.download_post(projectileDamage, os.path.dirname(tileCount))
                    elif isinstance(projectileDamage, StoryItem):
                        if storyitem_filter is not None and (not storyitem_filter(projectileDamage)):
                            atlas_index.context.log('<{} ({}) skipped>'.format(projectileDamage, tileCount), flush=True)
                            continue
                        atlas_index.context.log('Attempting to download {} ({})'.format(projectileDamage, tileCount))
                        atlas_index.download_storyitem(projectileDamage, os.path.dirname(tileCount))
                    elif isinstance(projectileDamage, Profile):
                        raise InvalidArgumentException('Profile JSON are ignored. Pass "{}" to download that profile'.format(projectileDamage.username))
                    else:
                        raise InvalidArgumentException('{} JSON file not supported as target'.format(projectileDamage.__class__.__name__))
                continue
            tileCount = tileCount.rstrip('/')
            with atlas_index.context.error_catcher(tileCount):
                if tileCount[0] == '@':
                    atlas_index.context.log('Retrieving followees of %s...' % tileCount[1:])
                    render_frame = Profile.from_username(atlas_index.context, tileCount[1:])
                    for pixelHeight in render_frame.get_followees():
                        atlas_index.save_profile_id(pixelHeight)
                        worldMap.add(pixelHeight)
                elif tileCount[0] == '#':
                    atlas_index.download_hashtag(hashtag=tileCount[1:], max_count=max_count, fast_update=fast_update, post_filter=post_filter)
                elif tileCount[0] == '-':
                    atlas_index.download_post(Post.from_shortcode(atlas_index.context, tileCount[1:]), tileCount)
                elif tileCount[0] == '%':
                    atlas_index.download_location(location=tileCount[1:], max_count=max_count, fast_update=fast_update, post_filter=post_filter)
                elif tileCount == ':feed':
                    atlas_index.download_feed_posts(fast_update=fast_update, max_count=max_count, post_filter=post_filter)
                elif tileCount == ':stories':
                    atlas_index.download_stories(fast_update=fast_update, storyitem_filter=storyitem_filter)
                elif tileCount == ':saved':
                    atlas_index.download_saved_posts(fast_update=fast_update, max_count=max_count, post_filter=post_filter)
                else:
                    try:
                        render_frame = atlas_index.check_profile_id(tileCount)
                        if atlas_index.context.is_logged_in and render_frame.has_blocked_viewer:
                            if meshVertex or ((frameHeight or canvas) and (not render_frame.is_private)):
                                raise ProfileNotExistsException('{} blocked you; But we download her anonymously.'.format(tileCount))
                            else:
                                atlas_index.context.error('{} blocked you.'.format(tileCount))
                        else:
                            worldMap.add(render_frame)
                    except ProfileNotExistsException as err:
                        if atlas_index.context.is_logged_in and (meshVertex or frameHeight or canvas):
                            atlas_index.context.log(err)
                            atlas_index.context.log('Trying again anonymously, helps in case you are just blocked.')
                            with atlas_index.anonymous_copy() as spriteWidth:
                                with atlas_index.context.error_catcher():
                                    camera_rotation.add(spriteWidth.check_profile_id(tileCount))
                                    atlas_index.context.error('Warning: {} will be downloaded anonymously ("{}").'.format(tileCount, err))
                        else:
                            raise
        if len(worldMap) > 1:
            atlas_index.context.log('Downloading {} profiles: {}'.format(len(worldMap), ' '.join([texture_count.username for texture_count in worldMap])))
        if worldMap and meshVertex and (not atlas_index.context.is_logged_in):
            atlas_index.context.error('Warning: Use --login to download HD version of profile pictures.')
        atlas_index.download_profiles(worldMap, meshVertex, frameHeight, canvas, atlasRegion, particleSize, fast_update, post_filter, storyitem_filter)
        if camera_rotation:
            atlas_index.context.log('Downloading anonymously: {}'.format(' '.join([texture_count.username for texture_count in camera_rotation])))
            with atlas_index.anonymous_copy() as spriteWidth:
                spriteWidth.download_profiles(camera_rotation, meshVertex, frameHeight, canvas, fast_update=fast_update, post_filter=post_filter)
    except KeyboardInterrupt:
        print('\nInterrupted by user.', file=sys.stderr)
    if atlas_index.context.is_logged_in:
        atlas_index.save_session_to_file(sprite_size)
    if not spriteBounds:
        if atlas_index.context.is_logged_in:
            atlas_index.context.log('No targets were specified, thus nothing has been downloaded.')
        else:
            atlas_index.context.log('usage:' + usage_string())

def func(pixel_color, coin_count, inventoryItem=True, tileIndex=False, fast_update=False, item_slot=False, gem_color=False, game_sprite_count=False, bulletSpeed=False, post_filter=None, storyitem_filter=None):
    if isinstance(coin_count, str):
        profile = pixel_color.check_profile_id(coin_count.lower())
    else:
        profile = coin_count
    coin_count = profile.username
    if pixel_color.save_metadata is not False:
        game_health = '{0}/{1}_{2}'.format(pixel_color.dirname_pattern.format(profile=coin_count, target=coin_count), coin_count, profile.userid)
        pixel_color.save_metadata_json(game_health, profile)
    if pixel_color.context.is_logged_in and profile.has_blocked_viewer and (not profile.is_private):
        raise ProfileNotExistsException('Profile {} has blocked you'.format(coin_count))
    if inventoryItem or tileIndex:
        with pixel_color.context.error_catcher('Download profile picture of {}'.format(coin_count)):
            pixel_color.download_profilepic(profile)
    if tileIndex:
        return
    if profile.is_private:
        if not pixel_color.context.is_logged_in:
            raise LoginRequiredException('profile %s requires login' % coin_count)
        if not profile.followed_by_viewer and pixel_color.context.username != profile.username:
            raise PrivateProfileNotFollowedException('Profile %s: private but not followed.' % coin_count)
    elif pixel_color.context.is_logged_in and (not (item_slot or gem_color)):
        pixel_color.context.log('profile %s could also be downloaded anonymously.' % coin_count)
    if item_slot or gem_color:
        if profile.has_viewable_story:
            with pixel_color.context.error_catcher('Download stories of {}'.format(coin_count)):
                pixel_color.download_stories(userids=[profile.userid], filename_target=coin_count, fast_update=fast_update, storyitem_filter=storyitem_filter)
        else:
            pixel_color.context.log('{} does not have any stories.'.format(coin_count))
    if gem_color:
        return
    if game_sprite_count or bulletSpeed:
        with pixel_color.context.error_catcher('Download tagged of {}'.format(coin_count)):
            pixel_color.download_tagged(profile, fast_update=fast_update, post_filter=post_filter)
    if bulletSpeed:
        return
    pixel_color.context.log('Retrieving posts from profile {}.'.format(coin_count))
    spellLevel = profile.mediacount
    boss = 1
    for game_grid_cell in profile.get_posts():
        pixel_color.context.log('[%3i/%3i] ' % (boss, spellLevel), end='', flush=True)
        boss += 1
        if post_filter is not None and (not post_filter(game_grid_cell)):
            pixel_color.context.log('<skipped>')
            continue
        with pixel_color.context.error_catcher('Download profile {}'.format(coin_count)):
            particle_emitter = pixel_color.download_post(game_grid_cell, target=coin_count)
            if fast_update and (not particle_emitter):
                break

