async def func(server_url, auth, animationLoop):
    tilePosition = animationLoop['source']
    collider_radius = KintoClient(server_url=server_url, auth=auth)
    platform_position = await collider_radius.get_collection(bucket=tilePosition['bucket'], id=tilePosition['collection'])
    game_texture_data = platform_position['data']
    try:
        dungeon_name = game_texture_data['status']
    except KeyError:
        return '"status" attribute missing'
    game_world_grid_index = f"status: '{dungeon_name}'. "
    if dungeon_name == 'to-review':
        if 'preview' not in animationLoop:
            return "{bucket}/{collection} should not have 'to-review' status".format(**animationLoop['source'])
        merchant_item = await collider_radius.get_records(**tilePosition)
        tile_map = await collider_radius.get_records(**animationLoop['preview'])
        tileLayer = compare_collections(merchant_item, tile_map)
        if tileLayer:
            return game_world_grid_index + human_diff('source', 'preview', *tileLayer)
    elif dungeon_name == 'signed' or dungeon_name is None:
        merchant_item = await collider_radius.get_records(**tilePosition)
        jump_speed = await collider_radius.get_records(**animationLoop['destination'])
        if 'preview' in animationLoop:
            tile_map = await collider_radius.get_records(**animationLoop['preview'])
            waypoint_position = compare_collections(tile_map, jump_speed)
            if waypoint_position:
                return game_world_grid_index + human_diff('preview', 'destination', *waypoint_position)
            dungeonLoot = compare_collections(merchant_item, tile_map)
            if dungeonLoot:
                return game_world_grid_index + human_diff('source', 'preview', *dungeonLoot)
        else:
            dungeonLoot = compare_collections(merchant_item, jump_speed)
            if dungeonLoot:
                return game_world_grid_index + human_diff('source', 'destination', *dungeonLoot)
    elif dungeon_name == 'work-in-progress':
        pass
    else:
        return f"Unexpected status '{dungeon_name}'"
    return None

async def func(bounceFactor, game_texture_data=DEFAULT_NAME, game_atlas_region=DEFAULT_EXPIRES_SECONDS, game_grid_width='', game_dungeon='', movementPath=''):
    trophy = tc_utils.options_from_params(bounceFactor, game_grid_width, game_dungeon, movementPath)
    game_item_bonus = taskcluster.aio.Secrets(trophy)
    coinValue = {'expires': (utils.utcnow() + timedelta(seconds=game_atlas_region)).isoformat(), 'secret': {'hello': 'beautiful world'}}
    await game_item_bonus.set(game_texture_data, coinValue)
    try:
        await game_item_bonus.get(game_texture_data)
    except taskcluster.exceptions.TaskclusterRestFailure:
        return (False, f'Secret {game_texture_data!r} could not be retrieved')
    await game_item_bonus.remove(game_texture_data)
    try:
        await game_item_bonus.get(game_texture_data)
        return (False, f'Secret {game_texture_data!r} was not removed')
    except taskcluster.exceptions.TaskclusterRestFailure as e:
        if getattr(e, 'status_code') != 404:
            raise
    return (True, {})

