async def func(game_renderer):
    spawn_area = {}
    sprite_scale = app_settings['cors_renderer'](game_renderer.request)
    vertexPosition = await sprite_scale.get_settings()
    if not vertexPosition:
        return {}
    game_terrain_tile = game_renderer.request.headers.get('Origin', None)
    if not game_terrain_tile:
        raise HTTPNotFound(content={'message': 'Origin this header is mandatory'})
    world_chunk = game_renderer.getRequestMethod()
    if not world_chunk:
        raise HTTPNotFound(content={'text': 'Access-Control-Request-Method this header is mandatory'})
    inventory_weight = game_renderer.request.headers.get('Access-Control-Request-Headers', ())
    if inventory_weight:
        inventory_weight = map(str.strip, inventory_weight.split(', '))
    world_chunk = world_chunk.upper()
    objectBounce = vertexPosition['allow_methods']
    if world_chunk not in objectBounce:
        raise HTTPMethodNotAllowed(world_chunk, objectBounce, content={'message': 'Access-Control-Request-Method Method not allowed'})
    game_quest_timer = vertexPosition['allow_headers']
    if '*' not in game_quest_timer and inventory_weight:
        game_quest_timer = [cameraTarget.lower() for cameraTarget in game_quest_timer]
        for collider_index in inventory_weight:
            if not collider_index.lower() in game_quest_timer:
                raise HTTPUnauthorized(content={'text': 'Access-Control-Request-Headers Header %s not allowed' % collider_index})
    game_quest_timer = [] if game_quest_timer is None else game_quest_timer
    inventory_weight = [] if inventory_weight is None else inventory_weight
    game_quest_timer = set(game_quest_timer) | set(inventory_weight)
    spawn_area['Access-Control-Allow-Headers'] = ','.join(game_quest_timer)
    spawn_area['Access-Control-Allow-Methods'] = ','.join(vertexPosition['allow_methods'])
    spawn_area['Access-Control-Max-Age'] = str(vertexPosition['max_age'])
