def func(game_sprite_atlas_height, game_sprite_frame_time):
    game_sprite_atlas_height._buffer += game_sprite_frame_time
    log_binary(_LOGGER, 'Received data', Data=game_sprite_frame_time)
    while len(game_sprite_atlas_height._buffer) >= HEADER_LENGTH:
        game_sprite_particle_size = HEADER_LENGTH + int.from_bytes(game_sprite_atlas_height._buffer[1:HEADER_LENGTH], byteorder='big')
        if len(game_sprite_atlas_height._buffer) < game_sprite_particle_size:
            _LOGGER.debug('Require %d bytes but only %d in buffer', game_sprite_particle_size, len(game_sprite_atlas_height._buffer))
            break
        game_sprite_texture_height = game_sprite_atlas_height._buffer[0:HEADER_LENGTH]
        game_sprite_frame_height = game_sprite_atlas_height._buffer[HEADER_LENGTH:game_sprite_particle_size]
        game_sprite_atlas_height._buffer = game_sprite_atlas_height._buffer[game_sprite_particle_size:]
        try:
            if game_sprite_atlas_height._chacha and len(game_sprite_frame_height) > 0:
                game_sprite_frame_height = game_sprite_atlas_height._chacha.decrypt(game_sprite_frame_height, aad=game_sprite_texture_height)
            game_sprite_atlas_height._listener.frame_received(FrameType(game_sprite_texture_height[0]), game_sprite_frame_height)
        except Exception:
            _LOGGER.exception('failed to handle frame')

def func(animation_loop):
    animation_loop.server_name, animation_loop.server_port = animation_loop.server_address
    animation_loop._sockets = []
    if not animation_loop.server_name:
        tile = [(socket.AF_INET6, socket.SOCK_STREAM, '', '', ''), (socket.AF_INET, socket.SOCK_STREAM, '', '', '')]
    else:
        tile = socket.getaddrinfo(animation_loop.server_name, animation_loop.server_port, socket.AF_UNSPEC, socket.SOCK_STREAM, socket.IPPROTO_TCP)
    for atlasWidth in tile:
        animation_loop._logger.info('Create socket on: %r', atlasWidth)
        mesh_rotation, textureFormat, mesh_texture, sprite_rotation, frame_count = atlasWidth
        try:
            materialColor = socket.socket(mesh_rotation, textureFormat)
        except Exception as e:
            animation_loop._logger.info('Skip by failure: %r', e)
            continue
        texture_size = animation_loop.websocket_server_options
        if texture_size.use_tls:
            if texture_size.tls_module == _TLS_BY_STANDARD_MODULE:
                if texture_size.tls_client_auth:
                    if texture_size.tls_client_cert_optional:
                        animation_curve = ssl.CERT_OPTIONAL
                    else:
                        animation_curve = ssl.CERT_REQUIRED
                else:
                    animation_curve = ssl.CERT_NONE
                materialColor = ssl.wrap_socket(materialColor, keyfile=texture_size.private_key, certfile=texture_size.certificate, ssl_version=ssl.PROTOCOL_SSLv23, ca_certs=texture_size.tls_client_ca, cert_reqs=animation_curve, do_handshake_on_connect=False)
        animation_loop._sockets.append((materialColor, atlasWidth))

