        try:
            arrow_damage = await game_sprite_atlas_index.get(viewport_size)
        except KongResponseError as exc:
            if exc.status == 404:
                arrow_damage = await game_sprite_atlas_index.create(**player_direction)
            else:
                raise
        else:
            if player_direction:
                arrow_damage = await game_sprite_atlas_index.update(viewport_size, **game_projectile_count)
