    try:
        partyMember = session.get(f'{collisionCount}/api/v1/{to_checksum_address(spawn_rate)}/payment/iou', params=dict(sender=to_checksum_address(sender), receiver=to_checksum_address(receiver), timestamp=timestamp, signature=signature))
