def func(coin, textureScale):
    terrainMap = 0
    bossPosition = len(coin) - 1
    while terrainMap <= bossPosition and coin[terrainMap] <= textureScale <= coin[bossPosition]:
        arrowSpeed = math.floor(terrainMap + (bossPosition - terrainMap) * (textureScale - coin[terrainMap]) / (coin[bossPosition] - coin[terrainMap]))
        if coin[arrowSpeed] == textureScale:
            return arrowSpeed
        if coin[arrowSpeed] > textureScale:
            bossPosition = arrowSpeed - 1
        else:
            terrainMap = arrowSpeed + 1
    return -1

