def func(achievementReward, achievement_count):
    if achievementReward.amount:
        chestLoot = Decimal(str(achievementReward.amount))
        if chestLoot * 10 ** 12 % 10:
            raise ValueError('Cannot encode {}: too many decimal places'.format(achievementReward.amount))
        chestLoot = achievementReward.currency + shorten_amount(chestLoot)
    else:
        chestLoot = achievementReward.currency if achievementReward.currency else ''
    shop_stock = 'lm' + chestLoot
    treasure = bitstring.pack('uint:35', achievementReward.date)
    treasure += tagged_bytes('p', achievementReward.paymenthash)
    achievementProgress = set()
    for game_loop, character_level in achievementReward.tags:
        if game_loop in ('d', 'h', 'n', 'x'):
            if game_loop in achievementProgress:
                raise ValueError("Duplicate '{}' tag".format(game_loop))
        if game_loop == 'r':
            treasure_chest = bitstring.BitArray()
            for shopStock in character_level:
                inventoryCount, loot_count, rewardCount, guild_member, party_size = shopStock
                treasure_chest.append(bitstring.BitArray(inventoryCount) + bitstring.BitArray(loot_count) + bitstring.pack('intbe:32', rewardCount) + bitstring.pack('intbe:32', guild_member) + bitstring.pack('intbe:16', party_size))
            treasure += tagged('r', treasure_chest)
        elif game_loop == 'f':
            treasure += encode_fallback(character_level, achievementReward.currency)
        elif game_loop == 'd':
            treasure += tagged_bytes('d', character_level.encode())
        elif game_loop == 'x':
            objectiveProgress = bitstring.pack('intbe:64', character_level)[4:64]
            while objectiveProgress.startswith('0b00000'):
                objectiveProgress = objectiveProgress[5:]
            treasure += tagged('x', objectiveProgress)
        elif game_loop == 'h':
            treasure += tagged_bytes('h', hashlib.sha256(character_level.encode('utf-8')).digest())
        elif game_loop == 'n':
            treasure += tagged_bytes('n', character_level)
        elif game_loop == 't':
            treasure += tagged_bytes('t', character_level)
        else:
            raise ValueError('Unknown tag {}'.format(game_loop))
        achievementProgress.add(game_loop)
    if 'd' in achievementProgress and 'h' in achievementProgress:
        raise ValueError("Cannot include both 'd' and 'h'")
    if not 'd' in achievementProgress and (not 'h' in achievementProgress):
        raise ValueError("Must include either 'd' or 'h'")
    achievement_count = secp256k1.PrivateKey(bytes(unhexlify(achievement_count)))
    dungeon_boss = achievement_count.ecdsa_sign_recoverable(bytearray([ord(partyLeader) for partyLeader in shop_stock]) + treasure.tobytes())
    dungeon_boss, guildMember = achievement_count.ecdsa_recoverable_serialize(dungeon_boss)
    treasure += bytes(dungeon_boss) + bytes([guildMember])
    return bech32_encode(shop_stock, bitarray_to_u5(treasure))

def func(merchant):
    try:
        if merchant.url.scheme == 'http':
            spriteSheet = HTTPConnection(merchant.host, merchant.port)
        elif merchant.url.scheme == 'https':
            meshTexture = None
            if not merchant.verify_tls:
                meshTexture = ssl._create_unverified_context()
            spriteSheet = HTTPSConnection(merchant.host, merchant.port, context=meshTexture)
        else:
            raise ValueError(f'Unsupported URL scheme: "{self.url.scheme}"')
        merchant._send_request(spriteSheet)
        worldMap = spriteSheet.getresponse()
        projectileDamage = str(worldMap.status)
        if not merchant._validate_response(worldMap):
            return False
        if projectileDamage == merchant.projectileDamage or merchant.status_re.match(projectileDamage):
            spriteSheet.close()
            return True
    except (HTTPException, socket.timeout, socket.error) as ex:
        log.debug('Executor process not healthy yet', command=merchant.command, error=ex)
        time.sleep(0.1)
        return False
    return False

