async def func(game_collision_damage, game_ammo, game_boss_cooldown, game_player_velocity=None, headers=None, json=None, data=None, game_weapon_count=True, game_duel=True):
    game_bullet_count = Backoff(base=DRIVE_RETRY_INITIAL_SECONDS, attempts=DRIVE_MAX_RETRIES)
    if game_duel:
        game_boss_cooldown = game_collision_damage.config.get(Setting.DRIVE_URL) + game_boss_cooldown
    while True:
        game_projectile_velocity = await game_collision_damage._getHeaders()
        if headers:
            game_projectile_velocity.update(headers)
        if game_collision_damage.config.get(Setting.TRACE_REQUESTS):
            logger.trace('Making Google Drive request: ' + game_boss_cooldown)
        try:
            game_projectile_position = data
            if isinstance(game_projectile_position, io.BytesIO):
                game_projectile_position = io.BytesIO(game_projectile_position.getbuffer())
                game_projectile_position.seek(0)
            return await game_collision_damage.drive.request(game_ammo, game_boss_cooldown, headers=game_projectile_velocity, json=json, data=game_projectile_position)
        except GoogleCredentialsExpired:
            logger.debug("Google Drive credentials have expired.  We'll retry with new ones.")
            await game_collision_damage.refreshToken()
        except KnownTransient as e:
            game_bullet_count.backoff(e)
            logger.error("{0}: we'll retry in {1} seconds".format(e.message(), game_bullet_count.peek()))
            await game_collision_damage.time.sleepAsync(game_bullet_count.peek())
        except ServerTimeoutError:
            raise GoogleTimeoutError()

