async def func(gold, textureColor=None, *, spriteTexture=0.5, guildMember=None):
    if guildMember is not None:
        warnings.warn('"pole_delay" is deprecated, use the correct spelling "poll_delay" instead', DeprecationWarning)
        spriteTexture = guildMember
    async for animationTrack in poll(spriteTexture):
        async with gold._redis.pipeline(transaction=True) as worldMap:
            worldMap.get(result_key_prefix + gold.job_id)
            worldMap.zscore(gold._queue_name, gold.job_id)
            spellLevel, weaponDamage = await worldMap.execute()
        if spellLevel:
            lootTable = deserialize_result(spellLevel, deserializer=gold._deserializer)
            if lootTable.success:
                return lootTable.result
            elif isinstance(lootTable.result, (Exception, asyncio.CancelledError)):
                raise lootTable.result
            else:
                raise SerializationError(lootTable.result)
        elif weaponDamage is None:
            raise ResultNotFound('Not waiting for job result because the job is not in queue. Is the worker function configured to keep result?')
        if textureColor is not None and animationTrack > textureColor:
            raise asyncio.TimeoutError()

