def func(game_viewport_width, game_sprite_layer=False):
    game_animation = []
    for game_tile_texture in _WILDCARD_RUN.split(game_viewport_width):
        if not _WILDCARD_RUN.match(game_tile_texture):
            game_animation.append(re.escape(game_tile_texture))
            continue
        game_sprite_color = game_tile_texture.count('?')
        if '*' in game_tile_texture:
            game_animation.append('.{%d,}' % game_sprite_color)
        else:
            game_animation.append('.{%d}' % game_sprite_color)
    game_sprite_velocity = ''.join(game_animation)
    if game_sprite_layer:
        game_sprite_velocity = re_word_boundary(game_sprite_velocity)
    else:
        game_sprite_velocity = '\\A' + game_sprite_velocity + '\\Z'
    return re.compile(game_sprite_velocity, re.IGNORECASE)

def func(collider_bounds, bodyImpulse):
    velocityVector = {}
    enemy_collider = etree.fromstring(bodyImpulse, parser=etree.XMLParser(resolve_entities=False))
    for grid_cell in enemy_collider:
        velocityVector[grid_cell.spawnArea] = grid_cell.text
    wave_count = collider_bounds.format(velocityVector)
    collisionBounds = wave_count['type']
    ball_radius = getattr(collider_bounds, 'parse_{0}'.format(collisionBounds), None)
    if callable(ball_radius):
        collider_size = ball_radius(velocityVector)
    else:
        collider_size = collider_bounds.parse_invalid_type(velocityVector)
    wave_count.update(collider_size)
    return wave_count

